{"command": "cd /workspace && cat > src/term.rs <<'RSEOF'
//! Terminal size detection.
//!
//! Mirrors what the shell completion/help machinery does to figure out how wide
//! the help text is allowed to be: the width of stdout when it is a terminal,
//! falling back to the `COLUMNS` environment variable, and finally to a
//! sensible default.

const DEFAULT_WIDTH: usize = 100;

#[repr(C)]
struct WinSize {
    rows: u16,
    cols: u16,
    xpixel: u16,
    ypixel: u16,
}

extern "C" {
    fn ioctl(fd: i32, request: u64, ...) -> i32;
}

const TIOCGWINSZ: u64 = 0x5413;

/// Width of the terminal attached to stdout, in columns.
fn stdout_width() -> Option<usize> {
    let mut ws = WinSize {
        rows: 0,
        cols: 0,
        xpixel: 0,
        ypixel: 0,
    };
    let rc = unsafe { ioctl(1, TIOCGWINSZ, &mut ws as *mut WinSize) };
    if rc == 0 && ws.cols != 0 {
        Some(ws.cols as usize)
    } else {
        None
    }
}

fn env_width(name: &str) -> Option<usize> {
    std::env::var_os(name)?.to_str()?.parse::<usize>().ok()
}

/// The width to use when formatting help output.
pub fn width() -> usize {
    stdout_width()
        .or_else(|| env_width("COLUMNS"))
        .unwrap_or(DEFAULT_WIDTH)
}
RSEOF
