{"command": "cd /workspace && cat > src/log.rs <<'RSEOF'
//! Simple logging, mirroring the `RUST_LOG` directives of the standard
//! `env_logger` crate, with a fixed non-coloured output format.

use std::io::Write;
use std::sync::OnceLock;
use std::time::{SystemTime, UNIX_EPOCH};

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum Level {
    Off = 0,
    Error = 1,
    Warn = 2,
    Info = 3,
    Debug = 4,
    Trace = 5,
}

impl Level {
    fn parse(s: &str) -> Option<Level> {
        // Level names are matched case insensitively, as well as numbers.
        Some(match s.to_ascii_lowercase().as_str() {
            "off" => Level::Off,
            "error" | "1" => Level::Error,
            "warn" | "2" => Level::Warn,
            "info" | "3" => Level::Info,
            "debug" | "4" => Level::Debug,
            "trace" | "5" => Level::Trace,
            _ => return None,
        })
    }
}

struct Directive {
    name: Option<String>,
    level: Level,
}

static DIRECTIVES: OnceLock<Vec<Directive>> = OnceLock::new();

/// `parse_spec` of `env_logger`: `target=level,other=level`.
fn parse_spec(spec: &str) -> (Vec<Directive>, Vec<String>) {
    let mut directives = Vec::new();
    let mut errors = Vec::new();

    let mut parts = spec.split('/');
    let mods = parts.next();
    if let Some(_filter) = parts.next() {
        // Only the first `/` separated part is the module list.
    }
    if let Some(m) = mods {
        for s in m.split(',').map(|ss| ss.trim()) {
            if s.is_empty() {
                continue;
            }
            let mut parts = s.split('=');
            let (level, name) = match (parts.next(), parts.next().map(|s| s.trim()), parts.next()) {
                (Some(part0), None, None) => match Level::parse(part0) {
                    Some(num) => (num, None),
                    None => (Level::Trace, Some(part0)),
                },
                (Some(part0), Some(""), None) => (Level::Trace, Some(part0)),
                (Some(part0), Some(part1), None) => match Level::parse(part1) {
                    Some(num) => (num, Some(part0)),
                    None => {
                        errors.push(format!("invalid logging spec '{part1}', ignoring it"));
                        continue;
                    }
                },
                _ => {
                    errors.push(format!("invalid logging spec '{s}', ignoring it"));
                    continue;
                }
            };
            directives.push(Directive {
                name: name.map(|s| s.to_owned()),
                level,
            });
        }
    }
    (directives, errors)
}

fn directives() -> &'static Vec<Directive> {
    DIRECTIVES.get_or_init(|| {
        let mut directives;
        let mut errors = Vec::new();
        match std::env::var("RUST_LOG") {
            Ok(spec) => {
                let (d, e) = parse_spec(&spec);
                errors = e;
                directives = d;
            }
            Err(_) => directives = Vec::new(),
        }
        if directives.is_empty() {
            // No directives at all: everything defaults to errors.
            directives.push(Directive {
                name: None,
                level: Level::Info,
            });
