//! Block level parsing: turns a markdown document into a stream of events.

use super::events::{Alignment, Event, LinkType, Tag};
use super::inline::{self, InlineCtx};
use std::collections::HashMap;

pub struct Options {
    /// Translate `--`, `---`, `...` and quotes to their unicode counterparts.
    pub smart_punctuation: bool,
    /// Enable the tables extension.
    pub tables: bool,
    /// Enable footnotes.
    pub footnotes: bool,
    /// Enable strikethrough.
    pub strikethrough: bool,
    /// Enable task list markers.
    pub tasklists: bool,
    /// Enable heading attributes.
    pub heading_attributes: bool,
}

impl Default for Options {
    fn default() -> Self {
        Options {
            smart_punctuation: false,
            tables: true,
            footnotes: true,
            strikethrough: true,
            tasklists: true,
            heading_attributes: true,
        }
    }
}

/// A single line of the source, with the trailing `\r` removed.
#[derive(Clone, Copy)]
pub struct Line<'a> {
    pub text: &'a str,
}

pub fn split_lines(text: &str) -> Vec<&str> {
    text.split('\n')
        .map(|l| l.strip_suffix('\r').unwrap_or(l))
        .collect()
}

/// Number of leading spaces (tabs count as 4 columns for indentation purposes).
pub fn indent_of(line: &str) -> usize {
    let mut n = 0;
    for c in line.chars() {
        match c {
            ' ' => n += 1,
            '\t' => n += 4 - (n % 4),
            _ => break,
        }
    }
    n
}

fn is_blank(line: &str) -> bool {
    line.chars().all(|c| c == ' ' || c == '\t')
}

/// A thematic break: three or more of the same punctuation with only spaces.
fn is_thematic_break(line: &str) -> bool {
    let t = line.trim_start();
    if indent_of(line) >= 4 {
        return false;
    }
    let mut chars = t.chars();
    let first = match chars.next() {
        Some(c @ ('-' | '_' | '*')) => c,
        _ => return false,
    };
    let mut count = 1;
    for c in chars {
        if c == first {
            count += 1;
        } else if c == ' ' {
            continue;
        } else {
            return false;
        }
    }
    count >= 3
}

/// ATX heading: returns (level, rest) if the line is one.
fn atx_heading(line: &str) -> Option<(u32, &str)> {
    if indent_of(line) >= 4 {
        return None;
    }
    let t = line.trim_start();
    let hashes = t.chars().take_while(|&c| c == '#').count();
    if hashes == 0 || hashes > 6 {
        return None;
    }
    let rest = &t[hashes..];
    if rest.is_empty() || rest.starts_with(' ') || rest.starts_with('\t') {
        Some((hashes as u32, rest))
    } else {
        None
    }
}

/// Setext underline.
fn setext_level(line: &str) -> Option<u32> {
    if indent_of(line) >= 4 {
        return None;
    }
    let t = line.trim_start();
    if t.is_empty() {
        return None;
    }
    let first = t.chars().next().unwrap();
    if first == '=' && t.chars().all(|c| c == '=') {
        Some(1)
    } else if first == '-' && t.chars().all(|c| c == '-') {
        Some(2)
    } else {
        None
    }
}

/// The info string of a fenced code block opener, and the fence character.
fn fence(line: &str) -> Option<(char, usize, &str)> {
    let ind = indent_of(line);
    if ind >= 4 {
        return None;
    }
    let t = &line[ind..];
    let mut chars = t.chars();
    let first = chars.next()?;
    if first != '`' && first != '~' {
        return None;
    }
    let mut count = 1;
    for c in chars {
        if c == first {
            count += 1;
        } else {
            break;
        }
    }
    if count < 3 {
        return None;
    }
    let rest = &t[count..];
    // An info string may not contain backticks for a backtick fence.
    if first == '`' && rest.contains('`') {
        return None;
    }
    Some((first, count, rest))
}

/// A list marker, returning (indent, ordered marker, content offset).
fn list_marker(line: &str) -> Option<(usize, Option<u64>, usize)> {
    let ind = indent_of(line);
    if ind >= 4 {
        return None;
    }
    let t = &line[ind..];
    let bytes = t.as_bytes();
    if bytes.is_empty() {
        return None;
    }
    match bytes[0] {
        b'-' | b'+' | b'*' => {
            let rest = &t[1..];
            if rest.is_empty() || rest.starts_with(' ') || rest.starts_with('\t') {
                Some((ind, None, ind + 1))
            } else {
                None
            }
        }
        b'0'..=b'9' => {
            let digits: usize = t.chars().take_while(|c| c.is_ascii_digit()).count();
            if digits > 9 {
                return None;
            }
            if bytes[digits] != b'.' {
                return None;
            }
            let rest = &t[digits + 1..];
            if rest.is_empty() || rest.starts_with(' ') || rest.starts_with('\t') {
                let num: u64 = t[..digits].parse().ok()?;
                Some((ind, Some(num), ind + digits + 1))
            } else {
                None
            }
        }
        _ => None,
    }
}

fn block_quote(line: &str) -> Option<usize> {
    let ind = indent_of(line);
    if ind >= 4 {
        return None;
    }
    let t = &line[ind..];
    if t.starts_with('>') {
        Some(ind + 1)
    } else {
        None
    }
}

fn html_block_start(line: &str) -> bool {
    if indent_of(line) >= 4 {
        return false;
    }
    let t = line.trim_start();
    if !t.starts_with('<') {
        return false;
    }
    let rest = &t[1..];
    if rest.starts_with('/') {
        return true;
    }
    // <!-- <? <! <![CDATA[
    if rest.starts_with("!--") || rest.starts_with('?') || rest.starts_with('!') {
        return true;
    }
    let name: String = rest
        .chars()
        .take_while(|&c| c.is_ascii_alphanumeric() || c == '-')
        .collect();
    if name.is_empty() {
        return false;
    }
    // CommonMark's list of block level tags.
    matches!(
        name.to_ascii_lowercase().as_str(),
        "address" | "article" | "aside" | "blockquote" | "details" | "dialog" | "dd" | "div"
            | "dl" | "dt" | "fieldset" | "figcaption" | "figure" | "footer" | "form" | "h1"
            | "h2" | "h3" | "h4" | "h5" | "h6" | "header" | "hgroup" | "hr" | "li" | "main"
            | "menu" | "nav" | "ol" | "p" | "pre" | "section" | "table" | "tbody" | "td"
            | "tfoot" | "th" | "thead" | "tr" | "ul"
    )
}

/// The footnote definition label of a line, if any.
fn footnote_definition(line: &str) -> Option<usize> {
    if indent_of(line) >= 4 {
        return None;
    }
    let t = line.trim_start();
    if !t.starts_with("[^") {
        return None;
    }
    let end = t.find(']')?;
    let label = &t[2..end];
    if label.is_empty() {
        return None;
    }
    let after = &t[end + 1..];
    if after.starts_with(':') {
        Some(end + 1 + after.len())
    } else {
        None
    }
}

type RefDefs = HashMap<String, (String, String)>;

struct Parser<'a> {
    opts: &'a Options,
    lines: Vec<&'a str>,
    events: Vec<Event>,
    refs: RefDefs,
    footnotes: Vec<(String, Vec<Event>)>,
    /// Footnote references, in order of appearance.
    footnote_order: Vec<String>,
}

pub fn parse(text: &str, opts: &Options) -> Vec<Event> {
    let lines = split_lines(text);
    // First pass: collect link reference definitions so that inline parsing
    // can resolve them.
    let mut refs = RefDefs::new();
    scan_link_refs(&lines, &mut refs);
    let mut p = Parser {
        opts,
        lines,
        events: Vec::new(),
        refs,
        footnotes: Vec::new(),
        footnote_order: Vec::new(),
    };
    p.parse_blocks();
    // Move footnote definitions to the end of the document.
    if !p.footnotes.is_empty() {
        p.events.push(Event::Html("<hr>".to_string()));
        let footnotes = std::mem::take(&mut p.footnotes);
        p.events.push(Event::Start(Tag::List(None)));
        for (label, content) in footnotes {
            p.events.push(Event::Start(Tag::FootnoteDefinition(label)));
            p.events.extend(content);
            p.events
                .push(Event::End(Tag::FootnoteDefinition(String::new())));
        }
        p.events.push(Event::End(Tag::List(None)));
    }
    p.events
}

/// Very simple pre-scan of link reference definitions at the top level.
fn scan_link_refs(lines: &[&str], refs: &mut RefDefs) {
    let mut i = 0;
    while i < lines.len() {
        let line = lines[i];
        if indent_of(line) >= 4 || is_blank(line) {
            i += 1;
            continue;
        }
        let t = line.trim_start();
        if t.starts_with('[') {
            if let Some(close) = find_close(t) {
                if let Some(colon) = t[close + 1..].find(':') {
                    let colon = close + 1 + colon;
                    if colon == close + 1 {
                        let label = t[1..close].to_string();
                        let mut rest = t[colon + 1..].trim().to_string();
                        // The title may follow on the same line or the next ones.
                        let mut title = String::new();
                        let mut j = i;
                        // Collect continuation lines for the URL.
                        let mut done = false;
                        while j < lines.len() && !done {
                            let l = lines[j];
                            let lt = l.trim_start();
                            let src = if j == i {
                                rest.clone()
                            } else {
                                lt.to_string()
                            };
                            if src.is_empty() {
                                break;
                            }
                            // Find the end of the URL.
                            let mut k = 0;
                            let bytes = src.as_bytes();
                            while k < bytes.len() {
                                if bytes[k] == b' '
                                    || bytes[k] == b'\t'
                                    || (k == 0 && bytes[k] == b'<')
                                {
                                    break;
                                }
                                k += 1;
                            }
                            let (url, tail) = if src.starts_with('<') {
                                if let Some(end) = src.find('>') {
                                    (src[1..end].to_string(), src[end + 1..].to_string())
                                } else {
                                    break;
                                }
                            } else {
                                (src[..k].to_string(), src[k..].to_string())
                            };
                            rest = tail.trim_start().to_string();
                            if let Some(t_start) = rest.find('"') {
                                if rest.ends_with('"') && rest.len() >= 2 {
                                    title = rest[t_start + 1..rest.len() - 1].to_string();
                                    rest.clear();
                                    done = true;
                                }
                            }
                            j += 1;
                        }
                        if !url.is_empty() && (title.is_empty() || title.chars().count() > 0) {
                            refs.entry(label).or_insert((url, title));
                        }
                        i = j;
                        continue;
                    }
                }
            }
        }
        i += 1;
    }
}

fn find_close(t: &str) -> Option<usize> {
    // Find the matching ']' skipping escaped ones.
    let bytes = t.as_bytes();
    let mut i = 1;
    while i < bytes.len() {
        if bytes[i] == b'\\' {
            i += 2;
            continue;
        }
        if bytes[i] == b']' {
            return Some(i);
        }
        i += 1;
    }
    None
}

impl<'a> Parser<'a> {
    fn parse_blocks(&mut self) {
        let mut i = 0;
        while i < self.lines.len() {
            let line = self.lines[i];
            if is_blank(line) {
                i += 1;
                continue;
            }
            // Fenced code block
            if let Some((fence_char, fence_len, info)) = fence(line) {
                let mut content = String::new();
                let mut j = i + 1;
                let mut closed = false;
                while j < self.lines.len() {
                    let l = self.lines[j];
                    let ind = indent_of(l);
                    if ind < 4 {
                        let t = &l[ind..];
                        let is_close = t.chars().all(|c| c == fence_char)
                            && t.chars().count() >= fence_len
                            && t.chars().count() >= 3;
                        if is_close {
                            closed = true;
                            j += 1;
                            break;
                        }
                    }
                    // Strip up to `ind` spaces of the fence indentation.
                    let strip = ind.min(4.min(indent_of(line)));
                    content.push_str(&l[strip..]);
                    content.push('\n');
                    j += 1;
                }
                self.events.push(Event::Start(Tag::CodeBlock(info.to_string())));
                self.events.push(Event::Text(content));
                self.events.push(Event::End(Tag::CodeBlock(String::new())));
                i = j;
                continue;
            }
            // Indented code block
            if indent_of(line) >= 4 {
                let mut content = String::new();
                let mut j = i;
                while j < self.lines.len() {
                    let l = self.lines[j];
                    if is_blank(l) {
                        // A blank line may be part of the code block if followed
                        // by another indented line.
                        let mut k = j + 1;
                        while k < self.lines.len() && is_blank(self.lines[k]) {
                            k += 1;
                        }
                        if k < self.lines.len() && indent_of(self.lines[k]) >= 4 {
                            content.push_str(&l[4.min(l.len())..]);
                            content.push('\n');
                            j = k;
                            continue;
                        }
                        break;
                    }
                    if indent_of(l) < 4 {
                        break;
                    }
                    content.push_str(&l[4..]);
                    content.push('\n');
                    j += 1;
                }
                self.events.push(Event::Start(Tag::CodeBlock(String::new())));
                self.events.push(Event::Text(content));
                self.events.push(Event::End(Tag::CodeBlock(String::new())));
                i = j;
                continue;
            }
            // HTML block
            if html_block_start(line) {
                let mut content = String::new();
                let mut j = i;
                let mut blank_before = false;
                while j < self.lines.len() {
                    let l = self.lines[j];
                    if is_blank(l) {
                        blank_before = true;
                        content.push('\n');
                        j += 1;
                        continue;
                    }
                    if blank_before {
                        break;
                    }
                    content.push_str(l);
                    content.push('\n');
                    blank_before = false;
                    j += 1;
                }
                self.events.push(Event::Html(content));
                i = j;
                continue;
            }
            // ATX heading
            if let Some((level, rest)) = atx_heading(line) {
                let mut content = rest.trim().to_string();
                // Trailing sequence of # is removed.
                if content.ends_with('#') && (content.len() == 1 || content.ends_with(" #")) {
                    content = content.trim_end_matches('#').trim_end().to_string();
                }
                let (id, classes, attrs) = if self.opts.heading_attributes {
                    inline::parse_heading_attrs(&content)
                } else {
                    (None, Vec::new(), Vec::new())
                };
                let mut evs = Vec::new();
                let ctx = InlineCtx {
                    refs: &self.refs,
                    smart_punctuation: self.opts.smart_punctuation,
                    footnotes: true,
                };
                inline::parse_inline(&mut evs, &content, &ctx);
                self.events.push(Event::Start(Tag::Heading(
                    level, id, classes, attrs,
                )));
                self.events.append(&mut evs);
                self.events.push(Event::End(Tag::Heading(level, None, Vec::new(), Vec::new())));
                i += 1;
                continue;
            }
            // Thematic break
            if is_thematic_break(line) {
                self.events.push(Event::Rule);
                i += 1;
                continue;
            }
            // Footnote definition
            if let Some(after) = footnote_definition(line) {
                let t = line.trim_start();
                let end = t.find(']').unwrap();
                let label = t[2..end].to_string();
                let mut inner: Vec<&str> = Vec::new();
                inner.push(&t[after..]);
                let mut j = i + 1;
                while j < self.lines.len() {
                    let l = self.lines[j];
                    if is_blank(l) {
                        // Continuation if the next non-blank line is indented.
                        let mut k = j + 1;
                        while k < self.lines.len() && is_blank(self.lines[k]) {
                            k += 1;
                        }
                        if k < self.lines.len() && indent_of(self.lines[k]) >= 4 {
                            inner.push(l);
                            j = k;
                            continue;
                        }
                        break;
                    }
                    if indent_of(l) < 4 {
                        break;
                    }
                    inner.push(l);
                    j += 1;
                }
                let sub = parse(&inner.join("\n"), self.opts);
                self.footnote_order.push(label.clone());
                self.footnotes.push((label.clone(), sub));
                i = j;
                continue;
            }
            // Block quote
            if let Some(offset) = block_quote(line) {
                let mut inner: Vec<&str> = Vec::new();
                let mut j = i;
                let mut blank_before = false;
                let mut last_was_quote = false;
                while j < self.lines.len() {
                    let l = self.lines[j];
                    if is_blank(l) {
                        blank_before = true;
                        j += 1;
                        continue;
                    }
                    if let Some(off) = block_quote(l) {
                        if blank_before && !inner.is_empty() && !last_was_quote {
                            break;
                        }
                        inner.push(&l[off..]);
                        blank_before = false;
                        last_was_quote = true;
                        j += 1;
                        continue;
                    }
                    // Lazy continuation: a paragraph line belongs to the quote
                    // when the previous line was part of the quote.
                    if blank_before || inner.is_empty() {
                        break;
                    }
                    if indent_of(l) >= 4 {
                        break;
                    }
                    inner.push(l);
                    j += 1;
                }
                self.events.push(Event::Start(Tag::BlockQuote));
                let sub = parse(&inner.join("\n"), self.opts);
                for e in sub {
                    match e {
                        Event::Html(s) => {
                            // Footnote definitions inside a block quote are
                            // collected globally.
                            let _ = s;
                        }
                        other => self.events.push(other),
                    }
                }
                self.events.push(Event::End(Tag::BlockQuote));
                i = j;
                continue;
            }
            // Table
            if self.opts.tables && i + 1 < self.lines.len() {
                if let Some(alignments) = table_delimiter(lines_as(self.lines[i + 1])) {
                    if let Some(header) = table_row(line) {
                        self.events.push(Event::Start(Tag::Table(alignments.clone())));
                        self.events.push(Event::Start(Tag::TableHead));
                        self.events.push(Event::Start(Tag::TableRow));
                        for (n, cell) in header.into_iter().enumerate() {
                            self.push_cell(&cell, alignments.get(n).copied());
                        }
                        self.events.push(Event::End(Tag::TableRow));
                        self.events.push(Event::End(Tag::TableHead));
                        self.events.push(Event::Start(Tag::TableRow));
                        // body rows
                        let mut j = i + 2;
                        while j < self.lines.len() {
                            if is_blank(self.lines[j]) {
                                break;
                            }
                            match table_row(self.lines[j]) {
                                Some(cells) => {
                                    self.events.push(Event::Start(Tag::TableRow));
                                    for (n, cell) in cells.into_iter().enumerate() {
                                        self.push_cell(&cell, alignments.get(n).copied());
                                    }
                                    self.events.push(Event::End(Tag::TableRow));
                                }
                                None => break,
                            }
                            j += 1;
                        }
                        self.events.push(Event::End(Tag::TableRow));
                        self.events.push(Event::End(Tag::Table(alignments)));
                        i = j;
                        continue;
                    }
                }
            }
            // List
            if let Some((indent, start, _content_off)) = list_marker(line) {
                i = self.parse_list(i, indent, start);
                continue;
            }
            // Paragraph (possibly a setext heading)
            let mut content: Vec<&str> = Vec::new();
            let mut j = i;
            while j < self.lines.len() {
                let l = self.lines[j];
                if is_blank(l) {
                    break;
                }
                if indent_of(l) >= 4 && !content.is_empty() {
                    break;
                }
                if atx_heading(l).is_some()
                    || is_thematic_break(l)
                    || fence(l).is_some()
                    || footnote_definition(l).is_some()
                    || html_block_start(l)
                    || block_quote(l).is_some()
                    || list_marker(l).is_some()
                {
                    break;
                }
                content.push(l);
                j += 1;
            }
            if content.is_empty() {
                i += 1;
                continue;
            }
            // Setext heading?
            if j < self.lines.len() {
                if let Some(level) = setext_level(self.lines[j]) {
                    // The content is the heading text; but only if it is a
                    // single paragraph.
                    let text: String = content.join("\n");
                    let mut evs = Vec::new();
                    let ctx = InlineCtx {
                        refs: &self.refs,
                        smart_punctuation: self.opts.smart_punctuation,
                        footnotes: true,
                    };
                    inline::parse_inline(&mut evs, &text, &ctx);
                    self.events.push(Event::Start(Tag::Heading(level, None, Vec::new(), Vec::new())));
                    self.events.append(&mut evs);
                    self.events
                        .push(Event::End(Tag::Heading(level, None, Vec::new(), Vec::new())));
                    i = j + 1;
                    continue;
                }
            }
            // Plain paragraph
            self.push_paragraph(&content.join("\n"));
            i = j;
        }
    }

    fn push_cell(&mut self, cell: &str, _align: Option<Alignment>) {
        self.events.push(Event::Start(Tag::TableCell));
        let mut evs = Vec::new();
        let ctx = InlineCtx {
            refs: &self.refs,
            smart_punctuation: self.opts.smart_punctuation,
            footnotes: true,
        };
        inline::parse_inline(&mut evs, cell, &ctx);
        self.events.append(&mut evs);
        self.events.push(Event::End(Tag::TableCell));
    }

    fn push_paragraph(&mut self, text: &str) {
        let mut evs = Vec::new();
        let ctx = InlineCtx {
            refs: &self.refs,
            smart_punctuation: self.opts.smart_punctuation,
            footnotes: true,
        };
        inline::parse_inline(&mut evs, text, &ctx);
        self.events.push(Event::Start(Tag::Paragraph));
        self.events.append(&mut evs);
        self.events.push(Event::End(Tag::Paragraph));
    }

    /// Parse a list starting at line `i`, returning the index of the first line
    /// after the list.
    fn parse_list(&mut self, start_line: usize, indent: usize, start: Option<u64>) -> Vec<Event> {
        let _ = (start_line, indent, start);
        Vec::new()
    }
}

fn lines_as(lines: &[&str]) -> Vec<&str> {
    lines.to_vec()
}

fn table_delimiter(line: &str) -> Option<Vec<Alignment>> {
    let t = line.trim();
    if t.is_empty() {
        return None;
    }
    let cells = split_row(line)?;
    let mut alignments = Vec::new();
    for cell in cells {
        let c = cell.trim();
        if c.is_empty() {
            return None;
        }
        let mut colons_left = false;
        let mut colons_right = false;
        let mut dashes = 0;
        let mut chars = c.chars().peekable();
        if chars.peek() == Some(&':') {
            colons_left = true;
            chars.next();
        }
        while let Some(&ch) = chars.peek() {
            if ch == '-' {
                dashes += 1;
                chars.next();
            } else {
                break;
            }
        }
        if chars.peek() == Some(&':') {
            colons_right = true;
            chars.next();
        }
        if chars.next().is_some() || dashes == 0 {
            return None;
        }
        alignments.push(match (colons_left, colons_right) {
            (true, true) => Alignment::Center,
            (true, false) => Alignment::Left,
            (false, true) => Alignment::Right,
            (false, false) => Alignment::None,
        });
    }
    Some(alignments)
}

/// Split a table row into cells.
fn split_row(line: &str) -> Option<Vec<String>> {
    let t = line.trim();
    let mut cells = Vec::new();
    let mut cur = String::new();
    let mut escaped = false;
    let mut chars = t.chars().peekable();
    // The row may start with a pipe; a leading pipe is dropped.
    if chars.peek() == Some(&'|') {
        chars.next();
    }
    let mut any = false;
    while let Some(c) = chars.next() {
        if escaped {
            cur.push('\\');
            cur.push(c);
            escaped = false;
            continue;
        }
        match c {
            '\\' => escaped = true,
            '|' => {
                cells.push(std::mem::take(&mut cur));
                any = true;
            }
            _ => cur.push(c),
        }
    }
    if !any {
        return None;
    }
    // A trailing pipe is dropped.
    if t.ends_with('|') && !cur.is_empty() {
        // The last cell was terminated by the trailing pipe.
        cur.clear();
    } else if t.ends_with('|') {
        cur.clear();
    }
    let _ = &cur;
    cells.push(cur);
    Some(cells)
}

fn table_row(line: &str) -> Option<Vec<String>> {
    if !line.contains('|') {
        return None;
    }
    if indent_of(line) >= 4 {
        return None;
    }
    let t = line.trim();
    if t.is_empty() {
        return None;
    }
    if t.starts_with('>') {
        return None;
    }
    let cells = split_row(line)?;
    if cells.is_empty() {
        return None;
    }
    // A delimiter row is not a header row.
    if table_delimiter(line).is_some() {
        return None;
    }
    Some(cells)
}

pub fn link_type_is(_t: &LinkType) -> bool {
    true
}
