#[derive(Clone)]
struct Delim {
    /// The delimiter characters (`*`, `_`, `~`) and count.
    ch: char,
    count: usize,
    /// Position in the output event list where the opener would go.
    index: usize,
    active: bool,
    /// Whether this can open emphasis.
    can_open: bool,
    /// Whether this can close emphasis.
    can_close: bool,
}

pub fn parse_inline(out: &mut Vec<Event>, text: &str, ctx: &InlineCtx) {
