struct Inline<'a> {
    out: &'a mut Vec<Event>,
    ctx: &'a InlineCtx<'a>,
    chars: Vec<char>,
    pos: usize,
    delims: Vec<Delim>,
}

impl<'a> Inline<'a> {
    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn at(&self, i: usize) -> Option<char> {
        self.chars.get(self.pos + i).copied()
    }

    fn prev(&self) -> Option<char> {
        if self.pos == 0 {
            None
        } else {
            self.chars.get(self.pos - 1).copied()
        }
    }

    fn run(&mut self) {
        let mut text = String::new();
        while self.pos < self.chars.len() {
            let c = self.peek().unwrap();
            match c {
                '\\' => {
                    if let Some(next) = self.at(1) {
                        match next {
                            '\n' => {
                                // Hard break.
                                self.pos += 1;
                                self.flush(&mut text);
                                self.out.push(Event::HardBreak);
                                self.pos += 1;
                                continue;
                            }
                            c if is_punctuation(c) => {
                                self.flush(&mut text);
                                self.out.push(Event::Text(c.to_string()));
                                self.pos += 2;
                                continue;
                            }
                            _ => {}
                        }
                    }
                    text.push('\\');
                    self.pos += 1;
                }
                '`' => {
                    let count = self.run_len('`');
                    if let Some(code) = self.code_span(count) {
                        self.flush(&mut text);
                        self.out.push(Event::Code(code));
                        continue;
                    }
                    for _ in 0..count {
                        text.push('`');
                    }
                    self.pos += count;
                }
                '*' | '_' | '~' => {
                    let count = self.run_len(c);
                    // `~` only comes in runs of 1 or 2.
                    let count = if c == '~' { count.min(2) } else { count };
                    if self.handle_emphasis(c, count, &mut text) {
                        continue;
                    }
                    for _ in 0..count {
                        text.push(c);
                    }
                    self.pos += count;
                }
                '[' => {
                    if self.ctx.footnotes && self.at(1) == Some('^') {
                        if let Some(label) = self.footnote_ref() {
                            self.flush(&mut text);
                            self.out.push(Event::FootnoteRef(label));
                            continue;
                        }
                    }
                    if let Some((evs, label)) = self.link(false) {
                        self.flush(&mut text);
                        self.out.extend(evs);
                        if let Some(label) = label {
                            self.delims.push(Delim {
                                ch: '[',
                                count: 1,
                                index: self.out.len(),
                                active: false,
                                can_open: false,
                                can_close: false,
                            });
                        }
                        continue;
                    }
                    text.push('[');
                    self.pos += 1;
                }
                '!' if self.at(1) == Some('[') => {
                    if let Some((evs, _)) = self.link(true) {
                        self.flush(&mut text);
                        self.out.extend(evs);
                        continue;
                    }
                    text.push('!');
                    self.pos += 1;
