                            link_type: LinkType::Autolink,
                            dest_url: String::new(),
                            title: String::new(),
                        }));
                        continue;
                    }
                    if let Some(html) = self.inline_html() {
                        self.flush(&mut text);
                        self.out.push(Event::InlineHtml(html));
                        continue;
                    }
                    text.push('<');
                    self.pos += 1;
                }
                '&' => {
                    if let Some(rep) = self.entity() {
                        self.flush(&mut text);
                        self.out.push(Event::Text(rep));
                        continue;
                    }
                    text.push('&');
                    self.pos += 1;
