                '\n' => {
                    // Soft break, unless the line ends with two spaces.
                    let trailing = text.chars().rev().take_while(|&c| c == ' ').count();
                    self.pos += 1;
                    if trailing >= 2 {
                        text.truncate(text.len() - trailing);
                        self.flush(&mut text);
                        self.out.push(Event::HardBreak);
                    } else {
                        self.flush(&mut text);
                        self.out.push(Event::SoftBreak);
                    }
                }
                _ => {
                    text.push(c);
                    self.pos += 1;
                }
            }
        }
        self.flush(&mut text);
        self.process_emphasis(usize::MAX, &mut String::new());
    }

    fn flush(&self, text: &mut String) {
        if !text.is_empty() {
            self.out.push(Event::Text(text.clone()));
            text.clear();
        }
    }

    fn run_len(&self, c: char) -> usize {
        let mut n = 0;
        while self.at(n) == Some(c) {
            n += 1;
        }
        n
    }

    /// A code span: `count` backticks, content, `count` backticks.
    fn code_span(&mut self, count: usize) -> Option<String> {
        let mut i = self.pos + count;
        let mut content = String::new();
        while i < self.chars.len() {
            if self.chars[i] == '`' {
                let run = {
                    let mut n = 0;
                    while i + n < self.chars.len() && self.chars[i + n] == '`' {
                        n += 1;
                    }
                    n
                };
                if run == count {
                    self.pos = i + run;
                    let mut s = content.trim_matches(' ').to_string();
                    if s.chars().all(|c| c == ' ') && !s.is_empty() {
                        s = " ".repeat(s.chars().count());
                    }
                    if s.is_empty() {
                        s = String::new();
                    }
                    return Some(s);
                }
                for _ in 0..run {
                    content.push('`');
                }
                i += run;
                continue;
            }
            content.push(self.chars[i]);
            i += 1;
        }
        None
    }

    /// Flanking rules for emphasis delimiters.
    fn flanking(&self, ch: char, count: usize) -> (bool, bool) {
        let before = if self.pos == 0 { None } else { self.chars[self.pos - 1] };
        let after = self.chars.get(self.pos + count).copied();
        let before_ws = before.map(|c| c.is_whitespace()).unwrap_or(true);
        let after_ws = after.map(|c| c.is_whitespace()).unwrap_or(true);
        let before_punct = before.map(is_punctuation).unwrap_or(false);
        let after_punct = after.map(is_punctuation).unwrap_or(false);
        // Left flanking: not followed by whitespace, and either not preceded by
        // punctuation or preceded by whitespace/punctuation.
        let left = !after_ws && (!before_punct || before_ws || after_punct);
        let right = !before_ws && (!after_punct || after_ws || before_punct);
        // An underscore requires the surroundings not to be alphanumeric.
        let mut can_open = left;
        let mut can_close = right;
        if ch == '_' {
            if let Some(b) = before {
                if b.is_alphanumeric() {
                    can_open = false;
                }
            }
            if let Some(a) = after {
                if a.is_alphanumeric() {
                    can_close = false;
                }
            }
        }
        (can_open, can_close)
    }

    fn handle_emphasis(&mut self, ch: char, count: usize, text: &mut String) -> bool {
        let (can_open, can_close) = self.flanking(ch, count);
        if !can_open && !can_close {
            return false;
