        self.flush(text);
        // Try to close with an earlier opener.
        if can_close {
            let mut idx = None;
            for (i, d) in self.delims.iter().enumerate().rev() {
                if d.ch == ch && d.active {
                    idx = Some(i);
                    break;
                }
