            if let Some(i) = idx {
                let opener_count = self.delims[i].count;
                let use_count = opener_count.min(count);
                if use_count > 0 {
                    self.process_emphasis(i, text);
                    // Consume the closing run.
                    self.pos += use_count;
                    return true;
                }
            }
        }
        if can_open {
            self.delims.push(Delim {
                ch,
                count,
                index: self.out.len(),
                active: true,
                can_open,
                can_close,
            });
            self.pos += count;
            return true;
        }
        false
    }

    /// Close emphasis from `stack_index` onwards.
    fn process_emphasis(&mut self, stack_index: usize, _text: &mut String) {
        while self.delims.len() > stack_index {
            let d = self.delims.pop().unwrap();
            let _ = d;
        }
    }

    fn footnote_ref(&mut self) -> Option<String> {
        let mut i = self.pos + 2;
        let mut label = String::new();
        while i < self.chars.len() {
            let c = self.chars[i];
            if c == ']' {
                self.pos = i + 1;
                return Some(label);
            }
            if c == '[' || c == '\\' || c.is_whitespace() {
                return None;
            }
            label.push(c);
            i += 1;
        }
        None
    }

    /// Parse a link or image. Returns the events and, for links, whether a
    /// potential reference opener should be pushed on the stack.
    fn link(&mut self, image: bool) -> Option<(Vec<Event>, Option<()>)> {
        let start = self.pos;
