        let mut depth = 0;
        let mut close = None;
        while i < self.chars.len() {
            match self.chars[i] {
                '\\' => {
                    i += 2;
                    continue;
                }
                '[' => depth += 1,
                ']' => {
                    if depth == 0 {
                        close = Some(i);
                        break;
                    }
                    depth -= 1;
                }
                _ => {}
            }
            i += 1;
        }
        let close = close?;
        let label: String = self.chars[self.pos + skip..close]
            .iter()
            .collect::<String>();
