        let mut j = close + 1;
        if j < self.chars.len() && self.chars[j] == '(' {
            let (dest, title, end) = self.parse_dest(j)?;
            self.pos = end;
            let mut evs = Vec::new();
            if image {
                evs.push(Event::Start(Tag::Image {
                    dest_url: dest,
                    title,
                }));
                push_inline(&mut evs, &label, self.ctx);
                evs.push(Event::End(Tag::Image {
                    dest_url: String::new(),
                    title: String::new(),
                }));
            } else {
                evs.push(Event::Start(Tag::Link {
                    link_type: LinkType::Inline,
                    dest_url: dest,
                    title,
                }));
                push_inline(&mut evs, &label, self.ctx);
                evs.push(Event::End(Tag::Link {
                    link_type: LinkType::Inline,
                    dest_url: String::new(),
                    title: String::new(),
                }));
