                if self.chars[i] == '\\' {
                    i += 1;
                    if i >= self.chars.len() {
                        return None;
                    }
                    dest.push(self.chars[i]);
                    i += 1;
                    continue;
                }
                dest.push(self.chars[i]);
                i += 1;
            }
            if i >= self.chars.len() {
                return None;
            }
            i += 1;
        } else {
            let mut depth = 0;
            while i < self.chars.len() {
                let c = self.chars[i];
