        let mut title = String::new();
        while i < self.chars.len() && self.chars[i].is_whitespace() {
            i += 1;
        }
        if i < self.chars.len() && (self.chars[i] == '"' || self.chars[i] == '\'') {
            let q = self.chars[i];
            i += 1;
            while i < self.chars.len() && self.chars[i] != q {
                if self.chars[i] == '\\' && i + 1 < self.chars.len() {
                    title.push(self.chars[i + 1]);
                    i += 2;
                    continue;
                }
                title.push(self.chars[i]);
                i += 1;
            }
            if i >= self.chars.len() {
                return None;
            }
            i += 1;
        }
        while i < self.chars.len() && self.chars[i].is_whitespace() {
            i += 1;
        }
        if i < self.chars.len() && self.chars[i] == ')' {
            Some((dest, title, i + 1))
        } else {
            None
        }
    }

    fn autolink(&mut self) -> Option<String> {
        let mut i = self.pos + 1;
        let mut url = String::new();
        while i < self.chars.len() {
            let c = self.chars[i];
            if c == '>' {
                if url.is_empty() || url.contains(' ') || url.contains('<') {
                    return None;
                }
                self.pos = i + 1;
                self.autolink_text = url.clone();
                return Some(url);
            }
            if c == '<' || c == '\n' {
                return None;
            }
            url.push(c);
            i += 1;
        }
        None
    }

    fn inline_html(&mut self) -> Option<String> {
        let mut i = self.pos + 1;
        let mut s = String::from("<");
        // Comment / declaration / processing instruction
        if self.chars.get(i) == Some(&'!') {
            if self.chars.get(i + 1) == Some(&'-') && self.chars.get(i + 2) == Some(&'-') {
                let mut j = i + 3;
                while j + 2 < self.chars.len() {
                    if self.chars[j] == '-' && self.chars[j + 1] == '-' && self.chars[j + 2] == '>' {
                        for c in &self.chars[self.pos..=j + 2] {
                            s.push(*c);
                        }
                        self.pos = j + 3;
                        return Some(s);
                    }
                    j += 1;
                }
                return None;
            }
            while i < self.chars.len() && self.chars[i] != '>' {
                if self.chars[i] == '\n' {
                    return None;
                }
                s.push(self.chars[i]);
                i += 1;
            }
            if i < self.chars.len() {
                s.push('>');
                self.pos = i + 1;
                return Some(s);
            }
            return None;
        }
        if self.chars.get(i) == Some(&'/') {
            s.push('/');
            i += 1;
        }
        let name_start = i;
        while i < self.chars.len() && (self.chars[i].is_ascii_alphanumeric() || self.chars[i] == '-') {
            i += 1;
        }
        if i == name_start {
            return None;
        }
        for c in &self.chars[name_start..i] {
            s.push(*c);
        }
        // Attributes
        loop {
            while i < self.chars.len() && self.chars[i] == ' ' {
                s.push(' ');
                i += 1;
            }
            if i >= self.chars.len() {
                return None;
            }
            if self.chars[i] == '>' {
                s.push('>');
                self.pos = i + 1;
                return Some(s);
            }
            if self.chars[i] == '/' && self.chars.get(i + 1) == Some(&'>') {
                s.push_str("/>");
                self.pos = i + 2;
                return Some(s);
            }
            // attribute name
            let start = i;
            while i < self.chars.len()
                && (self.chars[i].is_ascii_alphanumeric()
                    || self.chars[i] == '-'
                    || self.chars[i] == '_'
                    || self.chars[i] == ':'
                    || self.chars[i] == '.')
            {
                i += 1;
            }
            if i == start {
                return None;
            }
            for c in &self.chars[start..i] {
                s.push(*c);
            }
            if self.chars[i] == '=' {
                s.push('=');
                i += 1;
                if self.chars.get(i) == Some(&'"') || self.chars.get(i) == Some(&'\'') {
                    let q = self.chars[i];
                    s.push(q);
                    i += 1;
                    while i < self.chars.len() && self.chars[i] != q {
                        s.push(self.chars[i]);
                        i += 1;
                    }
                    if i >= self.chars.len() {
                        return None;
                    }
                    s.push(q);
                    i += 1;
                } else {
                    let start = i;
                    while i < self.chars.len()
                        && !self.chars[i].is_whitespace()
                        && self.chars[i] != '>'
                    {
                        i += 1;
                    }
                    if i == start {
                        return None;
                    }
                    for c in &self.chars[start..i] {
                        s.push(*c);
                    }
                }
            }
        }
    }

    fn entity(&mut self) -> Option<String> {
        let mut i = self.pos + 1;
        let mut name = String::new();
        while i < self.chars.len() && (self.chars[i].is_ascii_alphanumeric()) {
            name.push(self.chars[i]);
            i += 1;
            if name.len() > 32 {
                return None;
            }
        }
        if self.chars.get(i) != Some(&';') || name.is_empty() {
            return None;
        }
        let rep = match name.as_str() {
            "amp" => "&",
            "lt" => "<",
            "gt" => ">",
            "quot" => "\"",
            "apos" => "'",
            "nbsp" => "\u{a0}",
            "copy" => "\u{a9}",
            "hellip" => "\u{2026}",
            "mdash" => "\u{2014}",
            "ndash" => "\u{2013}",
            _ => {
                // Numeric entity
                let decoded = decode_entity(&name)?;
                self.pos = i + 1;
                return Some(decoded);
            }
        };
        self.pos = i + 1;
        Some(rep.to_string())
    }
}

// Extra fields live on the struct; declare them here so the code above compiles.
impl<'a> Inline<'a> {
    const fn _unused() {}
}

fn push_inline(out: &mut Vec<Event>, text: &str, ctx: &InlineCtx) {
    parse_inline(out, text, ctx);
}

pub fn is_punctuation(c: char) -> bool {
    c.is_ascii_punctuation()
        || matches!(
            c,
            '\u{00a1}'..='\u{00bf}' | '\u{2010}'..='\u{2027}' | '\u{2030}'..='\u{205e}'
        )
        || matches!(c, '\u{00a0}' | '\u{00a9}' | '\u{2028}' | '\u{2029}')
}

fn decode_entity(name: &str) -> Option<String> {
    if let Some(hex) = name.strip_prefix('#') {
        let n = if let Some(h) = hex.strip_prefix('x').or_else(|| hex.strip_prefix('X')) {
            u32::from_str_radix(h, 16).ok()
        } else {
            hex.parse::<u32>().ok()
        }?;
        return char::from_u32(n).map(|c| c.to_string());
    }
    Some(match name {
        "nbsp" => "\u{a0}".to_string(),
        "copy" => "\u{a9}".to_string(),
        "hellip" => "\u{2026}".to_string(),
        _ => return None,
    })
}

/// Parse `{ #id .class key=value }` heading attributes, returning the id,
/// classes and remaining attributes.
pub fn parse_heading_attrs(content: &str) -> (Option<String>, Vec<String>, Vec<(String, String)>) {
    let trimmed = content.trim_end();
    if !trimmed.ends_with('}') {
        return (None, Vec::new(), Vec::new());
    }
    let open = match trimmed.rfind('{') {
        Some(o) => o,
        None => return (None, Vec::new(), Vec::new()),
    };
    let inner = &trimmed[open + 1..trimmed.len() - 1];
    // Everything before the `{` must be whitespace-terminated content.
    if open > 0 && !trimmed[..open].ends_with(' ') && !trimmed[..open].is_empty() {
        return (None, Vec::new(), Vec::new());
    }
    let mut id = None;
    let mut classes = Vec::new();
    let mut attrs = Vec::new();
    for tok in inner.split_whitespace() {
        if let Some(v) = tok.strip_prefix('#') {
            id = Some(v.to_string());
        } else if let Some(v) = tok.strip_prefix('.') {
            classes.push(v.to_string());
        } else if let Some((k, v)) = tok.split_once('=') {
            attrs.push((k.to_string(), v.to_string()));
        } else {
            attrs.push((tok.to_string(), String::new()));
        }
    }
    if id.is_none() && classes.is_empty() && attrs.is_empty() {
        return (None, Vec::new(), Vec::new());
    }
    let text = trimmed[..open].trim_end().to_string();
    (id, classes, attrs)
}
