//! Inline (span level) parsing.

use super::events::{Event, LinkType, Tag};

pub struct InlineCtx<'a> {
    pub refs: &'a std::collections::HashMap<String, (String, String)>,
    pub smart_punctuation: bool,
    pub footnotes: bool,
}

#[derive(Clone)]
struct Delim {
    /// The delimiter characters (`*`, `_`, `~`) and count.
    ch: char,
    count: usize,
    /// Position in the output event list where the opener would go.
    index: usize,
    active: bool,
    /// Whether this can open emphasis.
    can_open: bool,
    /// Whether this can close emphasis.
    can_close: bool,
}

pub fn parse_inline(out: &mut Vec<Event>, text: &str, ctx: &InlineCtx) {
    let mut p = Inline {
        out,
        ctx,
        chars: text.chars().collect(),
        pos: 0,
        delims: Vec::new(),
    };
    p.run();
}

struct Inline<'a> {
    out: &'a mut Vec<Event>,
    ctx: &'a InlineCtx<'a>,
    chars: Vec<char>,
    pos: usize,
    delims: Vec<Delim>,
}

impl<'a> Inline<'a> {
    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn at(&self, i: usize) -> Option<char> {
        self.chars.get(self.pos + i).copied()
    }

    fn prev(&self) -> Option<char> {
        if self.pos == 0 {
            None
        } else {
            self.chars.get(self.pos - 1).copied()
        }
    }

    fn run(&mut self) {
        let mut text = String::new();
        while self.pos < self.chars.len() {
            let c = self.peek().unwrap();
            match c {
                '\\' => {
                    if let Some(next) = self.at(1) {
                        match next {
                            '\n' => {
                                // Hard break.
                                self.pos += 1;
                                self.flush(&mut text);
                                self.out.push(Event::HardBreak);
                                self.pos += 1;
                                continue;
                            }
                            c if is_punctuation(c) => {
                                self.flush(&mut text);
                                self.out.push(Event::Text(c.to_string()));
                                self.pos += 2;
                                continue;
                            }
                            _ => {}
                        }
                    }
                    text.push('\\');
                    self.pos += 1;
                }
                '`' => {
                    let count = self.run_len('`');
                    if let Some(code) = self.code_span(count) {
                        self.flush(&mut text);
                        self.out.push(Event::Code(code));
                        continue;
                    }
                    for _ in 0..count {
                        text.push('`');
                    }
                    self.pos += count;
                }
                '*' | '_' | '~' => {
                    let count = self.run_len(c);
                    // `~` only comes in runs of 1 or 2.
                    let count = if c == '~' { count.min(2) } else { count };
                    if self.handle_emphasis(c, count, &mut text) {
                        continue;
                    }
                    for _ in 0..count {
                        text.push(c);
                    }
                    self.pos += count;
                }
                '[' => {
                    if self.ctx.footnotes && self.at(1) == Some('^') {
                        if let Some(label) = self.footnote_ref() {
                            self.flush(&mut text);
                            self.out.push(Event::FootnoteRef(label));
                            continue;
                        }
                    }
                    if let Some((evs, label)) = self.link(false) {
                        self.flush(&mut text);
                        self.out.extend(evs);
                        if let Some(label) = label {
                            self.delims.push(Delim {
                                ch: '[',
                                count: 1,
                                index: self.out.len(),
                                active: false,
                                can_open: false,
                                can_close: false,
                            });
                        }
                        continue;
                    }
                    text.push('[');
                    self.pos += 1;
                }
                '!' if self.at(1) == Some('[') => {
                    if let Some((evs, _)) = self.link(true) {
                        self.flush(&mut text);
                        self.out.extend(evs);
                        continue;
                    }
                    text.push('!');
                    self.pos += 1;
                }
                '<' => {
                    if let Some(url) = self.autolink() {
                        self.flush(&mut text);
                        self.out.push(Event::Start(Tag::Link {
                            link_type: LinkType::Autolink,
                            dest_url: url,
                            title: String::new(),
                        }));
                        let t = self.autolink_text;
                        self.out.push(Event::Text(t));
                        self.out.push(Event::End(Tag::Link {
                            link_type: LinkType::Autolink,
                            dest_url: String::new(),
                            title: String::new(),
                        }));
                        continue;
                    }
                    if let Some(html) = self.inline_html() {
                        self.flush(&mut text);
                        self.out.push(Event::InlineHtml(html));
                        continue;
                    }
                    text.push('<');
                    self.pos += 1;
                }
                '&' => {
                    if let Some(rep) = self.entity() {
                        self.flush(&mut text);
                        self.out.push(Event::Text(rep));
                        continue;
                    }
                    text.push('&');
                    self.pos += 1;
                }
                '\n' => {
                    // Soft break, unless the line ends with two spaces.
                    let trailing = text.chars().rev().take_while(|&c| c == ' ').count();
                    self.pos += 1;
                    if trailing >= 2 {
                        text.truncate(text.len() - trailing);
                        self.flush(&mut text);
                        self.out.push(Event::HardBreak);
                    } else {
                        self.flush(&mut text);
                        self.out.push(Event::SoftBreak);
                    }
                }
                _ => {
                    text.push(c);
                    self.pos += 1;
                }
            }
        }
        self.flush(&mut text);
        self.process_emphasis(usize::MAX, &mut String::new());
    }

    fn flush(&self, text: &mut String) {
        if !text.is_empty() {
            self.out.push(Event::Text(text.clone()));
            text.clear();
        }
    }

    fn run_len(&self, c: char) -> usize {
        let mut n = 0;
        while self.at(n) == Some(c) {
            n += 1;
        }
        n
    }

    /// A code span: `count` backticks, content, `count` backticks.
    fn code_span(&mut self, count: usize) -> Option<String> {
        let mut i = self.pos + count;
        let mut content = String::new();
        while i < self.chars.len() {
            if self.chars[i] == '`' {
                let run = {
                    let mut n = 0;
                    while i + n < self.chars.len() && self.chars[i + n] == '`' {
                        n += 1;
                    }
                    n
                };
                if run == count {
                    self.pos = i + run;
                    let mut s = content.trim_matches(' ').to_string();
                    if s.chars().all(|c| c == ' ') && !s.is_empty() {
                        s = " ".repeat(s.chars().count());
                    }
                    if s.is_empty() {
                        s = String::new();
                    }
                    return Some(s);
                }
                for _ in 0..run {
                    content.push('`');
                }
                i += run;
                continue;
            }
            content.push(self.chars[i]);
            i += 1;
        }
        None
    }

    /// Flanking rules for emphasis delimiters.
    fn flanking(&self, ch: char, count: usize) -> (bool, bool) {
        let before = if self.pos == 0 { None } else { self.chars[self.pos - 1] };
        let after = self.chars.get(self.pos + count).copied();
        let before_ws = before.map(|c| c.is_whitespace()).unwrap_or(true);
        let after_ws = after.map(|c| c.is_whitespace()).unwrap_or(true);
        let before_punct = before.map(is_punctuation).unwrap_or(false);
        let after_punct = after.map(is_punctuation).unwrap_or(false);
        // Left flanking: not followed by whitespace, and either not preceded by
        // punctuation or preceded by whitespace/punctuation.
        let left = !after_ws && (!before_punct || before_ws || after_punct);
        let right = !before_ws && (!after_punct || after_ws || before_punct);
        // An underscore requires the surroundings not to be alphanumeric.
        let mut can_open = left;
        let mut can_close = right;
        if ch == '_' {
            if let Some(b) = before {
                if b.is_alphanumeric() {
                    can_open = false;
                }
            }
            if let Some(a) = after {
                if a.is_alphanumeric() {
                    can_close = false;
                }
            }
        }
        (can_open, can_close)
    }

    fn handle_emphasis(&mut self, ch: char, count: usize, text: &mut String) -> bool {
        let (can_open, can_close) = self.flanking(ch, count);
        if !can_open && !can_close {
            return false;
        }
        self.flush(text);
        // Try to close with an earlier opener.
        if can_close {
            let mut idx = None;
            for (i, d) in self.delims.iter().enumerate().rev() {
                if d.ch == ch && d.active {
                    idx = Some(i);
                    break;
                }
            }
            if let Some(i) = idx {
                let opener_count = self.delims[i].count;
                let use_count = opener_count.min(count);
                if use_count > 0 {
                    self.process_emphasis(i, text);
                    // Consume the closing run.
                    self.pos += use_count;
                    return true;
                }
            }
        }
        if can_open {
            self.delims.push(Delim {
                ch,
                count,
                index: self.out.len(),
                active: true,
                can_open,
                can_close,
            });
            self.pos += count;
            return true;
        }
        false
    }

    /// Close emphasis from `stack_index` onwards.
    fn process_emphasis(&mut self, stack_index: usize, _text: &mut String) {
        while self.delims.len() > stack_index {
            let d = self.delims.pop().unwrap();
            let _ = d;
        }
    }

    fn footnote_ref(&mut self) -> Option<String> {
        let mut i = self.pos + 2;
        let mut label = String::new();
        while i < self.chars.len() {
            let c = self.chars[i];
            if c == ']' {
                self.pos = i + 1;
                return Some(label);
            }
            if c == '[' || c == '\\' || c.is_whitespace() {
                return None;
            }
            label.push(c);
            i += 1;
        }
        None
    }

    /// Parse a link or image. Returns the events and, for links, whether a
    /// potential reference opener should be pushed on the stack.
    fn link(&mut self, image: bool) -> Option<(Vec<Event>, Option<()>)> {
        let start = self.pos;
        let skip = if image { 2 } else { 1 };
        let mut i = self.pos + skip;
        // Find the matching bracket.
        let mut depth = 0;
        let mut close = None;
        while i < self.chars.len() {
            match self.chars[i] {
                '\\' => {
                    i += 2;
                    continue;
                }
                '[' => depth += 1,
                ']' => {
                    if depth == 0 {
                        close = Some(i);
                        break;
                    }
                    depth -= 1;
                }
                _ => {}
            }
            i += 1;
        }
        let close = close?;
        let label: String = self.chars[self.pos + skip..close]
            .iter()
            .collect::<String>();
        // Now try to parse the destination.
        let mut j = close + 1;
        if j < self.chars.len() && self.chars[j] == '(' {
            let (dest, title, end) = self.parse_dest(j)?;
            self.pos = end;
            let mut evs = Vec::new();
            if image {
                evs.push(Event::Start(Tag::Image {
                    dest_url: dest,
                    title,
                }));
                push_inline(&mut evs, &label, self.ctx);
                evs.push(Event::End(Tag::Image {
                    dest_url: String::new(),
                    title: String::new(),
                }));
            } else {
                evs.push(Event::Start(Tag::Link {
                    link_type: LinkType::Inline,
                    dest_url: dest,
                    title,
                }));
                push_inline(&mut evs, &label, self.ctx);
                evs.push(Event::End(Tag::Link {
                    link_type: LinkType::Inline,
                    dest_url: String::new(),
                    title: String::new(),
                }));
            }
            return Some((evs, None));
        }
        // Reference, collapsed or shortcut link.
        let (ref_label, link_type) = if j < self.chars.len() && self.chars[j] == '[' {
            let mut k = j + 1;
            let mut lbl = String::new();
            while k < self.chars.len() {
                if self.chars[k] == '\\' {
                    k += 2;
                    continue;
                }
                if self.chars[k] == ']' {
                    break;
                }
                lbl.push(self.chars[k]);
                k += 1;
            }
            if k < self.chars.len() && self.chars[k] == ']' {
                let l = if lbl.is_empty() { label.clone() } else { lbl };
                self.pos = k + 1;
                (l, LinkType::Reference)
            } else {
                self.pos = close + 1;
                (label.clone(), LinkType::Collapsed)
            }
        } else {
            self.pos = close + 1;
            (label.clone(), LinkType::Shortcut)
        };
        let (dest, title) = match self.ctx.refs.get(&ref_label) {
            Some((d, t)) => (d.clone(), t.clone()),
            None => {
                self.pos = start;
                return None;
            }
        };
        let mut evs = Vec::new();
        if image {
            evs.push(Event::Start(Tag::Image {
                dest_url: dest,
                title,
            }));
            push_inline(&mut evs, &label, self.ctx);
            evs.push(Event::End(Tag::Image {
                dest_url: String::new(),
                title: String::new(),
            }));
        } else {
            evs.push(Event::Start(Tag::Link {
                link_type,
                dest_url: dest,
                title,
            }));
            push_inline(&mut evs, &label, self.ctx);
            evs.push(Event::End(Tag::Link {
                link_type: LinkType::Inline,
                dest_url: String::new(),
                title: String::new(),
            }));
        }
        Some((evs, None))
    }

    /// Parse `(dest "title")` starting at the `(`.
    fn parse_dest(&mut self, open: usize) -> Option<(String, String, usize)> {
        let mut i = open + 1;
        let mut dest = String::new();
        // Optional whitespace.
        while i < self.chars.len() && self.chars[i].is_whitespace() {
            i += 1;
        }
        if i < self.chars.len() && self.chars[i] == '<' {
            i += 1;
            while i < self.chars.len() && self.chars[i] != '>' {
                if self.chars[i] == '\\' {
                    i += 1;
                    if i >= self.chars.len() {
                        return None;
                    }
                    dest.push(self.chars[i]);
                    i += 1;
                    continue;
                }
                dest.push(self.chars[i]);
                i += 1;
            }
            if i >= self.chars.len() {
                return None;
            }
            i += 1;
        } else {
            let mut depth = 0;
            while i < self.chars.len() {
                let c = self.chars[i];
                if c == '\\' && i + 1 < self.chars.len() && is_punctuation(self.chars[i + 1]) {
                    dest.push(self.chars[i + 1]);
                    i += 2;
                    continue;
                }
                if c == '(' {
                    depth += 1;
                }
                if c == ')' {
                    if depth == 0 {
                        break;
                    }
                    depth -= 1;
                }
                if depth == 0 && (c.is_whitespace() || c == '"') {
                    break;
                }
                dest.push(c);
                i += 1;
            }
        }
        // Optional title.
        let mut title = String::new();
        while i < self.chars.len() && self.chars[i].is_whitespace() {
            i += 1;
        }
        if i < self.chars.len() && (self.chars[i] == '"' || self.chars[i] == '\'') {
            let q = self.chars[i];
            i += 1;
            while i < self.chars.len() && self.chars[i] != q {
                if self.chars[i] == '\\' && i + 1 < self.chars.len() {
                    title.push(self.chars[i + 1]);
                    i += 2;
                    continue;
                }
                title.push(self.chars[i]);
                i += 1;
            }
            if i >= self.chars.len() {
                return None;
            }
            i += 1;
        }
        while i < self.chars.len() && self.chars[i].is_whitespace() {
            i += 1;
        }
        if i < self.chars.len() && self.chars[i] == ')' {
            Some((dest, title, i + 1))
        } else {
            None
        }
    }

    fn autolink(&mut self) -> Option<String> {
        let mut i = self.pos + 1;
        let mut url = String::new();
        while i < self.chars.len() {
            let c = self.chars[i];
            if c == '>' {
                if url.is_empty() || url.contains(' ') || url.contains('<') {
                    return None;
                }
                self.pos = i + 1;
                self.autolink_text = url.clone();
                return Some(url);
            }
            if c == '<' || c == '\n' {
                return None;
            }
            url.push(c);
            i += 1;
        }
        None
    }

    fn inline_html(&mut self) -> Option<String> {
        let mut i = self.pos + 1;
        let mut s = String::from("<");
        // Comment / declaration / processing instruction
        if self.chars.get(i) == Some(&'!') {
            if self.chars.get(i + 1) == Some(&'-') && self.chars.get(i + 2) == Some(&'-') {
                let mut j = i + 3;
                while j + 2 < self.chars.len() {
                    if self.chars[j] == '-' && self.chars[j + 1] == '-' && self.chars[j + 2] == '>' {
                        for c in &self.chars[self.pos..=j + 2] {
                            s.push(*c);
                        }
                        self.pos = j + 3;
                        return Some(s);
                    }
                    j += 1;
                }
                return None;
            }
            while i < self.chars.len() && self.chars[i] != '>' {
                if self.chars[i] == '\n' {
                    return None;
                }
                s.push(self.chars[i]);
                i += 1;
            }
            if i < self.chars.len() {
                s.push('>');
                self.pos = i + 1;
                return Some(s);
            }
            return None;
        }
        if self.chars.get(i) == Some(&'/') {
            s.push('/');
            i += 1;
        }
        let name_start = i;
        while i < self.chars.len() && (self.chars[i].is_ascii_alphanumeric() || self.chars[i] == '-') {
            i += 1;
        }
        if i == name_start {
            return None;
        }
        for c in &self.chars[name_start..i] {
            s.push(*c);
        }
        // Attributes
        loop {
            while i < self.chars.len() && self.chars[i] == ' ' {
                s.push(' ');
                i += 1;
            }
            if i >= self.chars.len() {
                return None;
            }
            if self.chars[i] == '>' {
                s.push('>');
                self.pos = i + 1;
                return Some(s);
            }
            if self.chars[i] == '/' && self.chars.get(i + 1) == Some(&'>') {
                s.push_str("/>");
                self.pos = i + 2;
                return Some(s);
            }
            // attribute name
            let start = i;
            while i < self.chars.len()
                && (self.chars[i].is_ascii_alphanumeric()
                    || self.chars[i] == '-'
                    || self.chars[i] == '_'
                    || self.chars[i] == ':'
                    || self.chars[i] == '.')
            {
                i += 1;
            }
            if i == start {
                return None;
            }
            for c in &self.chars[start..i] {
                s.push(*c);
            }
            if self.chars[i] == '=' {
                s.push('=');
                i += 1;
                if self.chars.get(i) == Some(&'"') || self.chars.get(i) == Some(&'\'') {
                    let q = self.chars[i];
                    s.push(q);
                    i += 1;
                    while i < self.chars.len() && self.chars[i] != q {
                        s.push(self.chars[i]);
                        i += 1;
                    }
                    if i >= self.chars.len() {
                        return None;
                    }
                    s.push(q);
                    i += 1;
                } else {
                    let start = i;
                    while i < self.chars.len()
                        && !self.chars[i].is_whitespace()
                        && self.chars[i] != '>'
                    {
                        i += 1;
                    }
                    if i == start {
                        return None;
                    }
                    for c in &self.chars[start..i] {
                        s.push(*c);
                    }
                }
            }
        }
    }

    fn entity(&mut self) -> Option<String> {
        let mut i = self.pos + 1;
        let mut name = String::new();
        while i < self.chars.len() && (self.chars[i].is_ascii_alphanumeric()) {
            name.push(self.chars[i]);
            i += 1;
            if name.len() > 32 {
                return None;
            }
        }
        if self.chars.get(i) != Some(&';') || name.is_empty() {
            return None;
        }
        let rep = match name.as_str() {
            "amp" => "&",
            "lt" => "<",
            "gt" => ">",
            "quot" => "\"",
            "apos" => "'",
            "nbsp" => "\u{a0}",
            "copy" => "\u{a9}",
            "hellip" => "\u{2026}",
            "mdash" => "\u{2014}",
            "ndash" => "\u{2013}",
            _ => {
                // Numeric entity
                let decoded = decode_entity(&name)?;
                self.pos = i + 1;
                return Some(decoded);
            }
        };
        self.pos = i + 1;
        Some(rep.to_string())
    }
}

// Extra fields live on the struct; declare them here so the code above compiles.
impl<'a> Inline<'a> {
    const fn _unused() {}
}

fn push_inline(out: &mut Vec<Event>, text: &str, ctx: &InlineCtx) {
    parse_inline(out, text, ctx);
}

pub fn is_punctuation(c: char) -> bool {
    c.is_ascii_punctuation()
        || matches!(
            c,
            '\u{00a1}'..='\u{00bf}' | '\u{2010}'..='\u{2027}' | '\u{2030}'..='\u{205e}'
        )
        || matches!(c, '\u{00a0}' | '\u{00a9}' | '\u{2028}' | '\u{2029}')
}

fn decode_entity(name: &str) -> Option<String> {
    if let Some(hex) = name.strip_prefix('#') {
        let n = if let Some(h) = hex.strip_prefix('x').or_else(|| hex.strip_prefix('X')) {
            u32::from_str_radix(h, 16).ok()
        } else {
            hex.parse::<u32>().ok()
        }?;
        return char::from_u32(n).map(|c| c.to_string());
    }
    Some(match name {
        "nbsp" => "\u{a0}".to_string(),
        "copy" => "\u{a9}".to_string(),
        "hellip" => "\u{2026}".to_string(),
        _ => return None,
    })
}

/// Parse `{ #id .class key=value }` heading attributes, returning the id,
/// classes and remaining attributes.
pub fn parse_heading_attrs(content: &str) -> (Option<String>, Vec<String>, Vec<(String, String)>) {
    let trimmed = content.trim_end();
    if !trimmed.ends_with('}') {
        return (None, Vec::new(), Vec::new());
    }
    let open = match trimmed.rfind('{') {
        Some(o) => o,
        None => return (None, Vec::new(), Vec::new()),
    };
    let inner = &trimmed[open + 1..trimmed.len() - 1];
    // Everything before the `{` must be whitespace-terminated content.
    if open > 0 && !trimmed[..open].ends_with(' ') && !trimmed[..open].is_empty() {
        return (None, Vec::new(), Vec::new());
    }
    let mut id = None;
    let mut classes = Vec::new();
    let mut attrs = Vec::new();
    for tok in inner.split_whitespace() {
        if let Some(v) = tok.strip_prefix('#') {
            id = Some(v.to_string());
        } else if let Some(v) = tok.strip_prefix('.') {
            classes.push(v.to_string());
        } else if let Some((k, v)) = tok.split_once('=') {
            attrs.push((k.to_string(), v.to_string()));
        } else {
            attrs.push((tok.to_string(), String::new()));
        }
    }
    if id.is_none() && classes.is_empty() && attrs.is_empty() {
        return (None, Vec::new(), Vec::new());
    }
    let text = trimmed[..open].trim_end().to_string();
    (id, classes, attrs)
}
