//! Text processing helpers: entities and smart punctuation.

/// Whether a character counts as punctuation for the flanking rules.
pub fn is_punctuation(c: char) -> bool {
    c.is_ascii_punctuation()
        || ('\u{00a1}'..='\u{00bf}').contains(&c)
        || ('\u{2010}'..='\u{2027}').contains(&c)
        || ('\u{2030}'..='\u{205e}').contains(&c)
}

/// Decode an entity starting at `pos` (`&`).
pub fn entity_value(chars: &[char], pos: usize) -> Option<String> {
    let mut i = pos + 1;
    let mut name = String::new();
    while i < chars.len() && (chars[i].is_ascii_alphanumeric() || chars[i] == '#') {
        name.push(chars[i]);
        i += 1;
        if name.len() > 32 {
            return None;
        }
    }
    if i >= chars.len() || chars[i] != ';' || name.is_empty() {
        return None;
    }
    decode(&name)
}

fn decode(name: &str) -> Option<String> {
    if let Some(num) = name.strip_prefix('#') {
        let value = if let Some(hex) = num.strip_prefix('x').or_else(|| num.strip_prefix('X')) {
            u32::from_str_radix(hex, 16).ok()
        } else {
            num.parse::<u32>().ok()
        }?;
        return char::from_u32(value).map(|c| c.to_string());
    }
    Some(
        match name {
            "amp" => "&",
            "lt" => "<",
            "gt" => ">",
            "quot" => "\"",
            "apos" => "'",
            "nbsp" => "\u{a0}",
            "copy" => "\u{a9}",
            "hellip" => "\u{2026}",
            "mdash" => "\u{2014}",
            "ndash" => "\u{2013}",
            "bull" => "\u{2022}",
            "dagger" => "\u{2020}",
            "sect" => "\u{a7}",
            "times" => "\u{d7}",
            "deg" => "\u{b0}",
            "reg" => "\u{ae}",
            "trade" => "\u{2122}",
            "larr" => "\u{2190}",
            "uarr" => "\u{2191}",
            "rarr" => "\u{2192}",
            "darr" => "\u{2193}",
            "harr" => "\u{2194}",
            "check" => "\u{2713}",
            "cross" => "\u{2717}",
            _ => return None,
        }
        .to_string(),
    )
}

/// Turn ASCII punctuation sequences into their unicode counterparts.
pub fn smart_punctuation(text: &str) -> String {
    let chars: Vec<char> = text.chars().collect();
    let mut out = String::with_capacity(text.len());
    let mut i = 0;
    let mut in_dquotes = false;
    let mut in_squotes = false;
    while i < chars.len() {
        let c = chars[i];
        match c {
            '-' => {
                let mut run = 0;
                while i + run < chars.len() && chars[i + run] == '-' {
                    run += 1;
                }
                if run >= 3 {
                    out.push('\u{2014}');
                } else if run == 2 {
                    out.push('\u{2013}');
                } else {
                    out.push('-');
                }
                i += run;
            }
            '.' => {
                if i + 2 < chars.len() && chars[i + 1] == '.' && chars[i + 2] == '.' {
                    out.push('\u{2026}');
                    i += 3;
                } else {
                    out.push('.');
                    i += 1;
                }
            }
            '"' => {
                if in_dquotes {
                    out.push('\u{201d}');
                    in_dquotes = false;
                } else {
                    out.push('\u{201c}');
                    in_dquotes = true;
                }
                i += 1;
            }
            '\'' => {
                if in_squotes {
                    out.push('\u{2019}');
                    in_squotes = false;
                } else {
                    out.push('\u{2018}');
                    in_squotes = true;
                }
                i += 1;
            }
            _ => {
                out.push(c);
                i += 1;
            }
        }
    }
    out
}
