//! Inline (span level) parsing.

use super::events::{Event, LinkType, Tag};
use super::text::{self, entity_value};

pub struct InlineCtx<'a> {
    pub refs: &'a std::collections::HashMap<String, (String, String)>,
    pub smart_punctuation: bool,
    pub footnotes: bool,
}

#[derive(Clone)]
struct Delim {
    ch: char,
    count: usize,
    /// Index in the event list where the opener was (or would be) inserted.
    index: usize,
    can_open: bool,
    can_close: bool,
}

pub fn parse_inline(out: &mut Vec<Event>, text_str: &str, ctx: &InlineCtx) {
    let mut p = Inline {
        out,
        ctx,
        chars: text_str.chars().collect(),
        pos: 0,
        delims: Vec::new(),
    };
    p.run();
}

/// Parse inline content into a fresh event list.
pub fn inline_events(text_str: &str, ctx: &InlineCtx) -> Vec<Event> {
    let mut out = Vec::new();
    parse_inline(&mut out, text_str, ctx);
    out
}

struct Inline<'a> {
    out: &'a mut Vec<Event>,
    ctx: &'a InlineCtx<'a>,
    chars: Vec<char>,
    pos: usize,
    delims: Vec<Delim>,
}

impl<'a> Inline<'a> {
    fn at(&self, i: usize) -> Option<char> {
        self.chars.get(self.pos + i).copied()
    }

    fn run(&mut self) {
        let mut text = String::new();
        while self.pos < self.chars.len() {
            let c = self.chars[self.pos];
            match c {
                '\\' => {
                    if let Some(next) = self.at(1) {
                        if next == '\n' {
                            self.flush(&mut text);
                            self.pos += 2;
                            self.out.push(Event::HardBreak);
                            continue;
                        }
                        if is_punctuation(next) {
                            self.flush(&mut text);
                            self.out.push(Event::Text(smart(next, self.ctx)));
                            self.pos += 2;
                            continue;
                        }
                    }
                    text.push('\\');
                    self.pos += 1;
                }
                '`' => {
                    let count = self.run_len('`');
                    match self.code_span(count) {
                        Some(code) => {
                            self.flush(&mut text);
                            self.out.push(Event::Code(code));
                        }
                        None => {
                            for _ in 0..count {
                                text.push('`');
                            }
                            self.pos += count;
                        }
                    }
                }
                '*' | '_' | '~' => {
                    let mut count = self.run_len(c);
                    if c == '~' {
                        count = count.min(2);
                    }
                    match self.emphasis(c, count, &mut text) {
                        Some(()) => {}
                        None => {
                            for _ in 0..count {
                                text.push(c);
                            }
                            self.pos += count;
                        }
                    }
                }
                '[' => {
                    if self.ctx.footnotes && self.at(1) == Some('^') {
                        if let Some(label) = self.footnote_ref() {
                            self.flush(&mut text);
                            self.out.push(Event::FootnoteRef(label));
                            continue;
                        }
                    }
                    match self.link(false) {
                        Some(evs) => {
                            self.flush(&mut text);
                            self.out.extend(evs);
                        }
                        None => {
                            text.push('[');
                            self.pos += 1;
                        }
                    }
                }
                '!' if self.at(1) == Some('[') => match self.link(true) {
                    Some(evs) => {
                        self.flush(&mut text);
                        self.out.extend(evs);
                    }
                    None => {
                        text.push('!');
                        self.pos += 1;
                    }
                },
                '<' => {
                    if let Some((url, label)) = self.autolink() {
                        self.flush(&mut text);
                        self.out.push(Event::Start(Tag::Link {
                            link_type: LinkType::Autolink,
                            dest_url: url.clone(),
                            title: String::new(),
                        }));
                        self.out.push(Event::Text(label));
                        self.out.push(Event::End(Tag::Link {
                            link_type: LinkType::Autolink,
                            dest_url: String::new(),
                            title: String::new(),
                        }));
                        continue;
                    }
                    if let Some(html) = self.inline_html() {
                        self.flush(&mut text);
                        self.out.push(Event::InlineHtml(html));
                        continue;
                    }
                    text.push('<');
                    self.pos += 1;
                }
                '&' => {
                    if let Some(rep) = entity_value(&self.chars, self.pos) {
                        self.flush(&mut text);
                        self.out.push(Event::Text(rep));
                        self.pos += entity_len(&self.chars, self.pos);
                        continue;
                    }
                    text.push('&');
                    self.pos += 1;
                }
                '\n' => {
                    let trailing = text.chars().rev().take_while(|&c| c == ' ').count();
                    self.pos += 1;
                    if trailing >= 2 {
                        let keep = text.len() - trailing * ' '.len_utf8();
                        text.truncate(keep);
                        self.flush(&mut text);
                        self.out.push(Event::HardBreak);
                    } else {
                        self.flush(&mut text);
                        self.out.push(Event::SoftBreak);
                    }
                }
                _ => {
                    text.push(c);
                    self.pos += 1;
                }
            }
        }
        self.flush(&mut text);
        self.process_emphasis(self.delims.len());
    }

    fn flush(&self, text: &mut String) {
        if !text.is_empty() {
            self.out.push(Event::Text(smart_text(text, self.ctx)));
            text.clear();
        }
    }

    fn run_len(&self, c: char) -> usize {
        let mut n = 0;
        while self.at(n) == Some(c) {
            n += 1;
        }
        n
    }

    fn code_span(&mut self, count: usize) -> Option<String> {
        let mut i = self.pos + count;
        let mut content: Vec<char> = Vec::new();
        while i < self.chars.len() {
            if self.chars[i] == '`' {
                let mut n = 0;
                while i + n < self.chars.len() && self.chars[i + n] == '`' {
                    n += 1;
                }
                if n == count {
                    self.pos = i + n;
                    let s: String = content.iter().collect();
                    // Trim one leading and trailing space.
                    let mut s = s.as_str();
                    if s.starts_with(' ') && s.ends_with(' ') && s.chars().count() > 1 {
                        s = &s[1..s.len() - 1];
                    }
                    return Some(s.to_string());
                }
                for _ in 0..n {
                    content.push('`');
                }
                i += n;
                continue;
            }
            content.push(self.chars[i]);
            i += 1;
        }
        None
    }

    fn flanking(&self, ch: char, count: usize) -> (bool, bool) {
        let before = if self.pos == 0 {
            None
        } else {
            Some(self.chars[self.pos - 1])
        };
        let after = self.chars.get(self.pos + count).copied();
        let before_ws = before.map(|c| c.is_whitespace()).unwrap_or(true);
        let after_ws = after.map(|c| c.is_whitespace()).unwrap_or(true);
        let before_punct = before.map(is_punctuation).unwrap_or(false);
        let after_punct = after.map(is_punctuation).unwrap_or(false);
        let left = !after_ws && (!before_punct || before_ws || after_punct);
        let right = !before_ws && (!after_punct || after_ws || before_punct);
        let mut can_open = left;
        let mut can_close = right;
        if ch == '_' {
            if let Some(b) = before {
                if b.is_alphanumeric() {
                    can_open = false;
                }
            }
            if let Some(a) = after {
                if a.is_alphanumeric() {
                    can_close = false;
                }
            }
        }
        (can_open, can_close)
    }

    fn emphasis(&mut self, ch: char, count: usize, text: &mut String) -> Option<()> {
        let (can_open, can_close) = self.flanking(ch, count);
        if !can_open && !can_close {
            return None;
        }
        self.flush(text);
        if can_close {
            // Find the closest opener of the same character.
            let mut idx = None;
            for i in (0..self.delims.len()).rev() {
                if self.delims[i].ch == ch && self.delims[i].can_open {
                    idx = Some(i);
                    break;
                }
            }
            if let Some(i) = idx {
                // Pop everything above, emitting it as text.
                let mut dropped = String::new();
                while self.delims.len() > i + 1 {
                    let d = self.delims.pop().unwrap();
                    for _ in 0..d.count {
                        dropped.push(d.ch);
                    }
                }
                if !dropped.is_empty() {
                    self.out.push(Event::Text(dropped));
                }
                let use_count = self.delims[i].count.min(count).min(2);
                if use_count > 0 {
                    let tag = match ch {
                        '~' => Tag::Strikethrough,
                        _ if use_count == 2 => Tag::Strong,
                        _ => Tag::Emphasis,
                    };
                    // Insert the opener before the events added since.
                    let index = self.delims[i].index;
                    let opener = Event::Start(tag.clone());
                    self.out.insert(index, opener);
                    // Update all later delimiter indices.
                    for d in self.delims[i + 1..].iter_mut() {
                        d.index += 1;
                    }
                    self.out.push(Event::End(tag));
                    self.pos += use_count;
                    self.delims[i].count -= use_count;
                    if self.delims[i].count == 0 {
                        self.delims.remove(i);
                    } else {
                        // The opener can no longer open.
                        self.delims[i].can_open = false;
                    }
                    return Some(());
                }
            }
        }
        if can_open {
            self.delims.push(Delim {
                ch,
                count,
                index: self.out.len(),
                can_open,
                can_close,
            });
            self.pos += count;
            return Some(());
        }
        None
    }

    /// Convert remaining delimiters into literal text.
    fn process_emphasis(&mut self, upto: usize) {
        while self.delims.len() > upto.min(self.delims.len()) {
            let d = self.delims.pop().unwrap();
            let mut s = String::new();
            for _ in 0..d.count {
                s.push(d.ch);
            }
            if !s.is_empty() {
                self.out.push(Event::Text(s));
            }
        }
    }

    fn footnote_ref(&mut self) -> Option<String> {
        let mut i = self.pos + 2;
        let mut label = String::new();
        while i < self.chars.len() {
            let c = self.chars[i];
            if c == ']' {
                self.pos = i + 1;
                return Some(label);
            }
            if c == '[' || c == '\\' || c.is_whitespace() {
                return None;
            }
            label.push(c);
            i += 1;
        }
        None
    }

    fn link(&mut self, image: bool) -> Option<Vec<Event>> {
        let start = self.pos;
        let skip = if image { 2 } else { 1 };
        let mut i = self.pos + skip;
        let mut depth = 0;
        let mut close = None;
        while i < self.chars.len() {
            match self.chars[i] {
                '\\' => {
                    i += 2;
                    continue;
                }
                '[' => depth += 1,
                ']' => {
                    if depth == 0 {
                        close = Some(i);
                        break;
                    }
                    depth -= 1;
                }
                _ => {}
            }
            i += 1;
        }
        let close = close?;
        let label: String = self.chars[self.pos + skip..close].iter().collect();
        let mut j = close + 1;
        if self.chars.get(j) == Some(&'(') {
            let (dest, title, end) = self.parse_dest(j)?;
            self.pos = end;
            return Some(self.link_events(image, LinkType::Inline, dest, title, &label));
        }
        let (ref_label, link_type, new_pos) = if self.chars.get(j) == Some(&'[') {
            let mut k = j + 1;
            let mut lbl = String::new();
            while k < self.chars.len() {
                if self.chars[k] == '\\' {
                    k += 2;
                    continue;
                }
                if self.chars[k] == ']' {
                    break;
                }
                lbl.push(self.chars[k]);
                k += 1;
            }
            if self.chars.get(k) == Some(&']') {
                let l = if lbl.is_empty() { label.clone() } else { lbl };
                (l, LinkType::Reference, k + 1)
            } else {
                (label.clone(), LinkType::Collapsed, close + 1)
            }
        } else {
            (label.clone(), LinkType::Shortcut, close + 1)
        };
        let (dest, title) = self.ctx.refs.get(&ref_label)?.clone();
        self.pos = new_pos;
        Some(self.link_events(image, link_type, dest, title, &label))
    }

    fn link_events(
        &self,
        image: bool,
        link_type: LinkType,
        dest: String,
        title: String,
        label: &str,
    ) -> Vec<Event> {
        let mut evs = Vec::new();
        if image {
            evs.push(Event::Start(Tag::Image {
                dest_url: dest,
                title,
            }));
            evs.extend(inline_events(label, self.ctx));
            evs.push(Event::End(Tag::Image {
                dest_url: String::new(),
                title: String::new(),
            }));
        } else {
            evs.push(Event::Start(Tag::Link {
                link_type,
                dest_url: dest,
                title,
            }));
            evs.extend(inline_events(label, self.ctx));
            evs.push(Event::End(Tag::Link {
                link_type: LinkType::Inline,
                dest_url: String::new(),
                title: String::new(),
            }));
        }
        evs
    }

    fn parse_dest(&mut self, open: usize) -> Option<(String, String, usize)> {
        let mut i = open + 1;
        let mut dest = String::new();
        while i < self.chars.len() && self.chars[i].is_whitespace() {
            i += 1;
        }
        if self.chars.get(i) == Some(&'<') {
            i += 1;
            while i < self.chars.len() && self.chars[i] != '>' {
                if self.chars[i] == '\\' {
                    i += 1;
                    if i >= self.chars.len() {
                        return None;
                    }
                }
                dest.push(self.chars[i]);
                i += 1;
            }
            if i >= self.chars.len() {
                return None;
            }
            i += 1;
        } else {
            let mut depth = 0;
            while i < self.chars.len() {
                let c = self.chars[i];
                if c == '\\' && i + 1 < self.chars.len() && is_punctuation(self.chars[i + 1]) {
                    dest.push(self.chars[i + 1]);
                    i += 2;
                    continue;
                }
                if c == '(' {
                    depth += 1;
                }
                if c == ')' {
                    if depth == 0 {
                        break;
                    }
                    depth -= 1;
                }
                if depth == 0 && (c.is_whitespace() || c == '"') {
                    break;
                }
                dest.push(c);
                i += 1;
            }
        }
        let mut title = String::new();
        while i < self.chars.len() && self.chars[i].is_whitespace() {
            i += 1;
        }
        if let Some(&q) = self.chars.get(i) {
            if q == '"' || q == '\'' {
                i += 1;
                while i < self.chars.len() && self.chars[i] != q {
                    if self.chars[i] == '\\' && i + 1 < self.chars.len() {
                        title.push(self.chars[i + 1]);
                        i += 2;
                        continue;
                    }
                    title.push(self.chars[i]);
                    i += 1;
                }
                if i >= self.chars.len() {
                    return None;
                }
                i += 1;
            }
        }
        while i < self.chars.len() && self.chars[i].is_whitespace() {
            i += 1;
        }
        if self.chars.get(i) == Some(&')') {
            Some((dest, title, i + 1))
        } else {
            None
        }
    }

    fn autolink(&mut self) -> Option<(String, String)> {
        let mut i = self.pos + 1;
        let mut url = String::new();
        while i < self.chars.len() {
            let c = self.chars[i];
            if c == '>' {
                if url.is_empty() || url.contains(' ') || url.contains('<') {
                    return None;
                }
                self.pos = i + 1;
                return Some((url.clone(), url));
            }
            if c == '<' || c == '\n' {
                return None;
            }
            url.push(c);
            i += 1;
        }
        None
    }

    fn inline_html(&mut self) -> Option<String> {
        let mut i = self.pos + 1;
        let mut s = String::from("<");
        if self.chars.get(i) == Some(&'!') {
            if self.chars.get(i + 1) == Some(&'-') && self.chars.get(i + 2) == Some(&'-') {
                let mut j = i + 3;
                while j + 2 < self.chars.len() {
                    if self.chars[j] == '-'
                        && self.chars[j + 1] == '-'
                        && self.chars[j + 2] == '>'
                    {
                        for c in &self.chars[self.pos..=j + 2] {
                            s.push(*c);
                        }
                        self.pos = j + 3;
                        return Some(s);
                    }
                    j += 1;
                }
                return None;
            }
            while i < self.chars.len() && self.chars[i] != '>' {
                if self.chars[i] == '\n' {
                    return None;
                }
                s.push(self.chars[i]);
                i += 1;
            }
            if i < self.chars.len() {
                s.push('>');
                self.pos = i + 1;
                return Some(s);
            }
            return None;
        }
        if self.chars.get(i) == Some(&'/') {
            s.push('/');
            i += 1;
        }
        let name_start = i;
        while i < self.chars.len()
            && (self.chars[i].is_ascii_alphanumeric() || self.chars[i] == '-')
        {
            i += 1;
        }
        if i == name_start {
            return None;
        }
        for c in &self.chars[name_start..i] {
            s.push(*c);
        }
        loop {
            while i < self.chars.len() && (self.chars[i] == ' ' || self.chars[i] == '\n') {
                s.push(self.chars[i]);
                i += 1;
            }
            if i >= self.chars.len() {
                return None;
            }
            if self.chars[i] == '>' {
                s.push('>');
                self.pos = i + 1;
                return Some(s);
            }
            if self.chars[i] == '/' && self.chars.get(i + 1) == Some(&'>') {
                s.push_str("/>");
                self.pos = i + 2;
                return Some(s);
            }
            let start = i;
            while i < self.chars.len()
                && (self.chars[i].is_ascii_alphanumeric()
                    || matches!(self.chars[i], '-' | '_' | ':' | '.'))
            {
                i += 1;
            }
            if i == start {
                return None;
            }
            for c in &self.chars[start..i] {
                s.push(*c);
            }
            if self.chars.get(i) == Some(&'=') {
                s.push('=');
                i += 1;
                if let Some(&q) = self.chars.get(i) {
                    if q == '"' || q == '\'' {
                        s.push(q);
                        i += 1;
                        while i < self.chars.len() && self.chars[i] != q {
                            s.push(self.chars[i]);
                            i += 1;
                        }
                        if i >= self.chars.len() {
                            return None;
                        }
                        s.push(q);
                        i += 1;
                        continue;
                    }
                }
                let start = i;
                while i < self.chars.len()
                    && !self.chars[i].is_whitespace()
                    && self.chars[i] != '>'
                {
                    i += 1;
                }
                if i == start {
                    return None;
                }
                for c in &self.chars[start..i] {
                    s.push(*c);
                }
            }
        }
    }
}

fn entity_len(chars: &[char], pos: usize) -> usize {
    let mut i = pos + 1;
    while i < chars.len() && chars[i].is_ascii_alphanumeric() {
        i += 1;
    }
    i + 1 - pos
}

pub fn is_punctuation(c: char) -> bool {
    text::is_punctuation(c)
}

/// Apply smart punctuation to a single character.
fn smart(c: char, _ctx: &InlineCtx) -> String {
    c.to_string()
}

/// Apply smart punctuation to a chunk of text.
fn smart_text(text: &str, ctx: &InlineCtx) -> String {
    if !ctx.smart_punctuation {
        return text.to_string();
    }
    text::smart_punctuation(text)
}

/// Parse `{ #id .class key=value }` heading attributes.
pub fn parse_heading_attrs(content: &str) -> (Option<String>, Vec<String>, Vec<(String, String)>) {
    let trimmed = content.trim_end();
    if !trimmed.ends_with('}') {
        return (None, Vec::new(), Vec::new());
    }
    let open = match trimmed.rfind('{') {
        Some(o) => o,
        None => return (None, Vec::new(), Vec::new()),
    };
    let inner = &trimmed[open + 1..trimmed.len() - 1];
    if open > 0 && !trimmed[..open].ends_with(' ') {
        return (None, Vec::new(), Vec::new());
    }
    let mut id = None;
    let mut classes = Vec::new();
    let mut attrs = Vec::new();
    for tok in inner.split_whitespace() {
        if let Some(v) = tok.strip_prefix('#') {
            id = Some(v.to_string());
        } else if let Some(v) = tok.strip_prefix('.') {
            classes.push(v.to_string());
        } else if let Some((k, v)) = tok.split_once('=') {
            attrs.push((k.to_string(), v.to_string()));
        } else {
            attrs.push((tok.to_string(), String::new()));
        }
    }
    if id.is_none() && classes.is_empty() && attrs.is_empty() {
        return (None, Vec::new(), Vec::new());
    }
    let text = trimmed[..open].trim_end().to_string();
    (id, classes, attrs)
}
