//! Rendering of the event stream into HTML.

use super::events::{Alignment, Event, LinkType, Tag};
use super::block::Options;
use super::text;

pub struct CodeBlockOpts {
    /// Map from language to the prefix that hides lines.
    pub hidelines: Vec<(String, String)>,
    /// The default hide prefix for rust code.
    pub rust_hide_prefix: Option<String>,
    /// Whether the rust playground is enabled.
    pub playground_runnable: bool,
    /// Whether the "editable" attribute is honoured.
    pub playground_editable: bool,
    /// Whether line numbers are shown in the editor.
    pub playground_line_numbers: bool,
    /// Whether a copy button is added to playground blocks.
    pub playground_copyable: bool,
    /// The default rust edition.
    pub rust_edition: Option<String>,
}

impl Default for CodeBlockOpts {
    fn default() -> Self {
        CodeBlockOpts {
            hidelines: Vec::new(),
            rust_hide_prefix: Some("# ".to_string()),
            playground_runnable: true,
            playground_editable: false,
            playground_line_numbers: false,
            playground_copyable: true,
            rust_edition: None,
        }
    }
}

/// Renders events into HTML, matching the reference implementation.
pub struct Renderer {
    out: String,
    opts: Options,
    code: CodeBlockOpts,
    /// The list nesting depth, used to know when items contain blocks.
    list_stack: Vec<Option<u64>>,
    /// Whether the item currently being rendered has more than one block.
    loose_items: Vec<bool>,
    /// Footnote definitions, keyed by label.
    footnote_defs: Vec<(String, Vec<Event>)>,
    /// The labels of the footnote references in order of appearance.
    footnote_refs: Vec<String>,
}

pub fn render(events: &[Event], opts: &Options, code: &CodeBlockOpts) -> String {
    let mut r = Renderer {
        out: String::new(),
        opts: Options {
            smart_punctuation: opts.smart_punctuation,
            ..Default::default()
        },
        code: CodeBlockOpts {
            hidelines: code.hidelines.clone(),
            rust_hide_prefix: code.rust_hide_prefix.clone(),
            playground_runnable: code.playground_runnable,
            playground_editable: code.playground_editable,
            playground_line_numbers: code.playground_line_numbers,
            playground_copyable: code.playground_copyable,
            rust_edition: code.rust_edition.clone(),
        },
        list_stack: Vec::new(),
        loose_items: Vec::new(),
        footnote_defs: Vec::new(),
        footnote_refs: Vec::new(),
    };
    r.run(events);
    r.out
}

/// Escape a string for use in HTML text.
pub fn escape(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    for c in text.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            _ => out.push(c),
        }
    }
    out
}

/// Escape a string for use inside a quoted attribute.
pub fn escape_attribute(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    for c in text.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            _ => out.push(c),
        }
    }
    out
}

/// Compute the id of a heading from its text content.
pub fn id_from_content(content: &str) -> String {
    content
        .chars()
        .filter(|&c| c.is_alphanumeric() || c == '-' || c == '_' || c.is_whitespace())
        .map(|c| {
            if c.is_whitespace() {
                '-'
            } else if c.is_ascii() {
                c.to_ascii_lowercase()
            } else {
                c
            }
        })
        .collect()
}

impl Renderer {
    fn run(&mut self, events: &[Event]) {
        // Collect the footnote definitions and the order of the references.
        let mut defs: Vec<(String, Vec<Event>)> = Vec::new();
        let mut refs: Vec<String> = Vec::new();
        collect_footnotes(events, &mut defs, &mut refs);
        self.footnote_defs = defs;
        self.footnote_refs = refs;

        self.walk(events);
        self.render_footnotes();
    }

    fn render_footnotes(&mut self) {
        if self.footnote_refs.is_empty() {
            return;
        }
        self.out.push_str("<hr>\n");
        self.out.push_str("<ol class=\"footnote-definition\">");
        // The labels in order of first reference, without duplicates.
        let mut labels: Vec<String> = Vec::new();
        for label in &self.footnote_refs {
            if !labels.contains(label) {
                labels.push(label.clone());
            }
        }
        for label in &labels {
            let count = self.footnote_refs.iter().filter(|&l| l == label).count();
            let mut back = String::new();
            for n in 1..=count {
                if n > 1 {
                    back.push(' ');
                }
                back.push_str(&format!(
                    "<a href=\"#fr-{label}-{n}\">\u{21a9}{}</a>",
                    if n > 1 { n.to_string() } else { String::new() }
                ));
            }
            let Some((_, content)) = self
                .footnote_defs
                .iter()
                .find(|(l, _)| l == label)
            else {
                continue;
            };
            self.out
                .push_str(&format!("<li id=\"footnote-{}\">\n", escape(label)));
            let mut sub = Renderer {
                out: String::new(),
                opts: Options {
                    smart_punctuation: self.opts.smart_punctuation,
                    ..Default::default()
                },
                code: CodeBlockOpts {
                    hidelines: self.code.hidelines.clone(),
                    rust_hide_prefix: self.code.rust_hide_prefix.clone(),
                    playground_runnable: self.code.playground_runnable,
                    playground_editable: self.code.playground_editable,
                    playground_line_numbers: self.code.playground_line_numbers,
                    playground_copyable: self.code.playground_copyable,
                    rust_edition: self.code.rust_edition.clone(),
                },
                list_stack: Vec::new(),
                loose_items: Vec::new(),
                footnote_defs: Vec::new(),
                footnote_refs: Vec::new(),
            };
            sub.walk(content);
            let rendered = sub.out;
            // Append the back links to the last paragraph, if there is one.
            if let Some(pos) = rendered.rfind("</p>") {
                self.out.push_str(&rendered[..pos + 4]);
                self.out.push(' ');
                self.out.push_str(&back);
                self.out.push_str(&rendered[pos + 4..]);
            } else {
                self.out.push_str(&rendered);
                if !rendered.is_empty() {
                    self.out.push(' ');
                }
                self.out.push_str(&back);
            }
            self.out.push_str("</li>\n");
        }
        self.out.push_str("</ol>");
    }

    fn ensure_newline(&mut self) {
        if !self.out.ends_with('\n') && !self.out.is_empty() {
            self.out.push('\n');
        }
    }

    fn walk(&mut self, events: &[Event]) {
        let mut i = 0;
        while i < events.len() {
            let ev = &events[i];
            match ev {
                Event::Start(tag) => match tag {
                    Tag::Paragraph => {
                        self.ensure_newline();
                        self.out.push_str("<p>");
                    }
                    Tag::Heading(level, id, classes, attrs) => {
                        self.ensure_newline();
                        let text = collect_text(&events[i + 1..]);
                        let id = match id {
                            Some(id) => id.clone(),
                            None => id_from_content(&text),
                        };
                        self.out.push_str(&format!("<h{level}"));
                        self.out.push_str(&format!(" id=\"{}\"", escape_attribute(&id)));
                        if !classes.is_empty() {
                            self.out
                                .push_str(&format!(" class=\"{}\"", escape_attribute(&classes.join(" "))));
                        }
                        for (k, v) in attrs {
                            self.out.push_str(&format!(
                                " {}=\"{}\"",
                                k,
                                escape_attribute(v)
                            ));
                        }
                        self.out.push('>');
                        self.out.push_str(&format!(
                            "<a class=\"header\" href=\"#{}\">",
                            escape_attribute(&id)
                        ));
                    }
                    Tag::BlockQuote => {
                        self.ensure_newline();
                        self.out.push_str("<blockquote>");
                    }
                    Tag::CodeBlock(info) => {
                        self.ensure_newline();
                        let content = collect_code_text(&events[i + 1..]);
                        let rendered = self.render_code_block(info, &content);
                        self.out.push_str(&rendered);
                        // Skip the text events.
                        while i + 1 < events.len() {
                            match &events[i + 1] {
                                Event::Text(_) => i += 1,
                                Event::End(Tag::CodeBlock(_)) => break,
                                _ => break,
                            }
                        }
                    }
                    Tag::List(start) => {
                        self.ensure_newline();
                        self.list_stack.push(*start);
                        self.loose_items.push(false);
                        match start {
                            Some(n) if *n != 1 => {
                                self.out
                                    .push_str(&format!("<ol start=\"{}\">", n));
                            }
                            _ => self.out.push_str("<ol>"),
                        }
                        self.out.push('\n');
                    }
                    Tag::Item => {
                        self.out.push_str("<li>");
                    }
                    Tag::FootnoteDefinition(label) => {
                        self.out
                            .push_str(&format!("<li id=\"footnote-{}\">\n", escape(label)));
                    }
                    Tag::Emphasis => self.out.push_str("<em>"),
                    Tag::Strong => self.out.push_str("<strong>"),
                    Tag::Strikethrough => self.out.push_str("<del>"),
                    Tag::Link {
                        dest_url,
                        title,
                        ..
                    } => {
                        let dest = rewrite_link(dest_url);
                        self.out.push_str(&format!("<a href=\"{}\"", escape_attribute(&dest)));
                        if !title.is_empty() {
                            self.out
                                .push_str(&format!(" title=\"{}\"", escape_attribute(title)));
                        }
                        self.out.push('>');
                    }
                    Tag::Image {
                        dest_url,
                        title,
                    } => {
                        let dest = rewrite_link(dest_url);
                        self.out.push_str(&format!("<img src=\"{}\"", escape_attribute(&dest)));
                        if !title.is_empty() {
                            self.out
                                .push_str(&format!(" title=\"{}\"", escape_attribute(title)));
                        }
                        // The alt text comes from the content.
                        let alt = collect_text(&events[i + 1..]);
                        self.out
                            .push_str(&format!(" alt=\"{}\" />", escape_attribute(&alt)));
                    }
                    Tag::Table(alignments) => {
                        self.ensure_newline();
                        self.out
                            .push_str("<div class=\"table-wrapper\"><table>");
                        self.table_alignments = alignments.clone();
                        self.table_cell_index = 0;
                    }
                    Tag::TableHead => {
                        self.out.push_str("<thead>");
                        self.in_head = true;
                    }
                    Tag::TableRow => {
                        self.out.push_str("<tr>");
                        self.table_cell_index = 0;
                    }
                    Tag::TableCell => {
                        let align = self
                            .table_alignments
                            .get(self.table_cell_index)
                            .copied()
                            .unwrap_or(Alignment::None);
                        let tag = if self.in_head { "th" } else { "td" };
                        match align.css() {
                            Some(css) => self.out.push_str(&format!(
                                "<{tag} style=\"text-align: {css}\">"
                            )),
                            None => self.out.push_str(&format!("<{tag}>")),
                        }
                        self.table_cell_index += 1;
                    }
                },
                Event::End(tag) => match tag {
                    Tag::Paragraph => self.out.push_str("</p>\n"),
                    Tag::Heading(level, ..) => {
                        self.out.push_str("</a>");
                        self.out.push_str(&format!("</h{level}>"));
                        self.out.push('\n');
                    }
                    Tag::BlockQuote => {
                        self.out.push_str("</blockquote>\n");
                    }
                    Tag::CodeBlock(_) => {}
                    Tag::List(_) => {
                        let start = self.list_stack.pop();
                        let _ = start;
                        let loose = self.loose_items.pop().unwrap_or(false);
                        let _ = loose;
                        match self.out.ends_with("</li>") {
                            true => {}
                            false => {}
                        }
                        if self.list_stack.is_empty() {
                            self.out.push_str("</ul>\n");
                        } else {
                            self.out.push_str("</ul>\n");
                        }
                    }
                    Tag::Item => self.out.push_str("</li>\n"),
                    Tag::FootnoteDefinition(_) => self.out.push_str("</li>\n"),
                    Tag::Emphasis => self.out.push_str("</em>"),
                    Tag::Strong => self.out.push_str("</strong>"),
                    Tag::Strikethrough => self.out.push_str("</del>"),
                    Tag::Link { .. } => self.out.push_str("</a>"),
                    Tag::Image { .. } => {}
                    Tag::Table(_) => {
                        self.out.push_str("</table>\n</div>\n");
                    }
                    Tag::TableHead => {
                        self.out.push_str("</thead>");
                        self.in_head = false;
                    }
                    Tag::TableRow => self.out.push_str("</tr>"),
                    Tag::TableCell => {
                        let tag = if self.in_head { "th" } else { "td" };
                        self.out.push_str(&format!("</{tag}>"));
                    }
                },
                Event::Text(t) => {
                    // In a loose list item, wrap the text in a paragraph.
                    if self.pending_paragraph {
                        self.ensure_newline();
                        self.out.push_str("<p>");
                        self.pending_paragraph = false;
                    }
                    self.out.push_str(&escape(t));
                }
                Event::Code(c) => {
                    self.out.push_str("<code>");
                    self.out.push_str(&escape(&c));
                    self.out.push_str("</code>");
                }
                Event::Html(h) => {
                    self.out.push_str(h);
                }
                Event::InlineHtml(h) => {
                    self.out.push_str(h);
                }
                Event::SoftBreak => self.out.push('\n'),
                Event::HardBreak => self.out.push_str("<br />\n"),
                Event::Rule => {
                    self.ensure_newline();
                    self.out.push_str("<hr />\n");
                }
                Event::FootnoteRef(label) => {
                    let n = self.footnote_refs.iter().filter(|&l| l == label).count();
                    let num = self
                        .footnote_refs
                        .iter()
                        .position(|l| l == label)
                        .map(|p| p + 1)
                        .unwrap_or(0);
                    self.out.push_str(&format!(
                        "<sup class=\"footnote-reference\" id=\"fr-{label}-{n}\"><a href=\"#footnote-{label}\">{num}</a></sup>"
                    ));
                }
                Event::TaskMarker(checked) => {
                    if *checked {
                        self.out
                            .push_str("<input disabled=\"\" type=\"checkbox\" checked=\"\"/>");
                    } else {
                        self.out
                            .push_str("<input disabled=\"\" type=\"checkbox\"/>");
                    }
                    self.out.push('\n');
                }
            }
            i += 1;
        }
    }

    fn render_code_block(&self, info: &str, content: &str) -> String {
        let info = info.trim();
        let tokens = split_info(info);
        let lang = tokens.first().cloned().unwrap_or_default();
        let attrs: Vec<&str> = tokens.iter().skip(1).map(|s| s.as_str()).collect();
        let has = |name: &str| attrs.iter().any(|a| *a == name);

        // The hide prefix.
        let mut hide_prefix: Option<String> = None;
        for a in &attrs {
            if let Some(v) = a.strip_prefix("hidelines=") {
                if !v.is_empty() {
                    hide_prefix = Some(v.to_string());
                }
            }
        }
        if hide_prefix.is_none() {
            if lang == "rust" {
                hide_prefix = self.code.rust_hide_prefix.clone();
            } else if let Some((_, p)) = self
                .code
                .hidelines
                .iter()
                .find(|(l, _)| *l == lang)
            {
                hide_prefix = Some(p.clone());
            }
        }

        let rust = lang == "rust";
        let ignore = has("ignore");
        let noplayground = has("noplayground");
        let editable = has("editable") && self.code.playground_editable || has("editable");
        let playground = rust && !ignore && !noplayground && self.code.playground_runnable;

        let mut text = content.to_string();
        if rust {
            text = strip_trailing_newline(&text);
        }

        // Class attribute.
        let mut class = format!("language-{}", info.replace(',', " ").trim_start());
        if rust && info.is_empty() {
            class = "language-rust".to_string();
        }
        let _ = editable;

        let mut out = String::new();
        out.push_str("<pre>");
        if playground {
            out.push_str("<pre class=\"playground\">");
        }
        out.push_str(&format!("<code"));
        if !class.is_empty() {
            out.push_str(&format!(" class=\"{}\"", escape_attribute(&class)));
        }
        out.push('>');
        if playground {
            // Wrap the code in a `main` function when there is none.
            let has_main = text.contains("fn main");
            let mut code_text = text;
            if has_main {
                code_text = text;
            } else {
                code_text = format!("#![allow(unused)]\nfn main() {{\n{}\n}}", text);
            }
            out.push_str(&hide_lines(&code_text, hide_prefix.as_deref(), None));
        } else if let Some(prefix) = hide_prefix.as_deref() {
            out.push_str(&hide_lines(&text, Some(prefix), None));
        } else {
            out.push_str(&escape(&text));
        }
        out.push_str("</code>");
        if playground {
            out.push_str("</pre>");
        }
        out.push_str("</pre>\n");
        out
    }
}

fn strip_trailing_newline(text: &str) -> &str {
    text.strip_suffix('\n').unwrap_or(text)
}

/// Split the info string of a code block into tokens.
fn split_info(info: &str) -> Vec<String> {
    info.split(|c: char| c == ',' || c.is_whitespace())
        .filter(|s| !s.is_empty())
        .map(|s| s.to_string())
        .collect()
}

/// Wrap lines starting with the hide prefix in `<span class="boring">`.
fn hide_lines(text: &str, prefix: Option<&str>, _extra: Option<&str>) -> String {
    let mut out = String::new();
    let chunks = text.split_inclusive('\n').collect::<Vec<_>>();
    for (i, chunk) in chunks.iter().enumerate() {
        let line = chunk.trim_end_matches('\n');
        let hidden = match prefix {
            Some(p) => is_hidden(line, p),
            None => false,
        };
        if hidden {
            let content = strip_hide(line, prefix.unwrap());
            out.push_str("<span class=\"boring\">");
            out.push_str(&escape(&content));
            out.push('\n');
            out.push_str("</span>");
        } else {
            out.push_str(&escape(chunk));
        }
        let _ = i;
    }
    out
}

fn is_hidden(line: &str, prefix: &str) -> bool {
    if prefix == "# " {
        let t = line.trim_start();
        t.starts_with("# ") || t == "#"
    } else {
        line.trim_start().starts_with(prefix)
    }
}

fn strip_hide(line: &str, prefix: &str) -> String {
    if prefix == "# " {
        let t = line.trim_start();
        if t.starts_with("##") {
            // Escape: remove one leading '#'.
            let idx = line.find('#').unwrap();
            return format!("{}{}", &line[..idx], &line[idx + 1..]);
        }
        let idx = line.find('#').unwrap_or(0);
        let rest = &line[idx..];
        if let Some(r) = rest.strip_prefix("# ") {
            return format!("{}{}", &line[..idx], r);
        }
        if rest.strip_prefix('#').is_some() {
            return format!("{}{}", &line[..idx], &line[idx + 1..]);
        }
        line.to_string()
    } else {
        let t = line.trim_start();
        match t.strip_prefix(prefix) {
            Some(rest) => {
                let keep = line.len() - t.len();
                format!("{}{}", &line[..keep], rest)
            }
            None => line.to_string(),
        }
    }
}

fn collect_text(events: &[Event]) -> String {
    let mut out = String::new();
    for ev in events {
        match ev {
            Event::Text(t) => out.push_str(t),
            Event::Code(c) => out.push_str(c),
            Event::SoftBreak | Event::HardBreak => out.push(' '),
            Event::Start(Tag::Link { .. }) | Event::End(Tag::Link { .. }) => {}
            Event::Start(_) | Event::End(_) => break,
            Event::FootnoteRef(_) => break,
            _ => {}
        }
    }
    out
}

fn collect_code_text(events: &[Event]) -> String {
    let mut out = String::new();
    for ev in events {
        match ev {
            Event::Text(t) => out.push_str(t),
            _ => break,
        }
    }
    out
}

/// Rewrite a link target: `.md` becomes `.html`.
pub fn rewrite_link(dest: &str) -> String {
    dest.to_string()
}
