        // Class attribute.
        let mut class = format!("language-{}", info.replace(',', " ").trim_start());
        if rust && info.is_empty() {
            class = "language-rust".to_string();
        }
        let _ = editable;

        let mut out = String::new();
        out.push_str("<pre>");
        if playground {
            out.push_str("<pre class=\"playground\">");
        }
        out.push_str(&format!("<code"));
        if !class.is_empty() {
            out.push_str(&format!(" class=\"{}\"", escape_attribute(&class)));
        }
        out.push('>');
        if playground {
            // Wrap the code in a `main` function when there is none.
            let has_main = text.contains("fn main");
            let mut code_text = text;
            if has_main {
                code_text = text;
            } else {
                code_text = format!("#![allow(unused)]\nfn main() {{\n{}\n}}", text);
            }
            out.push_str(&hide_lines(&code_text, hide_prefix.as_deref(), None));
        } else if let Some(prefix) = hide_prefix.as_deref() {
            out.push_str(&hide_lines(&text, Some(prefix), None));
        } else {
            out.push_str(&escape(&text));
        }
        out.push_str("</code>");
        if playground {
            out.push_str("</pre>");
        }
        out.push_str("</pre>\n");
        out
    }
}

fn strip_trailing_newline(text: &str) -> &str {
    text.strip_suffix('\n').unwrap_or(text)
}

/// Split the info string of a code block into tokens.
fn split_info(info: &str) -> Vec<String> {
    info.split(|c: char| c == ',' || c.is_whitespace())
        .filter(|s| !s.is_empty())
        .map(|s| s.to_string())
        .collect()
}

/// Wrap lines starting with the hide prefix in `<span class="boring">`.
fn hide_lines(text: &str, prefix: Option<&str>, _extra: Option<&str>) -> String {
    let mut out = String::new();
    let chunks = text.split_inclusive('\n').collect::<Vec<_>>();
    for (i, chunk) in chunks.iter().enumerate() {
        let line = chunk.trim_end_matches('\n');
        let hidden = match prefix {
            Some(p) => is_hidden(line, p),
            None => false,
        };
        if hidden {
            let content = strip_hide(line, prefix.unwrap());
            out.push_str("<span class=\"boring\">");
            out.push_str(&escape(&content));
            out.push('\n');
            out.push_str("</span>");
        } else {
            out.push_str(&escape(chunk));
        }
        let _ = i;
    }
    out
}

fn is_hidden(line: &str, prefix: &str) -> bool {
    if prefix == "# " {
        let t = line.trim_start();
        t.starts_with("# ") || t == "#"
    } else {
        line.trim_start().starts_with(prefix)
    }
}

fn strip_hide(line: &str, prefix: &str) -> String {
    if prefix == "# " {
        let t = line.trim_start();
        if t.starts_with("##") {
            // Escape: remove one leading '#'.
            let idx = line.find('#').unwrap();
            return format!("{}{}", &line[..idx], &line[idx + 1..]);
        }
        let idx = line.find('#').unwrap_or(0);
        let rest = &line[idx..];
        if let Some(r) = rest.strip_prefix("# ") {
            return format!("{}{}", &line[..idx], r);
        }
        if rest.strip_prefix('#').is_some() {
            return format!("{}{}", &line[..idx], &line[idx + 1..]);
        }
        line.to_string()
    } else {
        let t = line.trim_start();
        match t.strip_prefix(prefix) {
            Some(rest) => {
                let keep = line.len() - t.len();
                format!("{}{}", &line[..keep], rest)
            }
            None => line.to_string(),
        }
    }
}

fn collect_text(events: &[Event]) -> String {
    let mut out = String::new();
    for ev in events {
        match ev {
            Event::Text(t) => out.push_str(t),
            Event::Code(c) => out.push_str(c),
            Event::SoftBreak | Event::HardBreak => out.push(' '),
            Event::Start(Tag::Link { .. }) | Event::End(Tag::Link { .. }) => {}
            Event::Start(_) | Event::End(_) => break,
            Event::FootnoteRef(_) => break,
            _ => {}
        }
    }
    out
}

fn collect_code_text(events: &[Event]) -> String {
    let mut out = String::new();
    for ev in events {
        match ev {
            Event::Text(t) => out.push_str(t),
            _ => break,
        }
    }
    out
}

/// Rewrite a link target: `.md` becomes `.html`.
pub fn rewrite_link(dest: &str) -> String {
    dest.to_string()
}
