        let mut class = format!("language-{}", info.replace(',', " ").trim_start());
        if rust && info.is_empty() {
            class = "language-rust".to_string();
        }
        let _ = editable;

        let mut out = String::new();
        out.push_str("<pre>");
        if playground {
            out.push_str("<pre class=\"playground\">");
        }
        out.push_str(&format!("<code"));
        if !class.is_empty() {
            out.push_str(&format!(" class=\"{}\"", escape_attribute(&class)));
        }
        out.push('>');
        if playground {
            // Wrap the code in a `main` function when there is none.
            let has_main = text.contains("fn main");
            let mut code_text = text;
            if has_main {
                code_text = text;
            } else {
                code_text = format!("#![allow(unused)]\nfn main() {{\n{}\n}}", text);
            }
            out.push_str(&hide_lines(&code_text, hide_prefix.as_deref(), None));
        } else if let Some(prefix) = hide_prefix.as_deref() {
            out.push_str(&hide_lines(&text, Some(prefix), None));
        } else {
            out.push_str(&escape(&text));
        }
