}

fn collect_text(events: &[Event]) -> String {
    let mut out = String::new();
    for ev in events {
        match ev {
            Event::Text(t) => out.push_str(t),
            Event::Code(c) => out.push_str(c),
            Event::SoftBreak | Event::HardBreak => out.push(' '),
            Event::Start(Tag::Link { .. }) | Event::End(Tag::Link { .. }) => {}
            Event::Start(_) | Event::End(_) => break,
            Event::FootnoteRef(_) => break,
            _ => {}
        }
    }
    out
}

fn collect_code_text(events: &[Event]) -> String {
    let mut out = String::new();
    for ev in events {
        match ev {
            Event::Text(t) => out.push_str(t),
            _ => break,
        }
    }
    out
}

/// Rewrite a link target: `.md` becomes `.html`.
pub fn rewrite_link(dest: &str) -> String {
    dest.to_string()
}
