/// Strip at most `n` characters of leading whitespace.
fn strip_indent(line: &str, n: usize) -> &str {
    let mut count = 0;
    let mut idx = 0;
    for c in line.chars() {
        if count >= n {
            break;
        }
        if c == ' ' {
            count += 1;
            idx += 1;
        } else if c == '\\t' {
            count += 4;
            idx += 1;
        } else {
            break;
        }
    }
    &line[idx..]
}

/// Recognise a task list marker, returning whether it is checked and the rest.
fn task_marker(text: &str) -> Option<(bool, &str)> {
    let t = text.strip_prefix('[')?;
    let (c, rest) = match t.chars().next()? {
        ' ' => (false, &t[1..]),
        'x' | 'X' => (true, &t[1..]),
        _ => return None,
    };
    if rest.starts_with(']') {
        let after = &rest[1..];
        if after.is_empty() || after.starts_with(' ') {
            return Some((c, after.strip_prefix(' ').unwrap_or(after)));
        }
    }
    None
}""")
