use std::path::PathBuf;

/// A path relative to the book root.
#[derive(Clone, PartialEq, Eq, Default, Hash)]
pub struct Path(pub PathBuf);

impl fmt::Debug for Path {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{:?}", self.0)
    }
}

impl Path {
    pub fn as_str(&self) -> &str {
        self.0.to_str().unwrap_or_default()
    }
}

impl<'de> serde::Deserializer<'de> for Path {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> std::result::Result<Self, D::Error> {
        struct V;
        impl<'de> serde::de::Visitor<'de> for V {
            type Value = Path;
            fn expecting(&self, f: &mut fmt::Formatter) -> fmt::Result {
                f.write_str("path string")
            }
            fn visit_str<E: serde::de::Error>(self, s: &str) -> std::result::Result<Path, E> {
                Ok(Path(PathBuf::from(s)))
            }
        }
        d.deserialize_string(V)
    }
}

impl From<&str> for Path {
    fn from(s: &str) -> Path {
        Path(PathBuf::from(s))
    }
}

/// The direction the text is written in.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TextDirection {
    #[serde(rename = "ltr")]
    LeftToRight,
    #[serde(rename = "rtl")]
    RightToLeft,
}

impl TextDirection {
    pub fn from_language(lang: &str) -> TextDirection {
        match lang {
            "ar" | "he" | "fa" | "ur" | "ps" | "yi" | "sd" | "ug" | "prs" | "dv" | "ks" | "ur"
            | "ckb" | "mzn" | "nqo" | "lif" | "azb" | "pnb" | "skr" | "bal" | "bcc" | "kxo"
            | "hne" | "pnb" | "ksh" | "pnt" | "haz" | "rkt" | "rhg" | "raj" | "haz" => {
                TextDirection::RightToLeft
            }
            _ => TextDirection::LeftToRight,
        }
    }
}

