/// `MDBOOK_FOO_bar__baz` becomes `foo-bar.baz`.
fn env_key(name: &str) -> String {
    let lower = name.to_lowercase();
    let dotted = lower.replace("__", ".");
    dotted.replace('_', "-")
}

/// Convert a JSON value into a TOML value.
fn toml_value_from_json(json: &serde_json::Value) -> Option<toml::Value> {
    Some(match json {
        serde_json::Value::Null => return None,
        serde_json::Value::Bool(b) => toml::Value::Boolean(*b),
        serde_json::Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                toml::Value::Integer(i)
            } else if let Some(f) = n.as_f64() {
                toml::Value::Float(f)
            } else {
                return None;
            }
        }
        serde_json::Value::String(s) => toml::Value::String(s.clone()),
        serde_json::Value::Array(items) => toml::Value::Array(
            items
                .iter()
                .map(toml_value_from_json)
                .collect::<Option<Vec<_>>>()?,
        ),
        serde_json::Value::Object(map) => {
            let mut table = toml::map::Map::new();
            for (k, v) in map {
                table.insert(k.clone(), toml_value_from_json(v)?);
            }
            toml::Value::Table(table)
        }
    })
}

/// Insert a value at a dotted path, creating the intermediate tables.
fn insert_path(table: &mut toml::Table, path: &str, value: toml::Value) {
    let parts: Vec<&str> = path.split('.').collect();
    insert_parts(table, &parts, value);
}

fn insert_parts(table: &mut toml::Table, parts: &[&str], value: toml::Value) {
    if parts.len() == 1 {
        table.insert(parts[0].to_string(), value);
        return;
    }
    let key = parts[0].to_string();
    let entry = table
        .entry(key)
        .or_insert_with(|| toml::Value::Table(toml::map::Map::new()));
    match entry {
        toml::Value::Table(t) => insert_parts(t, &parts[1..], value),
        _ => {
            *entry = toml::Value::Table(toml::map::Map::new());
            if let toml::Value::Table(t) = entry {
                insert_parts(t, &parts[1..], value);
            }
        }
    }
}
