const KNOWN_TOP_LEVEL: [&str; 5] = ["book", "build", "rust", "output", "preprocessor"];

impl Config {
    /// Parse the configuration from the contents of a `book.toml` file.
    pub fn from_str(text: &str) -> Result<Config> {
        let table: toml::Table = toml::from_str(text)
            .map_err(|e| Error::new("Invalid configuration file").with(format!("{e}")))?;

        // Warn about fields that are not understood.
        for key in table.keys() {
            if !KNOWN_TOP_LEVEL.contains(&key.as_str()) {
                crate::log::log(
                    crate::log::Level::Warn,
                    "mdbook_core::config",
                    format_args!("Invalid field \"{key}\" in book.toml"),
                );
            }
        }

        let mut config = Config {
            book: section(&table, "book")?,
            build: section(&table, "build")?,
            rust: section(&table, "rust")?,
            rest: toml::Value::Table(table_without(&table, &["book", "build", "rust"])),
        };
        config.language_defaults();
        Ok(config)
    }

    /// The default `en` language, when none is given.
    fn language_defaults(&mut self) {
        if self.book.language.is_none() {
            self.book.language = Some("en".to_string());
        }
    }

    /// The text direction, derived from the language when not set.
    pub fn html_text_direction(&self) -> crate::config::TextDirection {
        match self.book.text_direction {
            Some(d) => d,
            None => TextDirection::from_language(self.book.language.as_deref().unwrap_or("en")),
        }
    }

    /// The `[output.html]` section, if present.
    pub fn html_config(&self) -> std::result::Result<Option<HtmlConfig>, Error> {
        let Some(output) = self.rest.get("output") else {
            return Ok(None);
        };
        let Some(html) = output.get("html") else {
            return Ok(None);
        };
        let cfg: HtmlConfig = html
            .clone()
            .try_into()
            .map_err(|e: toml::de::Error| {
                Error::new("Couldn't deserialize the value").with(format!("{e}"))
            })?;
        Ok(Some(cfg))
    }

    /// Update the configuration from the `MDBOOK_` environment variables.
    pub fn update_from_env(&mut self) {
        crate::log::log(
            crate::log::Level::Debug,
            "mdbook_core::config",
            format_args!("Updating the config from environment variables"),
        );
        let mut vars: Vec<(String, String)> = std::env::vars()
            .filter(|(k, _)| k.starts_with("MDBOOK_"))
            .collect();
        vars.sort();
        let original = self.clone();
        for (name, value) in vars {
            let key = env_key(&name[7..]);
            crate::log::log(
                crate::log::Level::Trace,
                "mdbook_core::config",
                format_args!("{key} => {value}"),
            );
            let json: serde_json::Value = match serde_json::from_str(&value) {
                Ok(v) => v,
                Err(_) => serde_json::Value::String(value.clone()),
            };
            let toml_value = match toml_value_from_json(&json) {
                Some(v) => v,
                None => crate::errors::panic_message(
                    "unreachable: Unable to represent the item as a JSON Value",
                    "unsupported unit type",
                ),
            };
            let mut table = self.table();
            insert_path(&mut table, &key, toml_value);
            match Config::from_table(table) {
                Ok(c) => {
                    let _ = &original;
                    *self = c;
                }
                Err(_) => {
                    // The value could not be applied; keep the original.
                    *self = original.clone();
                }
            }
        }
    }

    fn table(&self) -> toml::Table {
        let mut table = match self.rest.clone() {
            toml::Value::Table(t) => t,
            _ => toml::map::Map::new(),
        };
        table.insert(
            "book".to_string(),
            toml::Value::try_from(&self.book).unwrap_or(toml::Value::Table(toml::map::Map::new())),
        );
        table.insert(
            "build".to_string(),
            toml::Value::try_from(&self.build)
                .unwrap_or(toml::Value::Table(toml::map::Map::new())),
        );
        table.insert(
            "rust".to_string(),
            toml::Value::try_from(&self.rust).unwrap_or(toml::Value::Table(toml::map::Map::new())),
        );
        table
    }

    fn from_table(mut table: toml::Table) -> Result<Config> {
        let mut config = Config {
            book: section(&table, "book")?,
            build: section(&table, "build")?,
            rust: section(&table, "rust")?,
            rest: toml::Value::Table(table_without(&table, &["book", "build", "rust"])),
        };
        config.language_defaults();
        Ok(config)
    }

    pub fn clone(&self) -> Config {
        Config {
            book: self.book.clone(),
            build: self.build.clone(),
            rust: self.rust.clone(),
            rest: self.rest.clone(),
        }
    }
}

fn section<T: for<'de> Deserialize<'de> + Default>(table: &toml::Table, key: &str) -> Result<T> {
    let value = table.get(key).cloned().unwrap_or(toml::Value::Table(toml::map::Map::new()));
    value
        .try_into::<T>()
        .map_err(|e: toml::de::Error| Error::new("Invalid configuration file").with(format!("{e}")))
}

fn table_without(table: &toml::Table, keys: &[&str]) -> toml::Table {
    let mut out = toml::map::Map::new();
    for (k, v) in table {
        if keys.contains(&k.as_str()) {
            continue;
        }
        out.insert(k.clone(), v.clone());
    }
    out
}

/// `MDBOOK_FOO_bar__baz` becomes `foo-bar.baz`.
fn env_key(name: &str) -> String {
    let lower = name.to_lowercase();
    let dotted = lower.replace("__", ".");
    dotted.replace('_', "-")
}

/// Convert a JSON value into a TOML value.
fn toml_value_from_json(json: &serde_json::Value) -> Option<toml::Value> {
    Some(match json {
        serde_json::Value::Null => return None,
        serde_json::Value::Bool(b) => toml::Value::Boolean(*b),
        serde_json::Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                toml::Value::Integer(i)
            } else if let Some(f) = n.as_f64() {
                toml::Value::Float(f)
            } else {
                return None;
            }
        }
        serde_json::Value::String(s) => toml::Value::String(s.clone()),
        serde_json::Value::Array(items) => toml::Value::Array(
            items
                .iter()
                .map(toml_value_from_json)
                .collect::<Option<Vec<_>>>()?,
        ),
        serde_json::Value::Object(map) => {
            let mut table = toml::map::Map::new();
            for (k, v) in map {
                table.insert(k.clone(), toml_value_from_json(v)?);
            }
            toml::Value::Table(table)
        }
    })
}

/// Insert a value at a dotted path, creating the intermediate tables.
fn insert_path(table: &mut toml::Table, path: &str, value: toml::Value) {
    let parts: Vec<&str> = path.split('.').collect();
    insert_parts(table, &parts, value);
}

fn insert_parts(table: &mut toml::Table, parts: &[&str], value: toml::Value) {
    if parts.len() == 1 {
        table.insert(parts[0].to_string(), value);
        return;
    }
    let key = parts[0].to_string();
    let entry = table
        .entry(key)
        .or_insert_with(|| toml::Value::Table(toml::map::Map::new()));
    match entry {
        toml::Value::Table(t) => insert_parts(t, &parts[1..], value),
        _ => {
            *entry = toml::Value::Table(toml::map::Map::new());
            if let toml::Value::Table(t) = entry {
                insert_parts(t, &parts[1..], value);
            }
        }
    }
}
