                            out.push(SummaryItem::Link {
                                name,
                                path,
                            });
                            if !children.is_empty() {
                                out.extend(children);
                            }
                            number += 1;
                            i = item_end;
                            // Skip the End(Item).
                            if matches!(events.get(i), Some(Event::End(Tag::Item))) {
                                i += 1;
                            }
                        }
                        Event::End(Tag::List(_)) => {
                            i += 1;
                            break;
                        }
                        _ => {
                            i += 1;
                        }
                    }
                }
                level += 1;
            }
            Event::End(Tag::List(_)) => {
                i += 1;
                break;
            }
            _ => {
                i += 1;
            }
        }
    }
    i
}

