//! Parsing of `SUMMARY.md`.

use crate::errors::{Error, Result};
use crate::md::block::{self, Options as MdOptions};
use crate::md::events::{Event, Tag};
use std::path::PathBuf;

#[derive(Debug, Clone, PartialEq)]
pub enum SummaryItem {
    Link {
        name: String,
        path: PathBuf,
    },
    Separator,
    PartTitle(String),
}

#[derive(Debug, Clone, Default)]
pub struct Summary {
    pub title: String,
    pub prefix_chapters: Vec<SummaryItem>,
    pub numbered_chapters: Vec<SummaryItem>,
    pub suffix_chapters: Vec<SummaryItem>,
}

pub const LOG_TARGET: &str = "mdbook_summary";

/// Parse a `SUMMARY.md` file.
pub fn parse_summary(text: &str) -> Result<Summary> {
    let opts = MdOptions::default();
    let events = block::parse(text, &opts);
    crate::log::log(
        crate::log::Level::Trace,
        LOG_TARGET,
        format_args!("Found a h1 in the SUMMARY"),
    );
    // The first h1 is the title of the summary.
    let mut i = 0;
    let mut title = String::new();
    let mut h1_found = false;
    while i < events.len() {
        match &events[i] {
            Event::Start(Tag::Heading(1, ..)) => {
                crate::log::log(
                    crate::log::Level::Debug,
                    LOG_TARGET,
                    format_args!("Found a h1 in the SUMMARY"),
                );
                // Consume the heading.
                let mut j = i + 1;
                while j < events.len() {
                    if matches!(events[j], Event::End(Tag::Heading(1, ..))) {
                        break;
                    }
                    j += 1;
                }
                title = collect_text(&events[i + 1..j]);
                h1_found = true;
                i = j + 1;
                break;
            }
            _ => i += 1,
        }
    }
    if !h1_found {
        i = 0;
    }

    let mut summary = Summary {
        title,
        ..Default::default()
    };

    crate::log::log(
        crate::log::Level::Debug,
        LOG_TARGET,
        format_args!("Parsing prefix items"),
    );
    i = parse_items(&events, i, &mut summary.prefix_chapters, false);

    crate::log::log(
        crate::log::Level::Debug,
        LOG_TARGET,
        format_args!("Parsing numbered chapters at level 0"),
    );
    i = parse_numbered(&events, i, &mut summary.numbered_chapters, &mut Vec::new(), 1);

    crate::log::log(
        crate::log::Level::Debug,
        crate::log::Level::Info,
        format_args!("Parsing suffix items"),
    );
    let _ = crate::log::Level::Debug;
    i = parse_items(&events, i, &mut summary.suffix_chapters, false);

    Ok(summary)
}

/// Collect the text of a list of events.
fn collect_text(events: &[Event]) -> String {
    let mut out = String::new();
    for ev in events {
        match ev {
            Event::Text(t) => out.push_str(t),
            Event::SoftBreak | Event::HardBreak => out.push(' '),
            _ => {}
        }
    }
    out
}

/// Parse root level items (links, separators and part titles).
fn parse_items(
    events: &[Event],
    mut i: usize,
    out: &mut Vec<SummaryItem>,
    _top: bool,
) -> usize {
    while i < events.len() {
        match &events[i] {
            Event::Rule => {
                crate::log::log(
                    crate::log::Level::Trace,
                    LOG_TARGET,
                    format_args!("Found separator"),
                );
                out.push(SummaryItem::Separator);
                i += 1;
            }
            Event::Start(Tag::Heading(1, ..)) => {
                let mut j = i + 1;
                while j < events.len() {
                    if matches!(events[j], Event::End(Tag::Heading(1, ..))) {
                        break;
                    }
                    j += 1;
                }
                let title = collect_text(&events[i + 1..j]);
                out.push(SummaryItem::PartTitle(title));
                i = j + 1;
            }
            Event::Start(Tag::List(_)) | Event::End(Tag::List(_)) => {
                crate::log::log(
                    crate::log::Level::Trace,
                    LOG_TARGET,
                    format_args!("Back: {:?}", events[i]),
                );
                break;
            }
            Event::Start(Tag::Link { dest_url, .. }) => {
                let mut j = i + 1;
                while j < events.len() {
                    if matches!(events[j], Event::End(Tag::Link { .. })) {
                        break;
                    }
                    j += 1;
                }
                let name = collect_text(&events[i + 1..j]);
                if dest_url.is_empty() {
                    crate::log::log(
                        crate::log::Level::Trace,
                        LOG_TARGET,
                        format_args!("Draft chapter: {name}"),
                    );
                } else {
                    crate::log::log(
                        crate::log::Level::Trace,
                        LOG_TARGET,
                        format_args!("Found prefix/suffix chapter: {name} ({dest_url})"),
                    );
                }
                out.push(SummaryItem::Link {
                    name,
                    path: PathBuf::from(dest_url),
                });
                i = j + 1;
            }
            Event::End(Tag::Paragraph) => {
                i += 1;
            }
            Event::Start(Tag::Paragraph) => {
                i += 1;
            }
            _ => i += 1,
        }
    }
    i
}

/// Parse the numbered chapters, which are nested lists.
fn parse_numbered(
    events: &[Event],
    mut i: usize,
    out: &mut Vec<SummaryItem>,
    numbers: &mut Vec<u64>,
    _level: u64,
) -> usize {
    while i < events.len() {
        match &events[i] {
            Event::Start(Tag::List(_)) => {
                // Parse the items of this list.
                i += 1;
                let mut number = 1;
                let mut level = numbers.len();
                while i < events.len() {
                    match &events[i] {
                        Event::Start(Tag::Item) => {
                            crate::log::log(
                                crate::log::Level::Trace,
                                LOG_TARGET,
                                format_args!("Next event: Some(Start(Item))"),
                            );
                            // The item content: a link, then optionally a nested list.
                            i += 1;
                            let mut name = String::new();
                            let mut path = PathBuf::new();
                            let mut item_end = i;
                            // The link
                            if matches!(events.get(i), Some(Event::Start(Tag::Link { dest_url, .. }))) {
                                let dest = match &events[i] {
                                    Event::Start(Tag::Link { dest_url, .. }) => dest_url.clone(),
                                    _ => String::new(),
                                };
                                let mut j = i + 1;
                                while j < events.len() {
                                    if matches!(events[j], Event::End(Tag::Link { .. })) {
                                        break;
                                    }
                                    j += 1;
                                }
                                name = collect_text(&events[i + 1..j]);
                                path = PathBuf::from(dest);
                                item_end = j + 1;
                            } else if matches!(events.get(i), Some(Event::Text(_))) {
                                // A part title inside a list?
                                let text = match &events[i] {
                                    Event::Text(t) => t.clone(),
                                    _ => String::new(),
                                };
                                out.push(SummaryItem::PartTitle(text));
                                i += 1;
                                continue;
                            } else {
                                i = item_end;
                                continue;
                            }
                            // The nested list, if any.
                            let mut children: Vec<SummaryItem> = Vec::new();
                            let mut nested = false;
                            if matches!(events.get(item_end), Some(Event::Start(Tag::List(_)))) {
                                crate::log::log(
                                    crate::log::Level::Debug,
                                    LOG_TARGET,
                                    format_args!("Parsing numbered chapters at level {level}.{number}."),
                                );
                                nested = true;
                                numbers.push(number);
                                item_end = parse_numbered(
                                    events,
                                    item_end,
                                    &mut children,
                                    numbers,
                                    level + 1,
                                );
                                numbers.pop();
                            }
                            crate::log::log(
                                crate::log::Level::Trace,
                                LOG_TARGET,
                                format_args!(
                                    "Found chapter: {}. {} ({})",
                                    format_number(numbers, number),
                                    name,
                                    path.display()
                                ),
                            );
                            let _ = nested;
                            out.push(SummaryItem::Link {
                                name,
                                path,
                            });
                            if !children.is_empty() {
                                out.extend(children);
                            }
                            number += 1;
                            i = item_end;
                            // Skip the End(Item).
                            if matches!(events.get(i), Some(Event::End(Tag::Item))) {
                                i += 1;
                            }
                        }
                        Event::End(Tag::List(_)) => {
                            i += 1;
                            break;
                        }
                        _ => {
                            i += 1;
                        }
                    }
                }
                level += 1;
            }
            Event::End(Tag::List(_)) => {
                i += 1;
                break;
            }
            _ => {
                i += 1;
            }
        }
    }
    i
}

pub fn format_number(numbers: &[u64], last: u64) -> String {
    let mut parts: Vec<String> = numbers.iter().map(|n| n.to_string()).collect();
    parts.push(last.to_string());
    parts.join(".")
}
