                    }
                    n if n == "else" => {
                        // Handled by the block parser.
                        return nodes;
                    }
                    _ => {
                        let raw = tag.triple;
                        nodes.push(Node::Expr {
                            raw,
                            expr: tag.name,
                        });
                    }
                }
                continue;
            }
            let c = self.chars[self.pos];
            text.push(c);
            self.pos += 1;
        }
        if !text.is_empty() {
            nodes.push(Node::Text(text));
        }
        nodes
    }

    fn skip_line_end(&mut self) {
        // Remove trailing whitespace up to and including the newline.
        while self.pos < self.chars.len() && (self.chars[self.pos] == ' ' || self.chars[self.pos] == '\t')
        {
            self.pos += 1;
        }
        if self.pos < self.chars.len() && self.chars[self.pos] == '\n' {
            self.pos += 1;
        } else if self.pos + 1 < self.chars.len()
            && self.chars[self.pos] == '\r'
            && self.chars[self.pos + 1] == '\n'
        {
            self.pos += 2;
        }
    }

    fn rest_of_line_is_whitespace(&self) -> bool {
        let mut i = self.pos;
        while i < self.chars.len() && (self.chars[i] == ' ' || self.chars[i] == '\t') {
            i += 1;
        }
        if i >= self.chars.len() {
            return true;
        }
        self.chars[i] == '\n'
    }

    /// Read a `{{ ... }}` tag, returning its content and the end position.
    fn read_tag(&mut self) -> Option<(TagInfo, usize)> {
        let triple = self.starts_with("{{{");
        let open_len = if triple { 3 } else { 2 };
        let mut i = self.pos + open_len;
        let mut depth = 0;
        let mut content = String::new();
        while i < self.chars.len() {
            if self.chars[i] == '{' {
                depth += 1;
            }
            if self.chars[i] == '}' {
                if depth > 0 {
                    depth -= 1;
                    content.push('}');
                    i += 1;
                    continue;
                }
                if triple {
                    if self.chars.get(i + 1) == Some(&'}') && self.chars.get(i + 2) == Some(&'}') {
                        self.pos = i + 3;
                        return Some((
                            TagInfo {
                                name: content.trim().to_string(),
                                triple: true,
                            },
                            i + 3,
                        ));
                    }
                } else {
                    self.pos = i + 2;
                    return Some((
                        TagInfo {
                            name: content.trim().to_string(),
                            triple: false,
                        },
                        i + 2,
                    ));
                }
            }
            content.push(self.chars[i]);
            i += 1;
        }
        None
    }
}

struct TagInfo {
    name: String,
    triple: bool,
}

fn parse_args(s: &str) -> Vec<Arg> {
    let mut args = Vec::new();
    let mut tokens = s.split_whitespace();
    // The first token is the helper name.
    tokens.next();
    for tok in tokens {
        if tok.starts_with('"') && tok.ends_with('"') && tok.len() >= 2 {
            args.push(Arg::Value(Value::Str(tok[1..tok.len() - 1].to_string())));
        } else {
            args.push(Arg::Path(tok.to_string()));
        }
    }
    args
}

fn render_nodes(nodes: &[Node], ctx: &Context, helpers: &dyn Helper, out: &mut String, _raw: bool) {
    for node in nodes {
        match node {
            Node::Text(t) => out.push_str(t),
            Node::Expr { raw, expr } => {
                let value = ctx.lookup(expr).unwrap_or(Value::Null);
                let s = value.render();
                if *raw {
                    out.push_str(&s);
                } else {
                    out.push_str(&escape(&s));
                }
            }
            Node::Partial(name) => {
                let _ = name;
            }
            Node::Block {
                name,
                args,
                body,
                inverse,
            } => {
                match name.as_str() {
                    "if" => {
                        let cond = args
                            .first()
                            .map(|a| match a {
                                Arg::Value(v) => v.clone(),
                                Arg::Path(p) => ctx.lookup(p).unwrap_or(Value::Null),
                            })
                            .unwrap_or(Value::Null);
                        if cond.truthy() {
                            render_nodes(body, ctx, helpers, out, false);
                        } else {
                            render_nodes(inverse, ctx, helpers, out, false);
                        }
                    }
                    "each" => {
                        let list = args
                            .first()
                            .map(|a| match a {
                                Arg::Value(v) => v.clone(),
                                Arg::Path(p) => ctx.lookup(p).unwrap_or(Value::Null),
                            })
                            .unwrap_or(Value::Null);
                        match list {
                            Value::Array(items) => {
                                let n = items.len();
                                for (i, item) in items.into_iter().enumerate() {
                                    let mut frame = match &item {
                                        Value::Object(_) => item.clone(),
                                        _ => Value::Object(vec![(
                                            "this".to_string(),
                                            item.clone(),
                                        )]),
                                    };
                                    frame
                                        .0
                                        .push(("@index".to_string(), Value::Int(i as i64)));
                                    frame.0.push(("@first".to_string(), Value::Bool(i == 0)));
                                    frame
                                        .0
                                        .push(("@last".to_string(), Value::Bool(i + 1 == n)));
                                    let sub = Context {
                                        stack: {
                                            let mut s = ctx.stack.clone();
                                            s.push(&frame);
                                            s
                                        },
                                    };
                                    render_nodes(body, &sub, helpers, out, false);
                                }
                            }
                            Value::Object(items) => {
                                let n = items.len();
                                for (i, (k, v)) in items.into_iter().enumerate() {
                                    let frame =
                                        Value::Object(vec![("key".to_string(), Value::Str(k))])
                                            .merge(v);
                                    let mut frame = frame;
                                    frame
                                        .0
                                        .push(("@index".to_string(), Value::Int(i as i64)));
                                    frame.0.push(("@first".to_string(), Value::Bool(i == 0)));
                                    frame
                                        .0
                                        .push(("@last".to_string(), Value::Bool(i + 1 == n)));
                                    let sub = Context {
                                        stack: {
                                            let mut s = ctx.stack.clone();
                                            s.push(&frame);
                                            s
                                        },
                                    };
                                    render_nodes(body, &sub, helpers, out, false);
                                }
                            }
                            _ => render_nodes(inverse, ctx, helpers, out, false),
                        }
                    }
                    _ => {
                        // A custom block helper.
                        let params: Vec<Value> = args
                            .iter()
                            .map(|a| match a {
                                Arg::Value(v) => v.clone(),
                                Arg::Path(p) => ctx.lookup(p).unwrap_or(Value::Null),
                            })
                            .collect();
                        let rendered = helpers.call(
                            name,
                            &params,
                            &HashMap::new(),
                            Some(body),
                            Some(inverse),
                            &|f| {
                                // Render the body with the same context.
                                let mut sub = String::new();
                                render_nodes(body, ctx, helpers, &mut sub, false);
                                let _ = f;
                                sub
                            },
                        );
                        out.push_str(&rendered);
                    }
                }
            }
        }
    }
}

impl Value {
    fn merge(self, other: Value) -> Value {
        match (self, other) {
            (Value::Object(mut a), Value::Object(b)) => {
                a.extend(b);
                Value::Object(a)
            }
            (_, other) => other,
        }
    }
}
