//! A small handlebars-compatible template engine.

use std::collections::HashMap;

#[derive(Clone, Debug, PartialEq)]
pub enum Value {
    Null,
    Bool(bool),
    Int(i64),
    Float(f64),
    Str(String),
    Array(Vec<Value>),
    Object(Vec<(String, Value)>),
}

impl Value {
    pub fn str(s: impl Into<String>) -> Value {
        Value::Str(s.into())
    }

    pub fn obj(items: Vec<(&str, Value)>) -> Value {
        Value::Object(items.into_iter().map(|(k, v)| (k.to_string(), v)).collect())
    }

    pub fn as_str(&self) -> Option<&str> {
        match self {
            Value::Str(s) => Some(s),
            _ => None,
        }
    }

    pub fn truthy(&self) -> bool {
        match self {
            Value::Null => false,
            Value::Bool(b) => *b,
            Value::Int(i) => *i != 0,
            Value::Float(f) => *f != 0.0,
            Value::Str(s) => !s.is_empty(),
            Value::Array(a) => !a.is_empty(),
            Value::Object(_) => true,
        }
    }

    /// The value as it is rendered by `{{ }}`.
    pub fn render(&self) -> String {
        match self {
            Value::Null => String::new(),
            Value::Bool(b) => b.to_string(),
            Value::Int(i) => i.to_string(),
            Value::Float(f) => fmt_float(*f),
            Value::Str(s) => s.clone(),
            Value::Array(_) => String::new(),
            Value::Object(_) => String::new(),
        }
    }

    pub fn get(&self, key: &str) -> Option<&Value> {
        match self {
            Value::Object(items) => items.iter().find(|(k, _)| k == key).map(|(_, v)| v),
            _ => None,
        }
    }
}

fn fmt_float(f: f64) -> String {
    if f == f.trunc() && f.abs() < 1e15 {
        format!("{f:.1}")
    } else {
        format!("{f}")
    }
}

/// Escape a value for HTML.
pub fn escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#x27;"),
            '`' => out.push_str("&#x60;"),
            '=' => out.push_str("&#x3D;"),
            _ => out.push(c),
        }
    }
    out
}

#[derive(Clone, Debug)]
enum Node {
    Text(String),
    /// `{{ expr }}` or `{{{ expr }}}`
    Expr { raw: bool, expr: String },
    /// `{{#name args}} ... {{/name}}`
    Block {
        name: String,
        args: Vec<Arg>,
        body: Vec<Node>,
        inverse: Vec<Node>,
    },
    Partial(String),
}

#[derive(Clone, Debug)]
enum Arg {
    Value(Value),
    Path(String),
}

pub struct Template {
    nodes: Vec<Node>,
}

/// Parse a template.
pub fn parse(source: &str) -> Template {
    let mut p = TemplateParser {
        chars: source.chars().collect(),
        pos: 0,
    };
    let nodes = p.parse_nodes(None);
    Template { nodes }
}

impl Template {
    /// Render the template with the given data and helpers.
    pub fn render(&self, data: &Value, helpers: &dyn Helper) -> String {
        let mut out = String::new();
        render_nodes(&self.nodes, &Context { stack: vec![data] }, helpers, &mut out, false);
        out
    }
}

struct Context<'a> {
    stack: Vec<&'a Value>,
}

impl<'a> Context<'a> {
    fn lookup(&self, path: &str) -> Option<Value> {
        // Special variables.
        if let Some(rest) = path.strip_prefix('@') {
            let frame = self.stack.last()?;
            return frame.get(&format!("@{rest}")).cloned();
        }
        let mut parts: Vec<&str> = path.split('.').collect();
        // `../` walks up the context stack.
        let mut up = 0;
        while let Some(first) = parts.first() {
            if *first == ".." {
                up += 1;
                parts.remove(0);
            } else {
                break;
            }
        }
        if parts.is_empty() {
            return None;
        }
        if parts.len() == 1 && parts[0] == "this" {
            return self.stack.get(self.stack.len().saturating_sub(1 + up)).cloned();
        }
        let base = self.stack.get(self.stack.len().saturating_sub(1 + up))?;
        let mut cur = *base;
        for part in parts {
            match cur.get(part) {
                Some(v) => cur = v,
                None => {
                    if part == "this" {
                        continue;
                    }
                    return None;
                }
            }
        }
        Some(cur.clone())
    }
}

/// A helper implementation.
pub trait Helper {
    fn call(
        &self,
        name: &str,
        params: &[Value],
        hash: &HashMap<String, Value>,
        body: Option<&[Node]>,
        inverse: Option<&[Node]>,
