#[derive(Clone, Debug)]
enum Node {
    Text(String),
    Expr { raw: bool, expr: String },
    Block {
        name: String,
        args: Vec<Arg>,
        body: Vec<Node>,
        inverse: Vec<Node>,
    },
    Partial(String),
}

#[derive(Clone, Debug)]
enum Arg {
    Value(Value),
    Path(String),
}

pub struct Template {
    nodes: Vec<Node>,
}

pub fn parse(source: &str) -> Template {
    let mut p = TemplateParser {
        chars: source.chars().collect(),
        pos: 0,
    };
    Template {
        nodes: p.parse_nodes(None).0,
    }
}

/// The rendering state: the output buffer plus the context stack.
pub struct Render<'a> {
    pub out: String,
    stack: Vec<&'a Value>,
    pub partials: &'a dyn PartialProvider,
    pub helpers: &'a dyn Helpers,
}

pub trait PartialProvider {
    fn partial(&self, name: &str) -> Option<&'a [Node]>;
}

pub trait Helpers {
    /// A block helper: renders its own body with the given renderer.
    fn call(
        &self,
        r: &mut Render,
        name: &str,
        params: &[Value],
        body: Option<&Vec<Node>>,
        inverse: Option<&Vec<Node>>,
    );
}

impl<'a> Render<'a> {
    pub fn new(data: &'a Value, partials: &'a dyn PartialProvider, helpers: &'a dyn Helpers) -> Self {
        Render {
            out: String::new(),
            stack: vec![data],
            partials,
            helpers,
        }
    }

    fn lookup(&self, path: &str) -> Option<Value> {
        if let Some(rest) = path.strip_prefix('@') {
            let frame = self.stack.last()?;
            return frame.get(&format!("@{rest}")).cloned();
        }
        let mut parts: Vec<&str> = path.split('.').collect();
        let mut up = 0usize;
        while let Some(first) = parts.first() {
            if *first == ".." {
                up += 1;
                parts.remove(0);
            } else {
                break;
            }
        }
        if parts.is_empty() {
            return None;
        }
        if parts.len() == 1 && parts[0] == "this" {
            return self.stack.get(self.stack.len().saturating_sub(1 + up)).cloned();
        }
        let base = *self.stack.get(self.stack.len().saturating_sub(1 + up))?;
        let mut cur = base.clone();
        for part in parts {
            if part == "this" {
                continue;
            }
            match cur.get(part) {
                Some(v) => cur = v.clone(),
                None => return None,
            }
        }
        Some(cur)
    }

    fn arg(&self, a: &Arg) -> Value {
        match a {
            Arg::Value(v) => v.clone(),
            Arg::Path(p) => self.lookup(p).unwrap_or(Value::Null),
        }
    }

    pub fn render_nodes(&mut self, nodes: &[Node]) {
        let nodes: Vec<Node> = nodes.to_vec();
        for node in &nodes {
            match node {
                Node::Text(t) => self.out.push_str(t),
                Node::Expr { raw, expr } => {
                    let value = self.lookup(expr).unwrap_or(Value::Null);
                    let s = value.render();
                    if *raw {
                        self.out.push_str(&s);
                    } else {
                        self.out.push_str(&crate::handlebars::escape(&s));
                    }
                }
                Node::Partial(name) => {
                    if let Some(nodes) = self.partials.partial(name) {
                        self.render_nodes(nodes);
                    }
                }
                Node::Block {
                    name,
                    args,
                    body,
                    inverse,
                } => match name.as_str() {
                    "if" | "unless" => {
                        let cond = args.first().map(|a| self.arg(a)).unwrap_or(Value::Null);
                        let truthy = cond.truthy();
                        let use_body = if name == "if" { truthy } else { !truthy };
                        if use_body {
                            self.render_nodes(body);
                        } else {
                            self.render_nodes(inverse);
                        }
                    }
                    "each" => {
                        let list = args.first().map(|a| self.arg(a)).unwrap_or(Value::Null);
                        match list {
                            Value::Array(items) => {
                                let n = items.len();
                                for (i, item) in items.iter().enumerate() {
                                    self.push_frame(item, i, n);
                                    self.render_nodes(body);
                                    self.stack.pop();
                                }
                            }
                            Value::Object(items) => {
                                let n = items.len();
                                for (i, (k, v)) in items.iter().enumerate() {
                                    let mut frame = Value::Object(vec![
                                        ("this".to_string(), v.clone()),
                                        ("key".to_string(), Value::Str(k.clone())),
                                        ("@index".to_string(), Value::Int(i as i64)),
                                        ("@first".to_string(), Value::Bool(i == 0)),
                                        ("@last".to_string(), Value::Bool(i + 1 == n)),
                                    ]);
                                    if let Value::Object(fields) = v {
                                        for (fk, fv) in fields {
                                            frame.0.push((fk.clone(), fv.clone()));
                                        }
                                    }
                                    self.stack.push(&frame);
                                    self.render_nodes(body);
                                    self.stack.pop();
                                }
                            }
                            _ => self.render_nodes(inverse),
                        }
                    }
                    _ => {
                        let params: Vec<Value> =
                            args.iter().map(|a| self.arg(a)).collect();
                        self.helpers.call(self, name, &params, Some(body), Some(inverse));
                    }
                },
            }
        }
    }

    fn push_frame(&mut self, item: &Value, i: usize, n: usize) {
        let mut frame = Value::Object(vec![("this".to_string(), item.clone())]);
        if let Value::Object(fields) = item {
            for (k, v) in fields {
                frame.0.push((k.clone(), v.clone()));
            }
        }
        frame.0.push(("@index".to_string(), Value::Int(i as i64)));
        frame.0.push(("@first".to_string(), Value::Bool(i == 0)));
        frame.0.push(("@last".to_string(), Value::Bool(i + 1 == n)));
        self.stack.push(&frame);
    }
}

struct TemplateParser {
    chars: Vec<char>,
    pos: usize,
}

impl TemplateParser {
    fn starts_with(&self, s: &str) -> bool {
        for (i, c) in s.chars().enumerate() {
            if self.chars.get(self.pos + i) != Some(&c) {
                return false;
            }
        }
        true
    }

    /// Parse nodes until the closer is found. Returns the nodes and whether the
    /// parse stopped at an `{{else}}`.
    fn parse_nodes(&mut self, closer: Option<&str>) -> (Vec<Node>, bool) {
        let mut nodes: Vec<Node> = Vec::new();
        let mut text = String::new();
        loop {
            if self.pos >= self.chars.len() {
                break;
            }
            if self.starts_with("{{") {
                let Some((name, triple)) = self.read_tag() else {
                    text.push_str("{{");
                    self.pos += 2;
                    continue;
                };
                let is_standalone_tag = name.starts_with('#')
                    || name.starts_with('/')
                    || name.starts_with('>')
                    || name.starts_with('!')
                    || name == "else";
                let before_ws = text.chars().all(|c| c.is_whitespace());
                let after_ws = self.rest_of_line_is_whitespace();
                if is_standalone_tag && before_ws && after_ws {
                    text.clear();
                    self.skip_line_end();
                }
                if !text.is_empty() {
                    nodes.push(Node::Text(std::mem::take(&mut text)));
                }
                if name.is_empty() || name.starts_with('!') {
                    continue;
                }
                if let Some(p) = name.strip_prefix('>') {
                    nodes.push(Node::Partial(p.trim().to_string()));
                    continue;
                }
                if name == "else" {
                    return (nodes, true);
                }
                if let Some(closer_name) = name.strip_prefix('/') {
                    if let Some(c) = closer {
                        if closer_name.trim() == c {
                            return (nodes, false);
                        }
                    }
                    // An unmatched closer: ignore.
                    continue;
                }
                if let Some(block_name) = name.strip_prefix('#') {
                    let (block_name, args) = parse_block_header(block_name);
                    let closer_name = format!("/{}", block_name);
                    let (mut body, hit_else) = self.parse_nodes(Some(&closer_name));
                    let mut inverse = Vec::new();
                    if hit_else {
                        let (inv, _) = self.parse_nodes(Some(&closer_name));
                        inverse = inv;
                    }
                    nodes.push(Node::Block {
                        name: block_name,
                        args,
                        body,
                        inverse,
                    });
                    let _ = &mut body;
                    continue;
                }
                nodes.push(Node::Expr {
                    raw: triple,
                    expr: name,
                });
                continue;
            }
            let c = self.chars[self.pos];
            text.push(c);
            self.pos += 1;
        }
        if !text.is_empty() {
            nodes.push(Node::Text(text));
        }
        (nodes, false)
    }

    fn skip_line_end(&mut self) {
        while self.pos < self.chars.len()
            && (self.chars[self.pos] == ' ' || self.chars[self.pos] == '\t')
        {
            self.pos += 1;
        }
        if self.pos + 1 < self.chars.len()
            && self.chars[self.pos] == '\r'
            && self.chars[self.pos + 1] == '\n'
        {
            self.pos += 2;
        } else if self.pos < self.chars.len() && self.chars[self.pos] == '\n' {
            self.pos += 1;
        }
    }

    fn rest_of_line_is_whitespace(&self) -> bool {
        let mut i = self.pos;
        while i < self.chars.len() && (self.chars[i] == ' ' || self.chars[i] == '\t') {
            i += 1;
        }
        if i >= self.chars.len() {
            return true;
        }
        self.chars[i] == '\n'
    }

    fn read_tag(&mut self) -> Option<(String, bool)> {
        let triple = self.starts_with("{{{");
        let open_len = if triple { 3 } else { 2 };
        let mut i = self.pos + open_len;
        let mut content = String::new();
        while i < self.chars.len() {
            match self.chars[i] {
                '}' => {
                    if triple {
                        if self.chars.get(i + 1) == Some(&'}')
                            && self.chars.get(i + 2) == Some(&'}')
                        {
                            self.pos = i + 3;
                            return Some((content.trim().to_string(), true));
                        }
                    } else {
                        self.pos = i + 2;
                        return Some((content.trim().to_string(), false));
                    }
                    content.push('}');
                    i += 1;
                }
                _ => {
                    content.push(self.chars[i]);
                    i += 1;
                }
            }
        }
        None
    }
}

fn parse_block_header(s: &str) -> (String, Vec<Arg>) {
    let mut tokens = s.split_whitespace();
    let name = tokens.next().unwrap_or("").to_string();
    let mut args = Vec::new();
    for tok in tokens {
        if tok.starts_with('"') && tok.ends_with('"') && tok.len() >= 2 {
            args.push(Arg::Value(Value::Str(tok[1..tok.len() - 1].to_string())));
        } else {
            args.push(Arg::Path(tok.to_string()));
        }
    }
    (name, args)
}
