{"command": "cd /workspace && cat > src/book.rs <<'RSEOF'
//! The in-memory representation of a book.

use crate::summary::SummaryItem;
use std::path::{Path, PathBuf};

#[derive(Debug, Clone)]
pub enum BookItem {
    Chapter(Chapter),
    Separator,
    PartTitle(String),
}

#[derive(Debug, Clone, Default)]
pub struct Chapter {
    /// The chapter name, as it appears in the summary.
    pub name: String,
    /// The raw markdown of the chapter.
    pub content: String,
    /// The path of the rendered file, relative to the build directory.
    pub path: PathBuf,
    /// The path of the source file, relative to the source directory.
    pub source_path: PathBuf,
    /// The names of the parent chapters.
    pub parent_names: Vec<String>,
    /// The section number, one entry per level.
    pub number: Vec<u64>,
    /// The path from the rendered file back to the root of the book.
    pub path_to_root: String,
    /// Whether the chapter is part of a numbered section.
    pub is_numbered: bool,
    /// A title overridden with the `{{#title}}` directive.
    pub title: Option<String>,
}

impl Chapter {
    /// The name of the file to render, e.g. `chapter_1.html`.
    pub fn output_file(&self) -> String {
        let mut file = self.path.to_str().unwrap_or_default().to_string();
        file.push_str(".html");
        file
    }

    /// The depth of the chapter below the root.
    pub fn depth(&self) -> usize {
        self.path.components().count()
    }
}

/// Walk the items of a book, depth first.
pub fn for_each_mut<'a>(items: &'a mut [BookItem], f: &mut dyn FnMut(&'a mut Chapter)) {
    for item in items {
        if let BookItem::Chapter(ch) = item {
            f(ch);
            for_each_mut(&mut ch.content, f);
        }
    }
}

pub fn for_each<'a>(items: &'a [BookItem], f: &mut dyn FnMut(&'a Chapter)) {
    for item in items {
        if let BookItem::Chapter(ch) = item {
            f(ch);
            for_each(&ch.content, f);
        }
    }
}

/// The path from a chapter to the root of the book.
pub fn path_to_root(path: &Path) -> String {
    let depth = path.components().count();
    if depth == 0 {
        return String::new();
    }
    "../".repeat(depth)
}
