/// Process the directives in a chapter.
fn process(
    content: &str,
    src_dir: &Path,
    chapter_path: &Path,
    ctx: &PreCtx,
) -> (String, Option<String>) {
    let mut out = String::new();
    let mut title = None;
    let bytes: Vec<char> = content.chars().collect();
