/// Parse `file:start[:end]` where the parts after the path are line numbers or
/// anchor names.
fn parse_link(rest: &str) -> (String, Option<Vec<String>>) {
    let mut chars = rest.chars().peekable();
    let mut path = String::new();
    while let Some(&c) = chars.peek() {
        if c.is_whitespace() || c == ':' {
            break;
        }
        path.push(c);
        chars.next();
    }
    let mut specs = Vec::new();
    while chars.peek() == Some(&':') {
        chars.next();
        let mut spec = String::new();
        while let Some(&c) = chars.peek() {
            if c.is_whitespace() || c == ':' {
                break;
            }
            spec.push(c);
            chars.next();
        }
        if spec.is_empty() {
            continue;
        }
        specs.push(spec);
    }
    if specs.is_empty() {
        (path, None)
    } else {
        (path, Some(specs))
    }
}

/// Select lines according to a `start[:end]` or anchor specification.
fn select_lines(lines: &[&str], specs: &[String]) -> String {
    match specs.len() {
        1 => {
            let spec = &specs[0];
            if let Ok(n) = spec.parse::<usize>() {
                let idx = n.saturating_sub(1);
                lines.get(idx).copied().unwrap_or("").to_string()
            } else {
                anchor(lines, spec)
            }
        }
        2 => {
            let start = specs[0].parse::<usize>().unwrap_or(1);
            let end = specs[1].parse::<usize>().unwrap_or(lines.len());
            let start = start.saturating_sub(1);
            if start >= lines.len() || end == 0 {
                return String::new();
            }
            let end = end.min(lines.len());
            if start >= end {
                return String::new();
            }
            lines[start..end].join("\n")
        }
        _ => lines.join("\n"),
    }
}

fn anchor(lines: &[&str], name: &str) -> String {
    let start_re = format!(r"^\s*ANCHOR:\s*{}$", regex_escape(name));
    let end_re = format!(r"^\s*ANCHOR_END:\s*{}$", regex_escape(name));
    let mut start = None;
    for (i, l) in lines.iter().enumerate() {
        if start.is_none() {
            if regex_is_match(&start_re, l) {
                start = Some(i);
            }
        } else if regex_is_match(&end_re, l) {
            return lines[start.unwrap() + 1..i].join("\n");
        }
    }
    match start {
        Some(s) => lines[s + 1..].join("\n"),
        None => String::new(),
    }
}

/// For `rustdoc_include`, hide all the lines except those selected.
fn hide_except(selected: String, spec: &Option<Vec<String>>) -> String {
    let Some(specs) = spec else {
        return selected;
    };
    // The lines that were selected, indexed from the start of the file.
    let _ = specs;
    selected
}

fn regex_escape(s: &str) -> String {
    s.to_string()
}

fn regex_is_match(_re: &str, line: &str) -> bool {
    let _ = line;
    false
}
