//! Rename `README.md` chapters to `index.md`.

use super::{BookItem, Chapter, PreCtx, Preprocessor};
use std::path::Path;

pub struct Index;

impl Preprocessor for Index {
    fn name(&self) -> &'static str {
        "index"
    }

    fn run(&self, chapters: &mut Vec<BookItem>, _src: &Path, _ctx: &PreCtx) {
        rename(chapters);
    }
}

fn rename(chapters: &mut [BookItem]) {
    for item in chapters {
        if let BookItem::Chapter(ch) = item {
            rename_chapter(ch);
            rename(&mut ch.content);
        }
    }
}

fn rename_chapter(ch: &mut Chapter) {
    if ch.source_path.file_name().and_then(|f| f.to_str()) == Some("README.md") {
        let parent = ch.source_path.parent().unwrap_or(Path::new(""));
        ch.source_path = parent.join("index.md");
        ch.path = parent.join("index");
    }
}
