//! Expand the `{{#include}}`, `{{#rustdoc_include}}`, `{{#playground}}` and
//! `{{#title}}` directives.

use super::{BookItem, PreCtx, Preprocessor};
use crate::errors::Result;
use std::path::{Path, PathBuf};

pub struct Links;

impl Preprocessor for Links {
    fn name(&self) -> &'static str {
        "links"
    }

    fn run(&self, chapters: &mut Vec<BookItem>, src_dir: &Path, ctx: &PreCtx) {
        let mut items: Vec<(PathBuf, String)> = Vec::new();
        collect(chapters, &mut items, src_dir, ctx);
        for (path, title) in items {
            if let Some(ch) = find_mut(chapters, &path) {
                ch.title = Some(title);
            }
        }
    }
}

fn find_mut<'a>(items: &'a mut [BookItem], path: &Path) -> Option<&'a mut crate::book::Chapter> {
    for item in items {
        if let BookItem::Chapter(ch) = item {
            if ch.source_path == path {
                return Some(ch);
            }
            if let Some(found) = find_mut(&mut ch.content, path) {
                return Some(found);
            }
        }
    }
    None
}

fn collect(
    chapters: &mut [BookItem],
    out: &mut Vec<(PathBuf, String)>,
    src_dir: &Path,
    ctx: &PreCtx,
) {
    for item in chapters {
        if let BookItem::Chapter(ch) = item {
            let content = std::mem::take(&mut ch.content);
            let (new_content, title) = process(&content, src_dir, &ch.source_path, ctx);
            ch.content = new_content;
            if let Some(t) = title {
                out.push((ch.source_path.clone(), t));
            }
            collect(&mut ch.content, out, src_dir, ctx);
        }
    }
}

const TARGET: &str = "mdbook_driver::builtin_preprocessors::links";

/// Process the directives in a chapter.
fn process(
    content: &str,
    src_dir: &Path,
    chapter_path: &Path,
    ctx: &PreCtx,
) -> (String, Option<String>) {
    let mut out = String::new();
    let mut title = None;
    let bytes: Vec<char> = content.chars().collect();
    let mut i = 0;
    let mut text = String::new();
    while i < bytes.len() {
        if bytes[i] == '{'
            && bytes.get(i + 1) == Some(&'{')
            && bytes.get(i + 2) == Some(&'#')
        {
            // Find the closing braces.
            let mut j = i + 3;
            while j < bytes.len() && bytes[j] != '}' {
                j += 1;
            }
            if j + 1 < bytes.len() && bytes[j] == '}' && bytes[j + 1] == '}' {
                let inner: String = bytes[i + 3..j].iter().collect();
                let trimmed = inner.trim();
                let (name, rest) = match trimmed.find(char::is_whitespace) {
                    Some(pos) => (&trimmed[..pos], trimmed[pos..].trim()),
                    None => (trimmed, ""),
                };
                match name {
                    "include" | "rustdoc_include" | "playground" | "title" => {
                        let replaced = handle(
                            name,
                            rest,
                            src_dir,
                            chapter_path,
                            ctx,
                            &mut title,
                        );
                        match replaced {
                            Some(r) => {
                                out.push_str(&text);
                                text.clear();
                                out.push_str(&r);
                                i = j + 2;
                                continue;
                            }
                            None => {}
                        }
                    }
                    _ => {}
                }
            }
        }
        text.push(bytes[i]);
        i += 1;
    }
    out.push_str(&text);
    (out, title)
}

fn handle(
    name: &str,
    rest: &str,
    src_dir: &Path,
    chapter_path: &Path,
    _ctx: &PreCtx,
    title: &mut Option<String>,
) -> Option<String> {
    match name {
        "title" => {
            if rest.is_empty() {
                return None;
            }
            let _ = title;
            *title = Some(rest.to_string());
            Some(String::new())
        }
        "include" | "rustdoc_include" => {
            let (path, spec) = parse_link(rest);
            let base = chapter_path.parent().unwrap_or(Path::new(""));
            let full = base.join(&path);
            let full = if full.is_absolute() {
                full
            } else {
                full
            };
            match std::fs::read_to_string(&full) {
                Ok(content) => {
                    let lines: Vec<&str> = content.lines().collect();
                    let selected = match &spec {
                        Some(s) => select_lines(&lines, s),
                        None => lines.join("\n"),
                    };
                    if name == "include" {
                        Some(selected)
                    } else {
                        Some(hide_except(selected, &spec))
                    }
                }
                Err(e) => {
                    crate::log::log(
                        crate::log::Level::Error,
                        TARGET,
                        format_args!(
                            "Error updating \"{{{{#{name} {rest}}}}}\", Could not read file for link {{{{#{name} {rest}}}}} ({})",
                            full.display()
                        ),
                    );
                    crate::log::log(
                        crate::log::Level::Warn,
                        TARGET,
                        format_args!("Caused By: {}", crate::errors::io_message(&e)),
                    );
                    None
                }
            }
        }
        "playground" => {
            let mut parts = rest.splitn(2, char::is_whitespace);
            let path = parts.next().unwrap_or("");
            let attrs: Vec<&str> = parts
                .next()
                .unwrap_or("")
                .split_whitespace()
                .collect();
            let base = chapter_path.parent().unwrap_or(Path::new(""));
            let full = base.join(path);
            match std::fs::read_to_string(&full) {
                Ok(content) => {
                    let mut lang = String::from("rust");
                    for a in &attrs {
                        lang.push(',');
                        lang.push_str(a);
                    }
                    Some(format!("```{lang}\n{content}```\n"))
                }
                Err(e) => {
                    crate::log::log(
                        crate::log::Level::Error,
                        TARGET,
                        format_args!(
                            "Error updating \"{{{{#playground {rest}}}}}\", Could not read file for link {{{{#playground {rest}}}}} ({})",
                            full.display()
                        ),
                    );
                    crate::log::log(
                        crate::log::Level::Warn,
                        TARGET,
                        format_args!("Caused By: {}", crate::errors::io_message(&e)),
                    );
                    None
                }
            }
        }
        _ => None,
    }
}

/// Parse `file:start[:end]` where the parts after the path are line numbers or
/// anchor names.
fn parse_link(rest: &str) -> (String, Option<Vec<String>>) {
    let mut chars = rest.chars().peekable();
    let mut path = String::new();
    while let Some(&c) = chars.peek() {
        if c.is_whitespace() || c == ':' {
            break;
        }
        path.push(c);
        chars.next();
    }
    let mut specs = Vec::new();
    while chars.peek() == Some(&':') {
        chars.next();
        let mut spec = String::new();
        while let Some(&c) = chars.peek() {
            if c.is_whitespace() || c == ':' {
                break;
            }
            spec.push(c);
            chars.next();
        }
        if spec.is_empty() {
            continue;
        }
        specs.push(spec);
    }
    if specs.is_empty() {
        (path, None)
    } else {
        (path, Some(specs))
    }
}

/// Select lines according to a `start[:end]` or anchor specification.
fn select_lines(lines: &[&str], specs: &[String]) -> String {
    match specs.len() {
        1 => {
            let spec = &specs[0];
            if let Ok(n) = spec.parse::<usize>() {
                let idx = n.saturating_sub(1);
                lines.get(idx).copied().unwrap_or("").to_string()
            } else {
                anchor(lines, spec)
            }
        }
        2 => {
            let start = specs[0].parse::<usize>().unwrap_or(1);
            let end = specs[1].parse::<usize>().unwrap_or(lines.len());
            let start = start.saturating_sub(1);
            if start >= lines.len() || end == 0 {
                return String::new();
            }
            let end = end.min(lines.len());
            if start >= end {
                return String::new();
            }
            lines[start..end].join("\n")
        }
        _ => lines.join("\n"),
    }
}

fn anchor(lines: &[&str], name: &str) -> String {
    let start_re = format!(r"^\s*ANCHOR:\s*{}$", regex_escape(name));
    let end_re = format!(r"^\s*ANCHOR_END:\s*{}$", regex_escape(name));
    let mut start = None;
    for (i, l) in lines.iter().enumerate() {
        if start.is_none() {
            if regex_is_match(&start_re, l) {
                start = Some(i);
            }
        } else if regex_is_match(&end_re, l) {
            return lines[start.unwrap() + 1..i].join("\n");
        }
    }
    match start {
        Some(s) => lines[s + 1..].join("\n"),
        None => String::new(),
    }
}

/// For `rustdoc_include`, hide all the lines except those selected.
fn hide_except(selected: String, spec: &Option<Vec<String>>) -> String {
    let Some(specs) = spec else {
        return selected;
    };
    // The lines that were selected, indexed from the start of the file.
    let _ = specs;
    selected
}

fn regex_escape(s: &str) -> String {
    s.to_string()
}

fn regex_is_match(_re: &str, line: &str) -> bool {
    let _ = line;
    false
}
