//! Expand the `{{#include}}`, `{{#rustdoc_include}}`, `{{#playground}}` and
//! `{{#title}}` directives.

use super::{BookItem, PreCtx, Preprocessor};
use regex::Regex;
use std::path::{Path, PathBuf};
use std::sync::OnceLock;

pub struct Links;

fn re() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| {
        Regex::new(r"\{\{\s*#(include|playground|rustdoc_include|title)\s+([^{}]+?)\}\}").unwrap()
    })
}

fn anchor_re(name: &str, end: bool) -> Regex {
    let prefix = if end { "ANCHOR_END" } else { "ANCHOR" };
    Regex::new(&format!(r"^\s*{prefix}:\s*{}\s*$", regex::escape(name))).unwrap()
}

impl Preprocessor for Links {
    fn name(&self) -> &'static str {
        "links"
    }

    fn run(&self, chapters: &mut Vec<BookItem>, _src: &Path, _ctx: &PreCtx) {
        let mut titles: Vec<(PathBuf, String)> = Vec::new();
        process_items(chapters, &mut titles);
        // The last `{{#title}}` wins.
        let mut by_path: std::collections::HashMap<PathBuf, String> =
            std::collections::HashMap::new();
        for (path, title) in titles {
            by_path.insert(path, title);
        }
        apply_titles(chapters, &by_path);
    }
}

fn apply_titles(items: &mut [BookItem], titles: &std::collections::HashMap<PathBuf, String>) {
    for item in items {
        if let BookItem::Chapter(ch) = item {
            if let Some(t) = titles.get(&ch.source_path) {
                ch.title = Some(t.clone());
            }
            apply_titles(&mut ch.content, titles);
        }
    }
}

fn process_items(items: &mut [BookItem], titles: &mut Vec<(PathBuf, String)>) {
    for item in items {
        if let BookItem::Chapter(ch) = item {
            let content = std::mem::take(&mut ch.content);
            let (new_content, title) = process(&content, &ch.source_path);
            ch.content = new_content;
            if let Some(t) = title {
                titles.push((ch.source_path.clone(), t));
            }
            process_items(&mut ch.content, titles);
        }
    }
}

fn process(content: &str, chapter_path: &Path) -> (String, Option<String>) {
    let mut out = String::new();
    let mut title = None;
    let mut last = 0;
    for caps in re().captures_iter(content) {
        let whole = caps.get(0).unwrap();
        out.push_str(&content[last..whole.start()]);
        last = whole.end();
        let name = caps.get(1).unwrap().as_str();
        let arg = caps.get(2).unwrap().as_str();
        match name {
            "title" => {
                title = Some(arg.to_string());
                // The directive is removed.
            }
            _ => match expand(name, arg, chapter_path) {
                Some(text) => out.push_str(&text),
                None => out.push_str(whole.as_str()),
            },
        }
    }
    out.push_str(&content[last..]);
    (out, title)
}

const TARGET: &str = "mdbook_driver::builtin_preprocessors::links";

fn report_error(directive: &str, path: &Path, e: &std::io::Error) {
    crate::log::log(
        crate::log::Level::Error,
        TARGET,
        format_args!(
            "Error updating \"{directive}\", Could not read file for link {directive} ({})",
            path.display()
        ),
    );
    crate::log::log(
        crate::log::Level::Warn,
        TARGET,
        format_args!("Caused By: {}", crate::errors::io_message(e)),
    );
}

fn expand(name: &str, arg: &str, chapter_path: &Path) -> Option<String> {
    let directive = format!("{{{{#{name} {arg}}}}}");
    let base = chapter_path.parent().unwrap_or_else(|| Path::new(""));
    match name {
        "include" | "rustdoc_include" => {
            let (path, specs) = parse_link(arg);
            let full = base.join(&path);
            let content = match std::fs::read_to_string(&full) {
                Ok(c) => c,
                Err(e) => {
                    report_error(&directive, &full, &e);
                    return None;
                }
            };
            let lines: Vec<&str> = content.lines().collect();
            let selected = match &specs {
                Some(specs) => mask(&lines, specs),
                None => (0..lines.len()).collect::<Vec<usize>>(),
            };
            let text = match name {
                "include" => selected
                    .iter()
                    .map(|&i| lines[i])
                    .collect::<Vec<_>>()
                    .join("\n"),
                _ => lines
                    .iter()
                    .enumerate()
                    .map(|(i, l)| {
                        if selected.contains(&i) {
                            l.to_string()
                        } else {
                            format!("# {l}")
                        }
                    })
                    .collect::<Vec<_>>()
                    .join("\n"),
            };
            Some(text)
        }
        "playground" => {
            let mut parts = arg.splitn(2, char::is_whitespace);
            let path = parts.next().unwrap_or("").to_string();
            let attrs: Vec<&str> = parts
                .next()
                .unwrap_or("")
                .split_whitespace()
                .collect();
            let full = base.join(&path);
            let content = match std::fs::read_to_string(&full) {
                Ok(c) => c,
                Err(e) => {
                    report_error(&directive, &full, &e);
                    return None;
                }
            };
            let mut lang = String::from("rust");
            for a in &attrs {
                lang.push(',');
                lang.push_str(a);
            }
            Some(format!("```{lang}\n{content}```\n"))
        }
        _ => None,
    }
}

/// Parse `file[:start[:end]]` into a path and the specifications.
fn parse_link(arg: &str) -> (String, Option<Vec<String>>) {
    let mut chars = arg.chars().peekable();
    let mut path = String::new();
    while let Some(&c) = chars.peek() {
        if c.is_whitespace() || c == ':' {
            break;
        }
        path.push(c);
        chars.next();
    }
    let mut specs = Vec::new();
    while chars.peek() == Some(&':') {
        chars.next();
        let mut spec = String::new();
        while let Some(&c) = chars.peek() {
            if c.is_whitespace() || c == ':' {
                break;
            }
            spec.push(c);
            chars.next();
        }
        if !spec.is_empty() {
            specs.push(spec);
        }
    }
    if specs.is_empty() {
        (path, None)
    } else {
        (path, Some(specs))
    }
}

/// The indices of the lines to show.
fn mask(lines: &[&str], specs: &[String]) -> Vec<usize> {
    match specs.len() {
        1 => {
            let spec = &specs[0];
            if let Ok(n) = spec.parse::<usize>() {
                let idx = n.saturating_sub(1);
                if idx < lines.len() {
                    vec![idx]
                } else {
                    Vec::new()
                }
            } else {
                anchor_mask(lines, spec)
            }
        }
        2 => {
            let start = specs[0].parse::<usize>().unwrap_or(1).saturating_sub(1);
            let end = specs[1].parse::<usize>().unwrap_or(lines.len());
            let mut out = Vec::new();
            if end == 0 {
                return out;
            }
            let end = end.min(lines.len());
            let mut i = start;
            while i < end {
                out.push(i);
                i += 1;
            }
            out
        }
        _ => (0..lines.len()).collect(),
    }
}

fn anchor_mask(lines: &[&str], name: &str) -> Vec<usize> {
    let start = anchor_re(name, false);
    let end = anchor_re(name, true);
    let mut from = None;
    let mut out = Vec::new();
    for (i, l) in lines.iter().enumerate() {
        if from.is_none() {
            if start.is_match(l) {
                from = Some(i);
            }
        } else if end.is_match(l) {
            let s = from.unwrap() + 1;
            let mut i = s;
            while i < lines.len() && i < l_index(i, l) {
                out.push(i);
                i += 1;
            }
            return out;
        }
    }
    if let Some(s) = from {
        let mut i = s + 1;
        while i < lines.len() {
            out.push(i);
            i += 1;
        }
    }
    out
}

fn l_index(i: usize, _l: &str) -> usize {
    i
}
