            let selected = match &specs {
                Some(specs) => mask(&lines, specs),
                None => (0..lines.len()).collect::<Vec<usize>>(),
            };
            let text = match name {
                "include" => selected
                    .iter()
                    .map(|&i| lines[i])
                    .collect::<Vec<_>>()
                    .join("\n"),
