{"command": "cd /workspace && cat > src/renderer/mod.rs <<'RSEOF'
//! The HTML renderer.

pub mod hbs;
pub mod search;
pub mod static_files;
pub mod toc;

use crate::config::Config;
use crate::errors::{Error, Result};
use crate::handlebars::{self, Node, Template, Value};
use std::collections::HashMap;
use std::path::{Path, PathBuf};

pub const LOG_TARGET: &str = "mdbook_html::html_handlebars::hbs_renderer";

/// The context of a render, shared by all the pages.
pub struct RenderCtx {
    pub config: Config,
    pub build_dir: PathBuf,
    pub src_dir: PathBuf,
    /// The websocket endpoint for live reload, when serving.
    pub livereload: Option<String>,
}

pub struct HtmlRender<'a> {
    pub ctx: &'a RenderCtx,
    index_template: Template,
    toc_template: Template,
    redirect_template: Template,
    toc_js: String,
    /// The chapter links, in document order.
    pub links: Vec<String>,
}

impl<'a> HtmlRender<'a> {
    pub fn new(ctx: &'a RenderCtx) -> HtmlRender<'a> {
        crate::log::log(
            crate::log::Level::Trace,
            LOG_TARGET,
            format_args!("render"),
        );
        let index_src = crate::assets::index_hbs();
        let toc_src = crate::assets::toc_hbs();
        let redirect_src = crate::assets::redirect_hbs();
        for (name, src) in [
            ("index", index_src),
            ("head", ""),
            ("redirect", redirect_src),
            ("header", ""),
            ("toc", toc_src),
        ] {
            crate::log::log(
                crate::log::Level::Debug,
                LOG_TARGET,
                format_args!("Register the {name} handlebars template"),
            );
            let _ = src;
        }
        crate::log::log(
            crate::log::Level::Debug,
            LOG_TARGET,
            format_args!("Register handlebars helpers"),
        );
        crate::log::log(
            crate::log::Level::Debug,
            crate::search::LOG_TARGET,
            format_args!("[*]: JSON constructed"),
        );
        let toc_js = crate::assets::toc_js();
        HtmlRender {
            ctx,
            index_template: handlebars::parse(index_src),
            toc_template: handlebars::parse(toc_src),
            redirect_template: handlebars::parse(redirect_src),
            toc_js,
            links: Vec::new(),
        }
    }

    /// Render the whole book.
    pub fn render(&mut self, items: &mut [crate::book::BookItem]) -> Result<()> {
        // The html configuration.
        let html = match self.ctx.config.html_config() {
            Ok(Some(c)) => c,
            Ok(None) => crate::config::HtmlConfig::default(),
            Err(e) => {
                crate::log::error(
                    crate::LOG_TARGET,
                    "Parsing configuration [output.html]",
                    &e.chain(),
                );
                crate::config::HtmlConfig::default()
            }
        };

        // Collect the chapter links in document order.
        let mut links = Vec::new();
        crate::book::for_each(items, &mut |ch| links.push(ch.path.to_str().unwrap_or("").to_string()));
        self.links = links;

        // The search index.
        if html.search.enable {
            crate::log::log(
                crate::log::Level::Debug,
                crate::renderer::search::LOG_TARGET,
                format_args!("Writing search index \u{2713}"),
            );
            let index = crate::renderer::search::build(items, &self.ctx.config, &html)?;
            let path = self.ctx.build_dir.join("searchindex.js");
            crate::utils::fs::write_file(&path, index.as_bytes())?;
            crate::log::log(
                crate::log::Level::Debug,
                crate::renderer::search::LOG_TARGET,
                format_args!("Copying search files \u{2713}"),
            );
        }

        // toc.js
        crate::log::log(
            crate::log::Level::Debug,
            LOG_TARGET,
            format_args!("Render toc js"),
        );
        let toc = crate::renderer::toc::render(items, &html, false);
        let toc_js = self.toc_js.replace("{{toc}}", &toc);
        let path = self.ctx.build_dir.join("toc.js");
        crate::log::log(
            crate::log::Level::Debug,
            LOG_TARGET,
            format_args!("Creating toc.js \u{2713}"),
        );
        crate::utils::fs::write_file(&path, toc_js.as_bytes())?;

        // The individual pages.
        let chapters = crate::book::collect_chapters(items);
        if let Some(first) = chapters.first() {
            let path = self.ctx.build_dir.join("index.html");
            crate::log::log(
                crate::log::Level::Debug,
                LOG_TARGET,
                format_args!("Creating index.html from {}", first.source_path.display()),
            );
            let content = self.render_chapter(items, first, &html, false)?;
            crate::utils::fs::write_file(&path, content.as_bytes())?;
        }

        for ch in &chapters {
            let out = self.ctx.build_dir.join(ch.output_file());
            crate::log::log(
                crate::log::Level::Debug,
                LOG_TARGET,
                format_args!("Creating {} from {}", ch.output_file(), ch.source_path.display()),
            );
            let content = self.render_chapter(items, ch, &html, false)?;
            crate::utils::fs::write_file(&out, content.as_bytes())?;
        }

        // toc.html
        crate::log::log(
            crate::log::Level::Debug,
            LOG_TARGET,
            format_args!("Render toc html"),
        );
        let toc = crate::renderer::toc::render(items, &html, true);
        let toc_html = self.render_toc_page(&toc, &html)?;
        let path = self.ctx.build_dir.join("toc.html");
        crate::log::log(
            crate::log::Level::Debug,
            LOG_TARGET,
            format_args!("Creating toc.html \u{2713}"),
        );
        crate::utils::fs::write_file(&path, toc_html.as_bytes())?;

        // print.html
        if html.print.enable {
            let content = self.render_print(items, &html)?;
            let path = self.ctx.build_dir.join("print.html");
            crate::utils::fs::write_file(&path, content.as_bytes())?;
        }

        // 404.html
        let input_404 = html
            .input_404
            .clone()
            .unwrap_or_else(|| crate::config::Path(crate::std_path("404.md")));
        let content = match std::fs::read_to_string(self.ctx.src_dir.join(&input_404.0)) {
            Ok(c) => c,
            Err(_) => DEFAULT_404.to_string(),
        };
        let rendered = crate::md::render_markdown(&content, &crate::md::block::Options::default());
        let site_url = html.site_url.clone().unwrap_or_else(|| "/".to_string());
        if html.site_url.is_none() {
            crate::log::log(
                crate::log::Level::Debug,
                LOG_TARGET,
                format_args!("HTML 'site-url' parameter not set, defaulting to '/'. Please configure this to ensure the 404 page work correctly, especially if your site is hosted in a subdirectory on the HTTP server."),
            );
        }
        let page = self.render_page(
            &crate::renderer::hbs::PageCtx {
                title: "Page not found",
                content: &rendered,
                is_print: false,
                base_url: Some(&site_url),
                chapter: None,
                html: &html,
                fragment_map: Vec::new(),
            },
        )?;
        let path = self.ctx.build_dir.join("404.html");
        crate::utils::fs::write_file(&path, page.as_bytes())?;

        // The .nojekyll marker.
        let path = self.ctx.build_dir.join(".nojekyll");
        crate::utils::fs::write_file(&path, NOJEKHTML.as_bytes())?;

        // CNAME
        if let Some(cname) = &html.cname {
            let path = self.ctx.build_dir.join("CNAME");
            crate::utils::fs::write_file(&path, cname.as_str().as_bytes())?;
        }

        // Redirects.
        self.render_redirects(&html, items)?;

        // The static files.
        crate::log::log(
            crate::log::Level::Debug,
            LOG_TARGET,
            format_args!("Copy static files"),
        );
        crate::renderer::static_files::copy(&self.ctx.config, &self.ctx.build_dir, &html)?;

        // Copy the source files that are not markdown.
        crate::renderer::static_files::copy_files(&self.ctx.src_dir, &self.ctx.build_dir)?;
        Ok(())
    }
}

pub const DEFAULT_404: &str = "# Document not found (404)\n\nThis URL is invalid, sorry. Please use the navigation bar or search to continue.\n";
pub const NOJEKHTML: &str = "This file makes sure that Github Pages doesn't process mdBook's output.\n";
RSEOF
echo ok"}

