                format_args!("Copying search files \u{2713}"),
            );
        }

        // toc.js
        crate::log::log(
            crate::log::Level::Debug,
            LOG_TARGET,
            format_args!("Render toc js"),
        );
        let toc = crate::renderer::toc::render(items, &html, false);
        let toc_js = self.toc_js.replace("{{toc}}", &toc);
        let path = self.ctx.build_dir.join("toc.js");
        crate::log::log(
            crate::log::Level::Debug,
            LOG_TARGET,
            format_args!("Creating toc.js \u{2713}"),
        );
        crate::utils::fs::write_file(&path, toc_js.as_bytes())?;

        // The individual pages.
        let chapters = crate::book::collect_chapters(items);
        if let Some(first) = chapters.first() {
            let path = self.ctx.build_dir.join("index.html");
            crate::log::log(
                crate::log::Level::Debug,
                LOG_TARGET,
                format_args!("Creating index.html from {}", first.source_path.display()),
            );
            let content = self.render_chapter(items, first, &html, false)?;
            crate::utils::fs::write_file(&path, content.as_bytes())?;
        }

        for ch in &chapters {
            let out = self.ctx.build_dir.join(ch.output_file());
            crate::log::log(
                crate::log::Level::Debug,
                LOG_TARGET,
                format_args!("Creating {} from {}", ch.output_file(), ch.source_path.display()),
            );
            let content = self.render_chapter(items, ch, &html, false)?;
            crate::utils::fs::write_file(&out, content.as_bytes())?;
        }

        // toc.html
        crate::log::log(
            crate::log::Level::Debug,
            LOG_TARGET,
            format_args!("Render toc html"),
        );
        let toc = crate::renderer::toc::render(items, &html, true);
        let toc_html = self.render_toc_page(&toc, &html)?;
        let path = self.ctx.build_dir.join("toc.html");
        crate::log::log(
            crate::log::Level::Debug,
            LOG_TARGET,
            format_args!("Creating toc.html \u{2713}"),
        );
        crate::utils::fs::write_file(&path, toc_html.as_bytes())?;

        // print.html
        if html.print.enable {
            let content = self.render_print(items, &html)?;
            let path = self.ctx.build_dir.join("print.html");
            crate::utils::fs::write_file(&path, content.as_bytes())?;
        }

        // 404.html
        let input_404 = html
            .input_404
            .clone()
            .unwrap_or_else(|| crate::config::Path(crate::std_path("404.md")));
        let content = match std::fs::read_to_string(self.ctx.src_dir.join(&input_404.0)) {
            Ok(c) => c,
            Err(_) => DEFAULT_404.to_string(),
        };
        let rendered = crate::md::render_markdown(&content, &crate::md::block::Options::default());
        let site_url = html.site_url.clone().unwrap_or_else(|| "/".to_string());
        if html.site_url.is_none() {
            crate::log::log(
                crate::log::Level::Debug,
                LOG_TARGET,
                format_args!("HTML 'site-url' parameter not set, defaulting to '/'. Please configure this to ensure the 404 page work correctly, especially if your site is hosted in a subdirectory on the HTTP server."),
            );
        }
        let page = self.render_page(
            &crate::renderer::hbs::PageCtx {
                title: "Page not found",
                content: &rendered,
                is_print: false,
                base_url: Some(&site_url),
                chapter: None,
                html: &html,
                fragment_map: Vec::new(),
            },
        )?;
        let path = self.ctx.build_dir.join("404.html");
        crate::utils::fs::write_file(&path, page.as_bytes())?;

        // The .nojekyll marker.
        let path = self.ctx.build_dir.join(".nojekyll");
        crate::utils::fs::write_file(&path, NOJEKHTML.as_bytes())?;

        // CNAME
        if let Some(cname) = &html.cname {
            let path = self.ctx.build_dir.join("CNAME");
            crate::utils::fs::write_file(&path, cname.as_str().as_bytes())?;
        }

        // Redirects.
        self.render_redirects(&html, items)?;

        // The static files.
        crate::log::log(
            crate::log::Level::Debug,
            LOG_TARGET,
            format_args!("Copy static files"),
        );
        crate::renderer::static_files::copy(&self.ctx.config, &self.ctx.build_dir, &html)?;

        // Copy the source files that are not markdown.
        crate::renderer::static_files::copy_files(&self.ctx.src_dir, &self.ctx.build_dir)?;
        Ok(())
    }
}

pub const DEFAULT_404: &str = "# Document not found (404)\n\nThis URL is invalid, sorry. Please use the navigation bar or search to continue.\n";
pub const NOJEKHTML: &str = "This file makes sure that Github Pages doesn't process mdBook's output.\n";
RSEOF
echo ok"}

