//! File system helpers.

pub const LOG_TARGET: &str = "mdbook_core::utils";

pub mod fs {
    pub const LOG_TARGET: &str = "mdbook_core::utils::fs";

    use crate::errors::{Error, Result};
    use std::path::Path;

    /// Create a file, creating the parent directories as needed.
    pub fn write_file(path: &Path, contents: &[u8]) -> Result<()> {
        crate::log::log(
            crate::log::Level::Debug,
            LOG_TARGET,
            format_args!("Creating {}", path.display()),
        );
        if let Some(parent) = path.parent() {
            if !parent.as_os_str().is_empty() {
                crate::log::log(
                    crate::log::Level::Trace,
                    LOG_TARGET,
                    format_args!("Parent directory is: {:?}", parent),
                );
                if let Err(e) = std::fs::create_dir_all(parent) {
                    return Err(Error::new(crate::errors::io_message(&e)));
                }
            }
        }
        if let Err(e) = std::fs::write(path, contents) {
            return Err(Error::new(crate::errors::io_message(&e)));
        }
        Ok(())
    }

    /// Copy a file, creating the parent directories as needed.
    pub fn copy_file(from: &Path, to: &Path) -> Result<()> {
        let contents = std::fs::read(from)
            .map_err(|e| Error::new(crate::errors::io_message(&e)))?;
        write_file(to, &contents)
    }

    /// Recursively copy a directory.
    pub fn copy_dir(from: &Path, to: &Path) -> Result<()> {
        std::fs::create_dir_all(to).map_err(|e| Error::new(crate::errors::io_message(&e)))?;
        for entry in crate::utils::fs::read_dir_sorted(from)? {
            let name = entry.file_name();
            let src = from.join(&name);
            let dst = to.join(&name);
            if entry.file_type().map(|t| t.is_dir()).unwrap_or(false) {
                copy_dir(&src, &dst)?;
            } else {
                copy_file(&src, &dst)?;
            }
        }
        Ok(())
    }

    pub fn read_dir_sorted(path: &Path) -> Result<Vec<std::fs::DirEntry>> {
        let mut entries: Vec<std::fs::DirEntry> = std::fs::read_dir(path)
            .map_err(|e| Error::new(crate::errors::io_message(&e)))?
            .filter_map(|e| e.ok())
            .collect();
        entries.sort_by_key(|e| e.file_name());
        Ok(entries)
    }

    /// Recursively delete a directory, returning the number of files and the
    /// total size.
    pub fn remove_dir_files(path: &Path) -> Result<(u64, u64)> {
        let mut files = 0;
        let mut size = 0;
        if !path.exists() {
            return Ok((0, 0));
        }
        if path.is_dir() {
            for entry in read_dir_sorted(path)? {
                let p = path.join(entry.file_name());
                if entry.file_type().map(|t| t.is_dir()).unwrap_or(false) {
                    let (f, s) = remove_dir_files(&p)?;
                    files += f;
                    size += s;
                    let _ = std::fs::remove_dir(&p);
                } else {
                    files += 1;
                    size += entry.metadata().map(|m| m.len()).unwrap_or(0);
                    let _ = std::fs::remove_file(&p);
                }
            }
            let _ = std::fs::remove_dir(path);
        } else {
            files += 1;
            size += std::fs::metadata(path).map(|m| m.len()).unwrap_or(0);
            let _ = std::fs::remove_file(path);
        }
        Ok((files, size))
    }

    /// Format a size in bytes the way the tool does.
    pub fn format_size(size: u64) -> String {
        const UNITS: [&str; 5] = ["B", "KiB", "MiB", "GiB", "TiB"];
        let mut size = size as f64;
        let mut unit = 0;
        while size >= 1024.0 && unit < UNITS.len() - 1 {
            size /= 1024.0;
            unit += 1;
        }
        if unit == 0 {
            format!("{}{}", size as u64, UNITS[unit])
        } else {
            format!("{:.2}{}", size, UNITS[unit])
        }
    }
}
