/// Render the `<ol class="chapter">` element of the table of contents.
pub fn render(items: &[BookItem], html: &HtmlConfig, is_print: bool) -> String {
    let mut out = String::new();
    out.push_str("<ol class=\"chapter\">");
    render_items(items, html, is_print, &mut out, false);
    out.push_str("</ol>");
    out
}

fn render_items(
    items: &[BookItem],
    html: &HtmlConfig,
    is_print: bool,
    out: &mut String,
    _nested: bool,
) {
    for item in items {
        match item {
            BookItem::Chapter(ch) => render_chapter(ch, html, is_print, out),
            BookItem::Separator => {
                out.push_str("<li class=\"chapter-item ");
                if !html.fold.enable {
                    out.push_str("expanded ");
                }
                out.push_str("affix \">");
                out.push_str("<li class=\"spacer\"></li>");
            }
            BookItem::PartTitle(title) => {
                out.push_str("<li class=\"chapter-item ");
                if !html.fold.enable {
                    out.push_str("expanded ");
                }
                out.push_str("affix \">");
                out.push_str(&format!(
                    "<li class=\"part-title\">{}</li>",
                    crate::md::html::escape(title)
                ));
            }
        }
    }
}

fn render_chapter(ch: &Chapter, html: &HtmlConfig, is_print: bool, out: &mut String) {
    let expanded = if !html.fold.enable { "expanded " } else { "" };
    let affix = if ch.is_numbered { "" } else { "affix " };
    out.push_str(&format!("<li class=\"chapter-item {expanded}{affix}\">"));
    let has_children = !ch.children.is_empty();
    let target = if is_print { " target=\"_parent\"" } else { "" };
    let number = if html.no_section_label || !ch.is_numbered {
        String::new()
    } else {
        format!(
            "<strong aria-hidden=\"true\">{}.</strong> ",
            crate::summary::format_number(&ch.number[..ch.number.len() - 1], *ch.number.last().unwrap_or(&0))
        )
    };
    match &ch.path.to_str() {
        Some(p) if !p.is_empty() => {
            out.push_str(&format!(
                "<a href=\"{}\"{target}>{number}{}</a>",
                escape_attribute(&ch.output_file()),
                crate::md::html::escape(&ch.name)
            ));
        }
        _ => {
            out.push_str(&format!(
                "<div>{number}{}</div>",
                crate::md::html::escape(&ch.name)
            ));
        }
    }
    if html.fold.enable && has_children {
        out.push_str("<a class=\"toggle\"><div>\u{2771}</div></a>");
    }
    out.push_str("</li>");
    if has_children {
        out.push_str("<li><ol class=\"section\">");
        render_items(&ch.children, html, is_print, out, true);
        out.push_str("</ol></li>");
    }
}
