    pub fn data(&self, chapter: Option<&crate::book::Chapter>, is_print: bool, _map: Vec<(String, String)>) -> Value {
        let config = &self.ctx.config;
        let html = self.html;
        let book_title = config.book.title.clone().unwrap_or_default();
        let title = match chapter {
            Some(ch) => {
                let ch_title = ch.title.clone().unwrap_or_else(|| ch.name.clone());
                if book_title.is_empty() {
                    ch_title
                } else {
                    format!("{ch_title} - {book_title}")
                }
            }
