            crate::config::TextDirection::RightToLeft => "rtl",
        };
        let favicon_svg = if crate::assets::asset("theme/favicon.svg").is_some() {
            Value::str("favicon.svg")
        } else {
            Value::Null
        };
        let favicon_png = if crate::assets::asset("theme/favicon.png").is_some() {
            Value::str("favicon.png")
        } else {
            Value::Null
        };
        let edit_url = chapter.and_then(|ch| {
