                )
            })
        });
        Value::obj(vec![
            ("language", Value::str(config.book.language.clone().unwrap_or_default())),
            ("default_theme", Value::str(html.default_theme.clone())),
            ("preferred_dark_theme", Value::str(html.preferred_dark_theme.clone())),
            ("text_direction", Value::str(text_direction)),
            ("title", Value::str(title)),
            ("is_print", Value::Bool(is_print)),
            ("base_url", Value::Null),
            ("description", Value::str(config.book.description.clone().unwrap_or_default())),
            ("favicon_svg", favicon_svg),
            ("favicon_png", favicon_png),
            ("copy_fonts", Value::Bool(html.copy_fonts)),
            ("path_to_root", Value::str("")),
            ("search_enabled", Value::Bool(html.search.enable)),
            ("search_js", Value::Bool(html.search.enable && html.search.copy_js)),
            ("book_title", Value::str(book_title)),
            ("print_enable", Value::Bool(html.print.enable)),
            ("mathjax_support", Value::Bool(html.mathjax_support)),
            ("git_repository_url", match &html.git_repository_url {
                Some(u) => Value::str(u.clone()),
                None => Value::Null,
            }),
            ("git_repository_icon", match &html.git_repository_icon {
                Some(i) => Value::str(i.clone()),
                None => match &html.git_repository_url {
                    Some(_) => Value::str("fa-github"),
                    None => Value::Null,
                },
            }),
            ("git_repository_edit_url", match edit_url {
                Some(u) => Value::str(u),
                None => Value::Null,
            }),
            ("playground_line_numbers", Value::Bool(html.playground.line_numbers)),
            ("playground_copyable", Value::Bool(html.playground.copyable)),
            ("playground_js", Value::Bool(html.playground.line_numbers || html.playground.editable)),
            ("live_reload_endpoint", Value::Null),
            ("fragment_map", Value::Null),
            (
                "additional_css",
                Value::Array(
                    html.additional_css
                        .iter()
                        .map(|p| Value::str(p.as_str()))
                        .collect(),
                ),
            ),
            (
                "additional_js",
                Value::Array(
                    html.additional_js
                        .iter()
                        .map(|p| Value::str(p.as_str()))
                        .collect(),
                ),
            }),
            ("previous", Value::Object(Vec::new())),
            ("next", Value::Object(Vec::new())),
        ])
    }
}

impl handlebars::Template {
    pub fn render_with(&self, data: &Value, hbs: &Hbs, toc: Option<&str>) -> String {
        let partials: &dyn handlebars::PartialProvider = hbs;
        let helpers = PageRender {
            hbs,
            data: data.clone(),
            toc: toc.map(|s| s.to_string()),
        };
        let mut r = Render::new(data.clone(), partials, &helpers);
        r.render_nodes(&self.nodes);
        r.out
    }
}

pub fn hashmap_from(_v: &Value) -> HashMap<String, String> {
    HashMap::new()
}
