        let index = read_template(&theme, "index.hbs", crate::assets::index_hbs());
        let head = read_template(&theme, "head.hbs", "");
        let header = read_template(&theme, "header.hbs", "");
        let redirect = read_template(&theme, "redirect.hbs", crate::assets::redirect_hbs());
        Hbs {
            ctx,
            html,
            index: handlebars::parse(&index),
            toc: handlebars::parse(crate::assets::toc_hbs()),
            redirect: handlebars::parse(&redirect),
            head: handlebars::parse(&head),
            header: handlebars::parse(&header),
        }
    }

    pub fn render_toc_page(&self, toc: &str) -> Result<String> {
        let data = self.data(None, false, Vec::new());
        let mut renderer = PageRender {
            hbs: self,
            data,
            toc: Some(toc.to_string()),
        };
        let mut r = Render::new(renderer.data.clone(), &renderer, &renderer);
        renderer_index(&mut r, self);
        Ok(r.out)
    }
}

fn theme_dir(ctx: &RenderCtx, html: &HtmlConfig) -> Option<std::path::PathBuf> {
    match &html.theme {
        Some(t) => {
            let p = crate::config::join(&ctx.config, t.0.clone());
            if p.is_dir() {
                Some(p)
            } else {
                None
            }
        }
        None => None,
    }
}

fn read_template(theme: &Option<std::path::PathBuf>, name: &str, default: &str) -> String {
    if let Some(dir) = theme {
        let p = dir.join(name);
        if let Ok(s) = std::fs::read_to_string(&p) {
            return s;
        }
    }
    default.to_string()
}

impl<'a> handlebars::PartialProvider for PageRender<'a> {
    fn partial(&self, name: &str) -> Option<&[Node]> {
        match name {
            "head" => Some(&self.hbs.head.nodes),
            "header" => Some(&self.hbs.header.nodes),
            _ => None,
        }
    }
}

pub struct PageRender<'a> {
    pub hbs: &'a Hbs<'a>,
    pub data: Value,
    pub toc: Option<String>,
}

impl<'a> handlebars::Helpers for PageRender<'a> {
    fn call(
        &self,
        r: &mut Render,
        name: &str,
        params: &[Value],
        body: Option<&Vec<Node>>,
        inverse: Option<&Vec<Node>>,
    ) {
        match name {
            "resource" => {
                let path = params.first().map(|p| p.render()).unwrap_or_default();
                r.out.push_str(&path);
            }
            "previous" | "next" => {
                let value = self.data.get(name).cloned().unwrap_or(Value::Null);
                match (value.get("link"), body) {
                    (Some(Value::Str(link)), Some(body)) if !link.is_empty() => {
                        // Render the body with `link` in scope.
                        let mut data = self.data.clone();
                        if let Value::Object(items) = &mut data {
                            items.retain(|(k, _)| k != "link");
                            items.push(("link".to_string(), Value::Str(link.clone())));
                        }
                        let mut sub = Render::new(data, self.hbs.partials_provider(), self);
                        sub.render_nodes(body);
                        r.out.push_str(&sub.out);
                    }
                    _ => {
                        if let Some(inv) = inverse {
                            let mut sub =
                                Render::new(self.data.clone(), self.hbs.partials_provider(), self);
                            sub.render_nodes(inv);
                            r.out.push_str(&sub.out);
                        }
                    }
                }
            }
            "toc" => {
                r.out.push_str(self.toc.as_deref().unwrap_or_default());
            }
            _ => {
                if let Some(b) = body {
                    r.render_nodes(b);
                }
            }
        }
    }
}

impl<'a> Hbs<'a> {
    fn partials_provider(&self) -> &'a dyn handlebars::PartialProvider {
        self
    }
}

impl<'a> handlebars::PartialProvider for Hbs<'a> {
    fn partial(&self, name: &str) -> Option<&[Node]> {
        match name {
            "head" => Some(&self.head.nodes),
            "header" => Some(&self.header.nodes),
            _ => None,
        }
    }
}

fn renderer_index(r: &mut Render, hbs: &Hbs) {
    let _ = (r, hbs);
}

impl<'a> handlebars::Helpers for Hbs<'a> {
    fn call(
        &self,
        _r: &mut Render,
        _name: &str,
        _params: &[Value],
        _body: Option<&Vec<Node>>,
        _inverse: Option<&Vec<Node>>,
    ) {
    }
}

