                let link = if name == "previous" {
                    self.previous.clone()
                } else {
                    self.next.clone()
                };
                if let (Some(link), Some(body)) = (link, body) {
                    r.push_frame(Value::obj(vec![("link", Value::str(link))]));
                    r.render_nodes(body);
                    r.pop_frame();
                }
            }
            "toc" => {
                r.out.push_str(&self.toc);
            }
            _ => {
                if let Some(b) = body {
                    r.render_nodes(b);
                }
            }
        }
    }
}

