use crate::config::HtmlConfig;
use crate::errors::Result;
use crate::handlebars::{self, Node, Render, Value};

use super::RenderCtx;

/// Everything needed to render one page.
pub struct PageCtx {
    pub title: String,
    pub content: String,
    pub is_print: bool,
    pub base_url: Option<String>,
    /// The chapter being rendered, if any.
    pub chapter: Option<crate::book::Chapter>,
    pub html: HtmlConfig,
    pub fragment_map: Vec<(String, String)>,
    /// The previous and next chapter links.
    pub previous: Option<String>,
    pub next: Option<String>,
}

pub struct Hbs<'a> {
    pub ctx: &'a RenderCtx,
    pub html: HtmlConfig,
    index: handlebars::Template,
    toc_page: handlebars::Template,
    redirect: handlebars::Template,
    head: Vec<Node>,
    header: Vec<Node>,
}

impl<'a> Hbs<'a> {
    pub fn new(ctx: &'a RenderCtx, html: HtmlConfig) -> Hbs<'a> {
        let theme = theme_dir(ctx, &html);
        let index = read_template(&theme, "index.hbs", crate::assets::index_hbs());
        let head = read_template(&theme, "head.hbs", "");
        let header = read_template(&theme, "header.hbs", "");
        let redirect = read_template(&theme, "redirect.hbs", crate::assets::redirect_hbs());
        Hbs {
            ctx,
            html,
            index: handlebars::parse(&index),
            toc_page: handlebars::parse(crate::assets::toc_hbs()),
            redirect: handlebars::parse(&redirect),
            head: handlebars::parse(&head).nodes,
            header: handlebars::parse(&header).nodes,
        }
    }

    /// The data shared by all pages.
    fn base_data(&self, page: &PageCtx) -> Value {
        let config = &self.ctx.config;
        let html = &self.html;
        let book_title = config.book.title.clone().unwrap_or_default();
        let title = match &page.chapter {
            Some(ch) => {
                let ch_title = ch.title.clone().unwrap_or_else(|| ch.name.clone());
                if book_title.is_empty() {
                    ch_title
                } else {
                    format!("{ch_title} - {book_title}")
                }
            }
            None => {
                if page.is_print {
                    book_title.clone()
                } else {
                    "Page not found".to_string()
                }
            }
        };
        let text_direction = match config.html_text_direction() {
            crate::config::TextDirection::LeftToRight => "ltr",
            crate::config::TextDirection::RightToLeft => "rtl",
        };
        let favicon_svg = if crate::assets::asset("theme/favicon.svg").is_some() {
            Value::str("favicon.svg")
        } else {
            Value::Null
        };
        let favicon_png = if crate::assets::asset("theme/favicon.png").is_some() {
            Value::str("favicon.png")
        } else {
            Value::Null
        };
        let edit_url = page.chapter.as_ref().and_then(|ch| {
            html.edit_url_template
                .as_ref()
                .map(|t| t.replace("{path}", &ch.source_path.to_str().unwrap_or_default()))
        });
        let fragment_map = if page.fragment_map.is_empty() {
            Value::Null
        } else {
            Value::str(crate::renderer::search::json_object(&page.fragment_map))
        };
        Value::obj(vec![
            (
                "language",
                Value::str(config.book.language.clone().unwrap_or_default()),
            ),
            ("default_theme", Value::str(html.default_theme.clone())),
            (
                "preferred_dark_theme",
                Value::str(html.preferred_dark_theme.clone()),
            ),
            ("text_direction", Value::str(text_direction)),
            ("title", Value::str(title)),
            ("is_print", Value::Bool(page.is_print)),
            ("base_url", match &page.base_url {
                Some(u) => Value::str(u.clone()),
                None => Value::Null,
            }),
            (
                "description",
                Value::str(config.book.description.clone().unwrap_or_default()),
            ),
            ("favicon_svg", favicon_svg),
            ("favicon_png", favicon_png),
            ("copy_fonts", Value::Bool(html.copy_fonts)),
            ("path_to_root", Value::str("")),
            ("search_enabled", Value::Bool(html.search.enable)),
            (
                "search_js",
                Value::Bool(html.search.enable && html.search.copy_js),
            ),
            ("book_title", Value::str(book_title)),
            ("print_enable", Value::Bool(html.print.enable)),
            ("mathjax_support", Value::Bool(html.mathjax_support)),
            (
                "git_repository_url",
                match &html.git_repository_url {
                    Some(u) => Value::str(u.clone()),
                    None => Value::Null,
                },
            ),
            (
                "git_repository_icon",
                match &html.git_repository_icon {
                    Some(i) => Value::str(i.clone()),
                    None => match &html.git_repository_url {
                        Some(_) => Value::str("fa-github"),
                        None => Value::Null,
                    },
                },
            ),
            (
                "git_repository_edit_url",
                match edit_url {
                    Some(u) => Value::str(u),
                    None => Value::Null,
                },
            ),
            (
                "playground_line_numbers",
                Value::Bool(html.playground.line_numbers),
            ),
            ("playground_copyable", Value::Bool(html.playground.copyable)),
            (
                "playground_js",
                Value::Bool(html.playground.line_numbers || html.playground.editable),
            ),
            (
                "live_reload_endpoint",
                match &page.live_reload {
                    Some(e) => Value::str(e.clone()),
                    None => Value::Null,
                },
            ),
            ("fragment_map", fragment_map),
            (
                "additional_css",
                Value::Array(
                    html.additional_css
                        .iter()
                        .map(|p| Value::str(p.as_str()))
                        .collect(),
                ),
            ),
            (
                "additional_js",
                Value::Array(
                    html.additional_js
                        .iter()
                        .map(|p| Value::str(p.as_str()))
                        .collect(),
                ),
            }),
            ("previous", Value::Null),
            ("next", Value::Null),
            ("content", Value::str(page.content.clone())),
        ])
    }

    /// Render a page with the given context.
    pub fn render_page(&self, page: &PageCtx) -> Result<String> {
        let data = self.base_data(page);
        let state = PageState {
            hbs: self,
            toc: String::new(),
            previous: page.previous.clone(),
            next: page.next.clone(),
        };
        let partials: &dyn handlebars::PartialProvider = &state;
        let helpers: &dyn handlebars::Helpers = &state;
        let mut r = Render::new(data, partials, helpers);
        r.render_nodes(&self.index.nodes);
        Ok(r.out)
    }

    /// Render the toc page.
    pub fn render_toc_page(&self, toc: &str) -> Result<String> {
        let data = self.base_data(&PageCtx {
            title: String::new(),
            content: String::new(),
            is_print: true,
            base_url: None,
            chapter: None,
            html: self.html.clone(),
            fragment_map: Vec::new(),
            previous: None,
            next: None,
            live_reload: None,
        });
        let state = PageState {
            hbs: self,
            toc: toc.to_string(),
            previous: None,
            next: None,
        };
        let partials: &dyn handlebars::PartialProvider = &state;
        let helpers: &dyn handlebars::Helpers = &state;
        let mut r = Render::new(data, partials, helpers);
        r.render_nodes(&self.toc_page.nodes);
        Ok(r.out)
    }

    /// Render a redirect page.
    pub fn render_redirect(&self, url: &str, fragment_map: &str) -> Result<String> {
        let data = Value::obj(vec![
            ("url", Value::str(url)),
            ("fragment_map", Value::str(fragment_map)),
        ]);
        let state = PageState {
            hbs: self,
            toc: String::new(),
            previous: None,
            next: None,
        };
        let partials: &dyn handlebars::PartialProvider = &state;
        let helpers: &dyn handlebars::Helpers = &state;
        let mut r = Render::new(data, partials, helpers);
        r.render_nodes(&self.redirect.nodes);
        Ok(r.out)
    }
}

struct PageState<'a> {
    hbs: &'a Hbs<'a>,
    toc: String,
    previous: Option<String>,
    next: Option<String>,
}

impl handlebars::PartialProvider for PageState<'_> {
    fn partial(&self, name: &str) -> Option<&[Node]> {
        match name {
            "head" => Some(&self.hbs.head),
            "header" => Some(&self.hbs.header),
            _ => None,
        }
    }
}

impl handlebars::Helpers for PageState<'_> {
    fn call(
        &self,
        r: &mut Render,
        name: &str,
        params: &[Value],
        body: Option<&Vec<Node>>,
        _inverse: Option<&Vec<Node>>,
    ) {
        match name {
            "resource" => {
                let path = params.first().map(|p| p.render()).unwrap_or_default();
                r.out.push_str(&path);
            }
            "previous" | "next" => {
                let link = if name == "previous" {
                    self.previous.clone()
                } else {
                    self.next.clone()
                };
                if let (Some(link), Some(body)) = (link, body) {
                    r.push_frame(Value::obj(vec![("link", Value::str(link))]));
                    r.render_nodes(body);
                    r.pop_frame();
                }
            }
            "toc" => {
                r.out.push_str(&self.toc);
            }
            _ => {
                if let Some(b) = body {
                    r.render_nodes(b);
                }
            }
        }
    }
}

fn theme_dir(ctx: &RenderCtx, html: &HtmlConfig) -> Option<std::path::PathBuf> {
    let theme = html.theme.as_ref()?;
    let p = crate::config::join(&ctx.config, theme.0.clone());
    if p.is_dir() {
        Some(p)
    } else {
        None
    }
}

fn read_template(theme: &Option<std::path::PathBuf>, name: &str, default: &str) -> String {
    if let Some(dir) = theme {
        if let Ok(s) = std::fs::read_to_string(dir.join(name)) {
            return s;
        }
    }
    default.to_string()
}
