//! Loading a book from disk and building it.

use crate::book::{BookItem, Chapter};
use crate::config::{Config, Path as CfgPath};
use crate::errors::{Error, Result};
use crate::summary::{self, Summary, SummaryItem};
use std::path::{Path, PathBuf};

pub const LOG_TARGET: &str = "mdbook_driver";

pub struct MdBook {
    pub config: Config,
    pub summary: Summary,
    pub root: PathBuf,
    pub src_dir: PathBuf,
    pub items: Vec<BookItem>,
}

impl MdBook {
    /// Load a book from its root directory.
    pub fn load(root: &Path) -> Result<MdBook> {
        let config_path = root.join("book.toml");
        let config = if config_path.exists() {
            crate::log::log(
                crate::log::Level::Debug,
                "mdbook_driver::mdbook",
                format_args!("Loading config from {}", config_path.display()),
            );
            let text = std::fs::read_to_string(&config_path)
                .map_err(|e| Error::new(crate::errors::io_message(&e)))?;
            Config::from_str(&text)?
        } else {
            Config::default()
        };
        let mut config = config;
        config.update_from_env();
        crate::log::log(
            crate::log::Level::Trace,
            "mdbook_driver::mdbook",
            format_args!("Config: {:#?}", config),
        );

        let src_dir = root.join(config.book.src.0.clone());
        let summary_path = src_dir.join("SUMMARY.md");
        let summary_text = match std::fs::read_to_string(&summary_path) {
            Ok(t) => t,
            Err(e) => {
                return Err(Error::new(format!(
                    "Couldn't open SUMMARY.md in {:?} directory",
                    src_dir
                ))
                .with(crate::errors::io_message(&e)))
            }
        };
        let summary = summary::parse_summary(&summary_text)?;

        // Create the missing chapters.
        let mut missing: Vec<PathBuf> = Vec::new();
        collect_missing(&summary, &src_dir, &mut missing);
        if config.build.create_missing {
            for path in &missing {
                if !path.exists() {
                    crate::log::log(
                        crate::log::Level::Debug,
                        "mdbook_driver::load",
                        format_args!("Creating missing file {}", path.display()),
                    );
                    let name = path
                        .file_stem()
                        .and_then(|s| s.to_str())
                        .unwrap_or_default();
                    crate::utils::fs::write_file(path, format!("# {name}\n").as_bytes())?;
                }
            }
        }

        let mut items = Vec::new();
        load_items(&summary, &src_dir, &mut Vec::new(), &mut items, true)?;
        Ok(MdBook {
            config,
            summary,
            root: root.to_path_buf(),
            src_dir,
            items,
        })
    }

    /// Build the book into the given destination directory.
    pub fn build(&mut self, dest: Option<&Path>) -> Result<()> {
        crate::log::log(
            crate::log::Level::Info,
            "mdbook_driver::mdbook",
            format_args!("Book building has started"),
        );
        let build_dir = self.build_dir(dest);
        let backends = self.backends();
        for (name, _) in &backends {
            crate::log::log(
                crate::log::Level::Info,
                "mdbook_driver::mdbook",
                format_args!("Running the {name} backend"),
            );
        }
        for (name, dir) in &backends {
            match name.as_str() {
                "markdown" => crate::renderer::markdown::render(self, dir)?,
                "html" => crate::renderer::html::render(self, dir)?,
                other => crate::renderer::external::render(self, other, dir)?,
            }
        }
        Ok(())
    }

    /// The directories each backend writes to.
    fn backends(&self) -> Vec<(String, PathBuf)> {
        let build_dir = self.build_dir(None);
        let mut outputs: Vec<String> = match self.config.rest.get("output") {
            Some(crate::config::Value::Table(t)) => t.keys().cloned().collect(),
            _ => Vec::new(),
        };
        if outputs.is_empty() {
            return vec![("html".to_string(), build_dir)];
        }
        if outputs.len() == 1 {
            return vec![(outputs.remove(0), build_dir)];
        }
        outputs
            .into_iter()
            .map(|name| (name.clone(), build_dir.join(&name)))
            .collect()
    }

    pub fn build_dir(&self, dest: Option<&Path>) -> PathBuf {
        match dest {
            Some(d) => d.to_path_buf(),
            None => self.root.join(self.config.build.build_dir.0.clone()),
        }
    }

    /// The preprocessors to run, in order.
    pub fn preprocessors(&self) -> Vec<Box<dyn crate::preprocess::Preprocessor>> {
        let mut out: Vec<Box<dyn crate::preprocess::Preprocessor>> = Vec::new();
        out.push(Box::new(crate::preprocess::index::Index));
        out.push(Box::new(crate::preprocess::links::Links));
        out
    }
}

/// Collect the paths of missing chapter files, in summary order.
fn collect_missing(summary: &Summary, src_dir: &Path, out: &mut Vec<PathBuf>) {
    for item in summary
        .prefix_chapters
        .iter()
        .chain(summary.numbered_chapters.iter())
        .chain(summary.suffix_chapters.iter())
    {
        if let SummaryItem::Link { path, .. } = item {
            let full = src_dir.join(path);
            if !full.exists() {
                out.push(full);
            }
        }
    }
}

fn load_items(
    summary: &[SummaryItem],
    src_dir: &Path,
    parents: &mut Vec<String>,
    out: &mut Vec<BookItem>,
    numbered: bool,
) -> Result<()> {
    let mut number: u64 = 0;
    for item in summary {
        match item {
            SummaryItem::Link { name, path } => {
                if path.as_os_str().is_empty() {
                    // A draft chapter.
                    out.push(BookItem::Chapter(Chapter {
                        name: name.clone(),
                        path: PathBuf::new(),
                        source_path: PathBuf::new(),
                        parent_names: parents.clone(),
                        is_numbered: numbered,
                        number: vec![number],
                        ..Default::default()
                    }));
                    continue;
                }
                let source_path = src_dir.join(path);
                let content = match std::fs::read_to_string(&source_path) {
                    Ok(c) => c,
                    Err(e) => {
                        return Err(Error::new(format!(
                            "Chapter file not found, {}",
                            path.display()
                        ))
                        .with(crate::errors::io_message(&e)))
                    }
                };
                crate::log::log(
                    crate::log::Level::Debug,
                    "mdbook_driver::load",
                    format_args!("Loading {name} ({})", path.display()),
                );
                number += 1;
                let mut ch_number: Vec<u64> = Vec::new();
                if numbered {
                    ch_number = parents_numbers(parents);
                    ch_number.push(number);
                }
                let out_path: PathBuf = path.with_extension("");
                let ch = Chapter {
                    name: name.clone(),
                    content,
                    path: out_path.clone(),
                    source_path,
                    parent_names: parents.clone(),
                    is_numbered: numbered,
                    number: ch_number,
                    path_to_root: crate::book::path_to_root(&out_path),
                    title: None,
                    children: Vec::new(),
                };
                out.push(BookItem::Chapter(ch));
            }
            SummaryItem::Separator => out.push(BookItem::Separator),
            SummaryItem::PartTitle(t) => out.push(BookItem::PartTitle(t.clone())),
        }
    }
    Ok(())
}

fn parents_numbers(parents: &[String]) -> Vec<u64> {
    parents.iter().filter_map(|p| p.parse().ok()).collect()
}

/// The `[output.html]` configuration, with a fallback to the defaults.
pub fn html_config(config: &Config) -> crate::config::HtmlConfig {
    match config.html_config() {
        Ok(Some(c)) => c,
        Ok(None) => crate::config::HtmlConfig::default(),
        Err(e) => {
            crate::log::error(crate::utils::LOG_TARGET, "Parsing configuration [output.html]", &e.chain());
            crate::config::HtmlConfig::default()
        }
    }
}

/// The `Path` helper for configuration values.
pub fn cfg_path(p: &str) -> CfgPath {
    CfgPath(PathBuf::from(p))
}
RSEOF
echo ok"}

