//! Parsing of `SUMMARY.md`.

use crate::errors::Result;
use crate::md::block::{self, Options as MdOptions};
use crate::md::events::{Event, Tag};
use std::path::PathBuf;

#[derive(Debug, Clone, PartialEq)]
pub enum SummaryItem {
    Link {
        name: String,
        path: PathBuf,
        children: Vec<SummaryItem>,
    },
    Separator,
    PartTitle(String),
}

#[derive(Debug, Clone, Default)]
pub struct Summary {
    pub title: String,
    pub prefix_chapters: Vec<SummaryItem>,
    pub numbered_chapters: Vec<SummaryItem>,
    pub suffix_chapters: Vec<SummaryItem>,
}

pub const LOG_TARGET: &str = "mdbook_summary";

/// Parse a `SUMMARY.md` file.
pub fn parse_summary(text: &str) -> Result<Summary> {
    let opts = MdOptions::default();
    let events = block::parse(text, &opts);
    // The first h1 is the title of the summary.
    let mut i = 0;
    let mut title = String::new();
    let mut h1_found = false;
    while i < events.len() {
        if matches!(events[i], Event::Start(Tag::Heading(1, ..))) {
            crate::log::log(
                crate::log::Level::Trace,
                LOG_TARGET,
                format_args!("Found a h1 in the SUMMARY"),
            );
            let mut j = i + 1;
            while j < events.len() {
                if matches!(events[j], Event::End(Tag::Heading(1, ..))) {
                    break;
                }
                j += 1;
            }
            title = collect_text(&events[i + 1..j]);
            h1_found = true;
            i = j + 1;
            break;
        }
        i += 1;
    }
    if !h1_found {
        i = 0;
    }

    let mut summary = Summary {
        title,
        ..Default::default()
    };

    crate::log::log(
        crate::log::Level::Debug,
        LOG_TARGET,
        format_args!("Parsing prefix items"),
    );
    i = parse_items(&events, i, &mut summary.prefix_chapters);

    crate::log::log(
        crate::log::Level::Debug,
        LOG_TARGET,
        format_args!("Parsing numbered chapters at level 0"),
    );
    i = parse_numbered(&events, i, &mut summary.numbered_chapters);

    crate::log::log(
        crate::log::Level::Debug,
        LOG_TARGET,
        format_args!("Parsing suffix items"),
    );
    let _ = parse_items(&events, i, &mut summary.suffix_chapters);

    Ok(summary)
}

/// Collect the text of a list of events.
fn collect_text(events: &[Event]) -> String {
    let mut out = String::new();
    for ev in events {
        match ev {
            Event::Text(t) => out.push_str(t),
            Event::SoftBreak | Event::HardBreak => out.push(' '),
            _ => {}
        }
    }
    out
}

/// Parse root level items: links, separators and part titles.
fn parse_items(events: &[Event], mut i: usize, out: &mut Vec<SummaryItem>) -> usize {
    let mut paragraph = false;
    let mut pending_link: Option<(String, PathBuf)> = None;
    while i < events.len() {
        match &events[i] {
            Event::Rule => {
                crate::log::log(
                    crate::log::Level::Trace,
                    LOG_TARGET,
                    format_args!("Found separator"),
                );
                out.push(SummaryItem::Separator);
                i += 1;
            }
            Event::Start(Tag::Heading(1, ..)) => {
                let mut j = i + 1;
                while j < events.len() {
                    if matches!(events[j], Event::End(Tag::Heading(1, ..))) {
                        break;
                    }
                    j += 1;
                }
                let title = collect_text(&events[i + 1..j]);
                out.push(SummaryItem::PartTitle(title));
                i = j + 1;
            }
            Event::Start(Tag::List(_)) | Event::End(Tag::List(_)) => {
                crate::log::log(
                    crate::log::Level::Trace,
                    LOG_TARGET,
                    format_args!("Back: {:?}", events[i]),
                );
                break;
            }
            Event::Start(Tag::Paragraph) => {
                paragraph = true;
                pending_link = None;
                i += 1;
            }
            Event::End(Tag::Paragraph) => {
                paragraph = false;
                if let Some((name, path)) = pending_link.take() {
                    out.push(SummaryItem::Link {
                        name,
                        path,
                        children: Vec::new(),
                    });
                }
                i += 1;
            }
            Event::Start(Tag::Link { dest_url, .. }) => {
                let mut j = i + 1;
                while j < events.len() {
                    if matches!(events[j], Event::End(Tag::Link { .. })) {
                        break;
                    }
                    j += 1;
                }
                let name = collect_text(&events[i + 1..j]);
                pending_link = Some((name, PathBuf::from(dest_url)));
                i = j + 1;
            }
            Event::End(Tag::Link { .. }) => {
                i += 1;
            }
            Event::Text(_) => {
                // Any other text in the paragraph means it is not a link.
                pending_link = None;
                i += 1;
            }
            _ => i += 1,
        }
    }
    i
}

/// Parse the numbered chapters, which are nested lists.
fn parse_numbered(events: &[Event], mut i: usize, out: &mut Vec<SummaryItem>) -> usize {
    let mut level = 0;
    while i < events.len() {
        match &events[i] {
            Event::Start(Tag::List(_)) => {
                level += 1;
                i = parse_list(events, i + 1, out);
            }
            Event::End(Tag::List(_)) => {
                i += 1;
                if level > 0 {
                    break;
                }
                break;
            }
            _ => i += 1,
        }
    }
    i
}

fn parse_list(events: &[Event], mut i: usize, out: &mut Vec<SummaryItem>) -> usize {
    while i < events.len() {
        match &events[i] {
            Event::Start(Tag::Item) => {
                i += 1;
                // The link, then an optional nested list.
                let mut name = String::new();
                let mut path = PathBuf::new();
                let mut has_link = false;
                if let Some(Event::Start(Tag::Link { dest_url, .. })) = events.get(i) {
                    let mut j = i + 1;
                    while j < events.len() {
                        if matches!(events[j], Event::End(Tag::Link { .. })) {
                            break;
                        }
                        j += 1;
                    }
                    name = collect_text(&events[i + 1..j]);
                    path = PathBuf::from(dest_url);
                    i = j + 1;
                    has_link = true;
                }
                let mut children: Vec<SummaryItem> = Vec::new();
                if let Some(Event::Start(Tag::List(_))) = events.get(i) {
                    i = parse_list(events, i + 1, &mut children);
                }
                if has_link {
                    crate::log::log(
                        crate::log::Level::Trace,
                        LOG_TARGET,
                        format_args!("Found chapter: ({})", path.display()),
                    );
                    out.push(SummaryItem::Link {
                        name,
                        path,
                        children,
                    });
                }
                if matches!(events.get(i), Some(Event::End(Tag::Item))) {
                    i += 1;
                }
            }
            Event::End(Tag::List(_)) => {
                return i + 1;
            }
            _ => i += 1,
        }
    }
    i
}
