    items: &[SummaryItem],
    src_dir: &Path,
    parents: &mut Vec<String>,
    out: &mut Vec<BookItem>,
    numbered: bool,
) -> Result<()> {
    let mut number: u64 = 0;
    for item in items {
        match item {
            SummaryItem::Link {
                name,
                path,
                children,
            } => {
                let mut ch = Chapter {
                    name: name.clone(),
                    parent_names: parents.clone(),
                    is_numbered: numbered,
                    ..Default::default()
                };
                if numbered {
                    number += 1;
                    let mut nums: Vec<u64> = Vec::new();
                    for p in parents.iter() {
                        if let Ok(n) = p.parse() {
                            nums.push(n);
                        }
                    }
                    nums.push(number);
                    ch.number = nums;
                }
                if !path.as_os_str().is_empty() {
                    let source_path = src_dir.join(path);
                    let content = match std::fs::read_to_string(&source_path) {
                        Ok(c) => c,
                        Err(e) => {
                            return Err(Error::new(format!(
                                "Chapter file not found, {}",
                                path.display()
                            ))
                            .with(crate::errors::io_message(&e)))
                        }
                    };
                    crate::log::log(
                        crate::log::Level::Debug,
                        "mdbook_driver::load",
                        format_args!("Loading {name} ({})", path.display()),
                    );
                    ch.content = content;
                    ch.source_path = source_path;
                    let out_path: PathBuf = path.with_extension("");
                    ch.path = out_path.clone();
                    ch.path_to_root = crate::book::path_to_root(&out_path);
                }
                if !children.is_empty() {
                    parents.push(number.to_string());
                    load_items(children, src_dir, parents, &mut ch.children, numbered)?;
                    parents.pop();
                }
                out.push(BookItem::Chapter(ch));
            }
            SummaryItem::Separator => out.push(BookItem::Separator),
            SummaryItem::PartTitle(t) => out.push(BookItem::PartTitle(t.clone())),
        }
    }
    Ok(())
}
RSEOF
echo ok"}

