{"command": "cd /workspace && cat > src/renderer/html.rs <<'RSEOF'
//! The HTML backend.

use crate::config::HtmlConfig;
use crate::errors::{Error, Result};
use crate::md::block::Options as MdOptions;
use crate::md::html::CodeBlockOpts;
use crate::renderer::hbs::{Hbs, PageCtx};
use crate::renderer::{RenderCtx, LOG_TARGET, DEFAULT_404, NOJEKHTML};
use std::path::Path;

use crate::driver::MdBook;

/// Render the book as HTML into `dest`.
pub fn render(book: &mut MdBook, dest: &Path) -> Result<()> {
    let html = book.html_config();
    let ctx = RenderCtx {
        config: book.config.clone(),
        build_dir: dest.to_path_buf(),
        src_dir: book.src_dir.clone(),
        root: book.root.clone(),
    };
    let mut r = HtmlRender::new(&ctx, &html);
    r.render(&mut book.items, dest)
}

struct HtmlRender<'a> {
    ctx: &'a RenderCtx,
    html: HtmlConfig,
    hbs: Hbs<'a>,
}

impl<'a> HtmlRender<'a> {
    fn new(ctx: &'a RenderCtx, html: &HtmlConfig) -> HtmlRender<'a> {
        crate::log::log(
            crate::log::Level::Trace,
            LOG_TARGET,
            format_args!("render"),
        );
        for name in ["index", "head", "redirect", "header", "toc"] {
            crate::log::log(
                crate::log::Level::Debug,
                LOG_TARGET,
                format_args!("Register the {name} handlebars template"),
            );
        }
        crate::log::log(
            crate::log::Level::Debug,
            LOG_TARGET,
            format_args!("Register handlebars helpers"),
        );
        let html = html.clone();
        let hbs = Hbs::new(ctx, html.clone());
        HtmlRender {
            ctx,
            html,
            hbs,
        }
    }

    fn code_opts(&self) -> CodeBlockOpts {
        let html = &self.html;
        let mut hidelines: Vec<(String, String)> = html
            .code
            .hidelines
            .iter()
            .map(|(k, v)| (k.clone(), v.clone()))
            .collect();
        hidelines.sort();
        CodeBlockOpts {
            hidelines,
            rust_hide_prefix: Some("# ".to_string()),
            playground_runnable: html.playground.runnable,
            playground_editable: html.playground.editable,
            playground_line_numbers: html.playground.line_numbers,
            playground_copyable: html.playground.copyable,
            rust_edition: self.ctx.config.rust.edition.clone(),
        }
    }

    fn md_opts(&self) -> MdOptions {
        MdOptions {
            smart_punctuation: self.html.smart_punctuation || self.html.curly_quotes,
            ..Default::default()
        }
    }

    fn render_content(&self, content: &str) -> String {
        crate::md::render_markdown_with(content, &self.md_opts(), &self.code_opts(), None)
    }

    fn render(&mut self, items: &mut [crate::book::BookItem], dest: &Path) -> Result<()> {
        // The search index.
        let search = crate::renderer::search::Search::new(&self.html);
        if self.html.search.enable {
            let index = search.build(items);
            crate::log::log(
                crate::log::Level::Debug,
                crate::renderer::search::LOG_TARGET,
                format_args!("Writing search index \u{2713}"),
            );
            self.search_index = Some(index);
            crate::log::log(
                crate::log::Level::Debug,
                crate::renderer::search::LOG_TARGET,
                format_args!("Copying search files \u{2713}"),
            );
        }

        // toc.js
        crate::log::log(
            crate::log::Level::Debug,
            LOG_TARGET,
            format_args!("Render toc js"),
        );
        let toc = crate::renderer::toc::render(items, &self.html, false);
        self.toc_html = Some(toc.clone());
        let toc_js = crate::assets::toc_js().replace("{{toc}}", &toc);
        crate::log::log(
            crate::log::Level::Debug,
            LOG_TARGET,
            format_args!("Creating toc.js \u{2713}"),
        );
        self.toc_js = Some(toc_js);

        // The static files.
        crate::log::log(
            crate::log::Level::Debug,
            LOG_TARGET,
            format_args!("Copy static files"),
        );
        crate::renderer::static_files::write_static(
            &self.ctx.config,
            &self.ctx.root,
            dest,
            &self.html,
            self.search_index.as_deref(),
            self.toc_js.as_deref(),
        )?;

        // toc.html
        crate::log::log(
            crate::log::Level::Debug,
            LOG_TARGET,
            format_args!("Render toc html"),
        );
        let toc = crate::renderer::toc::render(items, &self.html, true);
        self.toc_html = Some(toc.clone());
        let page = self.hbs.render_toc_page(&toc)?;
        let path = dest.join("toc.html");
        crate::log::log(
            crate::log::Level::Debug,
            LOG_TARGET,
            format_args!("Creating toc.html \u{2713}"),
        );
        crate::utils::fs::write_file(&path, page.as_bytes())?;

        // .nojekyll
        let path = dest.join(".nojekyll");
        crate::utils::fs::write_file(&path, NOJEKHTML.as_bytes())?;

        // CNAME
        if let Some(cname) = &self.html.cname {
            let path = dest.join("CNAME");
            crate::utils::fs::write_file(&path, cname.as_str().as_bytes())?;
        }

        // The chapters.
        let chapters = crate::book::collect_chapters(items);
        let mut first_index = None;
        for (i, ch) in chapters.iter().enumerate() {
            if ch.path.as_os_str().is_empty() {
                continue;
            }
            let (content, map) = self.render_chapter(items, ch, &chapters)?;
            let out = dest.join(ch.output_file());
            crate::log::log(
                crate::log::Level::Debug,
                LOG_TARGET,
                format_args!("Creating {}", ch.output_file()),
            );
            crate::utils::fs::write_file(&out, content.as_bytes())?;
            if first_index.is_none() {
                first_index = Some(i);
                let out = dest.join("index.html");
                crate::log::log(
                    crate::log::Level::Debug,
                    LOG_TARGET,
                    format_args!("Creating index.html from {}", ch.source_path.display()),
                );
                crate::utils::fs::write_file(&out, content.as_bytes())?;
            }
        }

        // 404.html
        self.render_404(items, dest)?;

        // print.html
        if self.html.print.enable {
            self.render_print(items, dest, &chapters)?;
        }

        // Redirects.
        self.render_redirects(items, dest)?;

        // Copy the source files that are not markdown.
        crate::renderer::static_files::copy_files(&self.ctx.src_dir, dest)?;
        crate::log::log(
            crate::log::Level::Info,
            LOG_TARGET,
            format_args!("HTML book written to {:?}", dest.display().to_string()),
        );
        Ok(())
    }

    /// Render one chapter.
    fn render_chapter(
        &self,
        items: &mut [crate::book::BookItem],
        ch: &crate::book::Chapter,
        chapters: &[crate::book::Chapter],
    ) -> Result<(String, Vec<(String, String)>)> {
        let content = self.render_content(&ch.content);
        // The previous and next chapters.
        let pos = chapters.iter().position(|c| c.source_path == ch.source_path);
        let (previous, next) = match pos {
            Some(i) => {
                let prev = chapters[..i]
                    .iter()
                    .rev()
                    .find(|c| !c.path.as_os_str().is_empty());
                let next = chapters[i + 1..].iter().find(|c| !c.path.as_os_str().is_empty());
                (
                    prev.map(|c| c.output_file()),
                    next.map(|c| c.output_file()),
                )
            }
            None => (None, None),
        };
        // The fragment map from the redirects.
        let mut map = Vec::new();
        let out_path = format!("/{}", ch.output_file());
        for (from, to) in &self.html.redirect {
            if let Some((base, frag)) = from.split_once('#') {
                let base = format!("/{base}");
                if base == out_path {
                    map.push((format!("#{frag}"), to.clone()));
                }
            }
        }
        let page_ctx = PageCtx {
            title: ch.title.clone().unwrap_or_else(|| ch.name.clone()),
            content,
            is_print: false,
            base_url: None,
            chapter: Some(ch.clone()),
            html: self.html.clone(),
            fragment_map: map.clone(),
            previous,
            next,
            live_reload: None,
        };
        let rendered = self.hbs.render_page(&page_ctx)?;
        Ok((rendered, map))
    }

    fn render_404(&mut self, items: &mut [crate::book::BookItem], dest: &Path) -> Result<()> {
        let input_404 = self
            .html
            .input_404
            .clone()
            .unwrap_or_else(|| crate::config::Path(std::path::PathBuf::from("404.md")));
        let content = match std::fs::read_to_string(self.ctx.src_dir.join(&input_404.0)) {
            Ok(c) => c,
            Err(_) => DEFAULT_404.to_string(),
        };
        if self.html.site_url.is_none() {
            crate::log::log(
                crate::log::Level::Debug,
                LOG_TARGET,
                format_args!("HTML 'site-url' parameter not set, defaulting to '/'. Please configure this to ensure the 404 page work correctly, especially if your site is hosted in a subdirectory on the HTTP server."),
            );
        }
        let rendered = self.render_content(&content);
        let page_ctx = PageCtx {
            title: String::new(),
            content: rendered,
            is_print: false,
            base_url: Some(self.html.site_url.clone().unwrap_or_else(|| "/".to_string())),
            chapter: None,
            html: self.html.clone(),
            fragment_map: Vec::new(),
            previous: None,
            next: None,
            live_reload: None,
        };
        let page = self.hbs.render_page(&page_ctx)?;
        let path = dest.join("404.html");
        crate::log::log(
            crate::log::Level::Debug,
            LOG_TARGET,
            format_args!("Creating 404.html \u{2713}"),
        );
        crate::utils::fs::write_file(&path, page.as_bytes())
    }

    fn render_print(
        &mut self,
        items: &mut [crate::book::BookItem],
        dest: &Path,
        chapters: &[crate::book::Chapter],
    ) -> Result<()> {
        let mut content = String::new();
        for ch in chapters {
            if ch.path.as_os_str().is_empty() {
                continue;
            }
            if !content.is_empty() {
                content.push_str(
                    "<div style=\"break-before: page; page-break-before: always;\"></div>",
                );
            }
            content.push_str(&self.render_content(&ch.content));
        }
        let page_ctx = PageCtx {
            title: String::new(),
            content,
            is_print: true,
            base_url: None,
            chapter: None,
            html: self.html.clone(),
            fragment_map: Vec::new(),
            previous: None,
            next: None,
            live_reload: None,
        };
        let page = self.hbs.render_page(&page_ctx)?;
        let path = dest.join("print.html");
        crate::log::log(
            crate::log::Level::Debug,
            LOG_TARGET,
            format_args!("Creating print.html \u{2713}"),
        );
        crate::utils::fs::write_file(&path, page.as_bytes())
    }

    fn render_redirects(
        &mut self,
        items: &mut [crate::book::BookItem],
        dest: &Path,
    ) -> Result<()> {
        let chapters = crate::book::collect_chapters(items);
        let existing: Vec<String> = chapters
            .iter()
            .map(|c| c.output_file())
            .collect();
        for (from, to) in &self.html.redirect {
            let (base, frag) = match from.split_once('#') {
                Some((b, f)) => (b.to_string(), Some(f.to_string())),
                None => (from.clone(), None),
            };
            let base = base.trim_start_matches('/');
            if frag.is_some() {
                // The page must exist as a chapter.
                if !existing.contains(&format!("{base}.html")) {
                    return Err(Error::new(format!(
                        "redirect entry for `{base}` only has source paths with `#` fragments"
