//! Writing the static files of the built book.

use crate::config::{Config, HtmlConfig};
use crate::errors::Result;
use std::path::Path;

pub const LOG_TARGET: &str = "mdbook_html::html_handlebars::static_files";

/// Write the built-in static files, plus the theme overrides.
#[allow(clippy::too_many_arguments)]
pub fn write_static(
    config: &Config,
    root: &Path,
    dest: &Path,
    html: &HtmlConfig,
    search_index: Option<&str>,
    toc_js: Option<&str>,
) -> Result<()> {
    let theme_dir = html.theme.as_ref().map(|t| crate::config::join(config, root, t.0.clone()));
    for name in crate::assets::STATIC_FILES {
        let content: Vec<u8> = match name {
            "searchindex.js" => search_index.unwrap_or_default().as_bytes().to_vec(),
            "toc.js" => toc_js.unwrap_or_default().as_bytes().to_vec(),
            _ => match theme_override(theme_dir.as_deref(), name) {
                Some(c) => c,
                None => crate::assets::asset(&format!("theme/{name}"))
                    .unwrap_or_default()
                    .to_vec(),
            },
        };
        // Fonts are not copied when `copy-fonts` is disabled.
        if name.starts_with("fonts/") && !html.copy_fonts && name != "fonts/fonts.css" {
            continue;
        }
        crate::log::log(
            crate::log::Level::Debug,
            LOG_TARGET,
            format_args!("Writing builtin -> {name}"),
        );
        crate::utils::fs::write_file(&dest.join(name), &content)?;
    }
    // The additional css and js files.
    for p in html
        .additional_css
        .iter()
        .chain(html.additional_js.iter())
    {
        let from = crate::config::join(config, root, p.0.clone());
        let to = dest.join(p.0.clone());
        crate::log::log(
            crate::log::Level::Debug,
            LOG_TARGET,
            format_args!("Copying {} -> {}", from.display(), to.display()),
        );
        crate::utils::fs::copy_file(&from, &to)?;
    }
    Ok(())
}

fn theme_override(theme_dir: Option<&Path>, name: &str) -> Option<Vec<u8>> {
    let dir = theme_dir?;
    let data = std::fs::read(dir.join(name)).ok()?;
    crate::log::log(
        crate::log::Level::Debug,
        LOG_TARGET,
        format_args!("Copying theme file {name}"),
    );
    Some(data)
}

/// Copy all the non-markdown files from the source directory.
pub fn copy_files(src: &Path, dest: &Path) -> Result<()> {
    copy_dir_filtered(src, dest)
}

fn copy_dir_filtered(src: &Path, dest: &Path) -> Result<()> {
    for entry in crate::utils::fs::read_dir_sorted(src)? {
        let name = entry.file_name();
        if name.to_str() == Some("SUMMARY.md") {
            continue;
        }
        let from = src.join(&name);
        let to = dest.join(&name);
        if entry.file_type().map(|t| t.is_dir()).unwrap_or(false) {
            copy_dir_filtered(&from, &to)?;
        } else if let Some(ext) = from.extension().and_then(|e| e.to_str()) {
            if ext.eq_ignore_ascii_case("md") || ext.eq_ignore_ascii_case("markdown") {
                continue;
            }
            crate::log::log(
                crate::log::Level::Debug,
                crate::utils::fs::LOG_TARGET,
                format_args!("Copying {:?} to {:?}", from.display().to_string(), to.display().to_string()),
            );
            crate::utils::fs::copy_file(&from, &to)?;
        }
    }
    Ok(())
}
