//! Invoking an external backend command.

use crate::driver::MdBook;
use crate::errors::{Error, Result};
use std::path::Path;

const LOG_TARGET: &str = "mdbook_driver::builtin_renderers";

pub fn render(book: &MdBook, name: &str, dest: &Path) -> Result<()> {
    let cfg = backend_config(book, name);
    let command = cfg
        .get("command")
        .and_then(|v| v.as_str())
        .map(|s| s.to_string())
        .unwrap_or_else(|| format!("mdbook-{name}"));
    let optional = cfg
        .get("optional")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    crate::log::log(
        crate::log::Level::Info,
        LOG_TARGET,
        format_args!("Invoking the \"{name}\" renderer"),
    );
    let mut parts = command.split_whitespace();
    let program = parts.next().unwrap_or_default().to_string();
    let args: Vec<&str> = parts.collect();
    match std::process::Command::new(&program)
        .args(args)
        .current_dir(dest)
        .spawn()
    {
        Ok(mut child) => {
            let _ = child.wait();
            Ok(())
        }
        Err(e) => {
            if optional {
                crate::log::log(
                    crate::log::Level::Warn,
                    LOG_TARGET,
                    format_args!(
                        "The command `{program}` wasn't found, is the \"{name}\" backend installed?"
                    ),
                );
                return Ok(());
            }
            crate::log::log(
                crate::log::Level::Error,
                LOG_TARGET,
                format_args!(
                    "The command `{program}` wasn't found, is the \"{name}\" backend installed? If you want to ignore this error when the \"{name}\" backend is not installed, set `optional = true` in the `[output.{name}]` section of the book.toml configuration file."
                ),
            );
            Err(Error::new("Rendering failed")
                .with("Unable to start the backend")
                .with(crate::errors::io_message(&e)))
        }
    }
}

fn backend_config(book: &MdBook, name: &str) -> toml::Table {
    match book.config.rest.get("output").and_then(|o| o.get(name)) {
        Some(toml::Value::Table(t)) => t.clone(),
        _ => toml::Table::new(),
    }
}
