//! The elasticlunr-compatible search index.

use crate::config::HtmlConfig;
use crate::summary::SummaryItem;
pub const LOG_TARGET: &str = "mdbook_html::html_handlebars::search";

pub struct Search<'a> {
    #[allow(dead_code)]
    html: &'a HtmlConfig,
}

impl<'a> Search<'a> {
    pub fn new(html: &'a HtmlConfig) -> Search<'a> {
        Search { html }
    }

    pub fn build(&self, _items: &mut [crate::book::BookItem]) -> String {
        String::new()
    }
}

/// Render a `serde_json`-like object from a list of key/value pairs.
pub fn json_object(items: &[(String, String)]) -> String {
    let mut out = String::from("{");
    for (i, (k, v)) in items.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        out.push_str(&crate::renderer::search::json_string(k));
        out.push(':');
        out.push_str(&crate::renderer::search::json_string(v));
    }
    out.push('}');
    out
}

pub fn json_string(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

/// Whether a summary item is a link.
pub fn is_link(item: &SummaryItem) -> bool {
    matches!(item, SummaryItem::Link { .. })
}
