//! The build, test and clean commands.

use clap_builder::ArgMatches;
use crate::errors::Result;
use std::path::Path;

pub enum Kind {
    Build,
    Test,
    Clean,
}

pub fn run(matches: &ArgMatches, kind: Kind) {
    let root = matches
        .get_one::<String>("dir")
        .map(|s| s.as_str())
        .unwrap_or(".");
    let dest = matches.get_one::<String>("dest_dir").map(|s| s.as_str());
    let result = match kind {
        Kind::Build => build(Path::new(root), dest),
        Kind::Test => test(Path::new(root), dest, matches),
        Kind::Clean => clean(Path::new(root), dest),
    };
    if let Err(e) = result {
        crate::errors::bail(&e);
    }
}

fn dest_dir(book: &crate::driver::MdBook, dest: Option<&str>) -> std::path::PathBuf {
    match dest {
        Some(d) => book.root.join(d),
        None => book.build_dir(None),
    }
}

fn build(root: &Path, dest: Option<&str>) -> Result<()> {
    let mut book = crate::driver::MdBook::load(root)?;
    let dest = dest_dir(&book, dest);
    book.build(Some(&dest))?;
    let open = false;
    if open {
        crate::cmd::open(&dest.join("index.html"));
    }
    Ok(())
}

fn test(root: &Path, dest: Option<&str>, matches: &ArgMatches) -> Result<()> {
    let mut book = crate::driver::MdBook::load(root)?;
    let dest = dest_dir(&book, dest);
    let chapter = matches.get_one::<String>("chapter").map(|s| s.as_str());
    let libs: Vec<String> = matches
        .get_many::<String>("library_path")
        .map(|it| it.map(|s| s.to_string()).collect())
        .unwrap_or_default();
    crate::test_runner::run(&book, &dest, chapter, &libs)
}

fn clean(root: &Path, dest: Option<&str>) -> Result<()> {
    let book = crate::driver::MdBook::load(root)?;
    let dest = dest_dir(&book, dest);
    let (files, size) = crate::utils::fs::remove_dir_files(&dest)?;
    if size == 0 {
        println!("Removed {files} files");
    } else {
        println!(
            "Removed {files} files, {} total",
            crate::utils::fs::format_size(size)
        );
    }
    Ok(())
}
