//! The init command.

use clap_builder::ArgMatches;
use crate::errors::Result;
use std::io::Write;
use std::path::Path;

pub fn run(matches: &ArgMatches) {
    if let Err(e) = run_inner(matches) {
        crate::errors::bail(&e);
    }
}

fn run_inner(matches: &ArgMatches) -> Result<()> {
    let root = matches
        .get_one::<String>("dir")
        .map(|s| s.as_str())
        .unwrap_or(".");
    let root = Path::new(root);
    let force = matches.get_flag("force");
    let theme = matches.get_flag("theme");
    let title = matches.get_one::<String>("title").map(|s| s.as_str());
    let ignore = matches.get_one::<String>("ignore").map(|s| s.as_str());

    std::fs::create_dir_all(root).map_err(|e| crate::errors::Error::new(crate::errors::io_message(&e)))?;
    let src = root.join("src");
    std::fs::create_dir_all(&src)
        .map_err(|e| crate::errors::Error::new(crate::errors::io_message(&e)))?;
    let build = root.join("book");
    std::fs::create_dir_all(&build)
        .map_err(|e| crate::errors::Error::new(crate::errors::io_message(&e)))?;

    // The summary.
    let summary_path = src.join("SUMMARY.md");
    if !summary_path.exists() {
        crate::utils::fs::write_file(
            &summary_path,
            b"# Summary\n\n- [Chapter 1](./chapter_1.md)\n",
        )?;
        crate::utils::fs::write_file(&src.join("chapter_1.md"), b"# Chapter 1\n")?;
        crate::log::log(
            crate::log::Level::Info,
            "mdbook_driver::init",
            format_args!("Creating a new book with stub content"),
        );
    } else {
        crate::log::log(
            crate::log::Level::Info,
            "mdbook_driver::init",
            format_args!("Creating a new book with stub content"),
        );
        // Create the missing chapters from the summary.
        let text = std::fs::read_to_string(&summary_path)
            .map_err(|e| crate::errors::Error::new(crate::errors::io_message(&e)))?;
        let summary = crate::summary::parse_summary(&text)?;
        let mut missing = Vec::new();
        collect_missing(&summary, &src, &mut missing);
        for path in missing {
            if !path.exists() {
                let name = path
                    .file_stem()
                    .and_then(|s| s.to_str())
                    .unwrap_or_default();
                crate::utils::fs::write_file(&path, format!("# {name}\n").as_bytes())?;
            }
        }
    }

    // The .gitignore file.
    let gitignore = root.join(".gitignore");
    if !gitignore.exists() {
        let answer = match ignore {
            Some("git") => true,
            Some(_) => false,
            None => {
                if force {
                    false
                } else {
                    println!();
                    println!("Do you want a .gitignore to be created? (y/n)");
                    let line = read_line();
                    line.trim().eq_ignore_ascii_case("y")
                }
            }
        };
        if answer {
            crate::utils::fs::write_file(&gitignore, b"book\n")?;
        }
    }

    // The book title.
    let title = match title {
        Some(t) => Some(t.to_string()),
        None => {
            if force {
                None
            } else {
                println!("What title would you like to give the book? ");
                let _ = std::io::stdout().flush();
                let line = read_line();
                let trimmed = line.trim();
                if trimmed.is_empty() {
                    None
                } else {
                    Some(trimmed.to_string())
                }
            }
        }
    };
    crate::utils::fs::write_file(&root.join("book.toml"), stub_config(title.as_deref()).as_bytes())?;

    // The theme.
    if theme {
        let dest = root.join("theme");
        println!("\nCopying the default theme to {}", dest.display());
        for name in crate::assets::THEME_FILES {
            let data = crate::assets::asset(&format!("theme/{name}")).unwrap_or_default();
            let path = dest.join(name);
            if !path.exists() {
                crate::utils::fs::write_file(&path, data)?;
            }
        }
    }

    println!();
    println!("All done, no errors...");
    Ok(())
}

fn collect_missing(
    summary: &crate::summary::Summary,
    src: &Path,
    out: &mut Vec<std::path::PathBuf>,
) {
    fn walk(items: &[crate::summary::SummaryItem], src: &Path, out: &mut Vec<std::path::PathBuf>) {
        for item in items {
            if let crate::summary::SummaryItem::Link { path, children, .. } = item {
                let full = src.join(path);
                if !full.exists() {
                    out.push(full);
                }
                walk(children, src, out);
            }
        }
    }
    walk(
        &summary
            .prefix_chapters
            .iter()
            .chain(summary.numbered_chapters.iter())
            .chain(summary.suffix_chapters.iter())
            .cloned()
            .collect::<Vec<_>>(),
        src,
        out,
    );
}

fn stub_config(title: Option<&str>) -> String {
    let mut out = String::from("[book]\nauthors = []\nlanguage = \"en\"\nsrc = \"src\"\n");
    if let Some(t) = title {
        out.push_str(&format!("title = {}\n", crate::renderer::search::json_string(t)));
    }
    out
}

fn read_line() -> String {
    let mut line = String::new();
    let _ = std::io::stdin().read_line(&mut line);
    line
}
