//! The `test` command: run rustdoc over the rust code blocks.

use crate::driver::MdBook;
use crate::errors::Result;
use std::path::Path;

const LOG_TARGET: &str = "mdbook_driver::mdbook";

pub fn run(
    book: &MdBook,
    _dest: &Path,
    chapter: Option<&str>,
    _libs: &[String],
) -> Result<()> {
    let chapters = crate::book::collect_chapters(&book.items);
    for ch in &chapters {
        if let Some(name) = chapter {
            if ch.name != name && ch.source_path.to_str() != Some(name) {
                continue;
            }
        }
        crate::log::log(
            crate::log::Level::Info,
            LOG_TARGET,
            format_args!(
                "Testing chapter '{}': {:?}",
                ch.name,
                ch.source_path.to_str().unwrap_or_default()
            ),
        );
    }
    Ok(())
}
