{"command": "cd /workspace && cat > src/md/block.rs <<'RSEOF'
//! Block level parsing: turns a markdown document into a stream of events.

use super::events::{Alignment, Event, Tag};
use super::inline::{self, InlineCtx};
use std::collections::HashMap;

#[derive(Clone, Copy)]
pub struct Options {
    /// Translate `--`, `---`, `...` and quotes to their unicode counterparts.
    pub smart_punctuation: bool,
}

impl Default for Options {
    fn default() -> Self {
        Options {
            smart_punctuation: false,
        }
    }
}

pub fn split_lines(text: &str) -> Vec<&str> {
    text.split('\n')
        .map(|l| l.strip_suffix('\r').unwrap_or(l))
        .collect()
}

/// Number of leading spaces (a tab counts as 4 columns).
pub fn indent_of(line: &str) -> usize {
    let mut n = 0;
    for c in line.chars() {
        match c {
            ' ' => n += 1,
            '\t' => n += 4 - (n % 4),
            _ => break,
        }
    }
    n
}

fn is_blank(line: &str) -> bool {
    line.chars().all(|c| c == ' ' || c == '\t')
}

/// A thematic break: three or more of the same punctuation with only spaces.
fn is_thematic_break(line: &str) -> bool {
    if indent_of(line) >= 4 {
        return false;
    }
    let t = line.trim_start();
    let mut chars = t.chars();
    let first = match chars.next() {
        Some(c @ ('-' | '_' | '*')) => c,
        _ => return false,
    };
    let mut count = 1;
    for c in chars {
        if c == first {
            count += 1;
        } else if c == ' ' {
            continue;
        } else {
            return false;
        }
    }
    count >= 3
}

/// ATX heading: returns (level, rest) if the line is one.
fn atx_heading(line: &str) -> Option<(u32, &str)> {
    if indent_of(line) >= 4 {
        return None;
    }
    let t = line.trim_start();
    let hashes = t.chars().take_while(|&c| c == '#').count();
    if hashes == 0 || hashes > 6 {
        return None;
    }
    let rest = &t[hashes..];
    if rest.is_empty() || rest.starts_with(' ') || rest.starts_with('\t') {
        Some((hashes as u32, rest))
    } else {
        None
    }
}

/// Setext underline.
fn setext_level(line: &str) -> Option<u32> {
    if indent_of(line) >= 4 {
        return None;
    }
    let t = line.trim_start();
    if t.is_empty() {
        return None;
    }
    let first = t.chars().next().unwrap();
    if first == '=' && t.chars().all(|c| c == '=') {
        Some(1)
    } else if first == '-' && t.chars().all(|c| c == '-') {
        Some(2)
    } else {
        None
    }
}

/// The info string of a fenced code block opener, and the fence character.
fn fence(line: &str) -> Option<(char, usize, &str)> {
    let ind = indent_of(line);
    if ind >= 4 {
        return None;
    }
    let t = &line[ind..];
    let mut chars = t.chars();
    let first = chars.next()?;
    if first != '`' && first != '~' {
        return None;
    }
    let mut count = 1;
    for c in chars {
        if c == first {
            count += 1;
        } else {
            break;
        }
    }
    if count < 3 {
        return None;
    }
    let rest = &t[count..];
    if first == '`' && rest.contains('`') {
        return None;
    }
    Some((first, count, rest))
}

/// A list marker: (indent, ordered start, content column).
fn list_marker(line: &str) -> Option<(usize, Option<u64>, usize)> {
    let ind = indent_of(line);
    if ind >= 4 {
        return None;
    }
    let t = &line[ind..];
    let bytes = t.as_bytes();
    if bytes.is_empty() {
        return None;
    }
    let (marker_len, ordered) = match bytes[0] {
        b'-' | b'+' | b'*' => {
            let rest = &t[1..];
            if rest.is_empty() || rest.starts_with(' ') || rest.starts_with('\t') {
                (1usize, None)
            } else {
                return None;
            }
        }
        b'0'..=b'9' => {
            let digits: usize = t.chars().take_while(|c| c.is_ascii_digit()).count();
            if digits > 9 || digits == 0 {
                return None;
            }
            if bytes[digits] != b'.' {
                return None;
            }
            let rest = &t[digits + 1..];
            if rest.is_empty() || rest.starts_with(' ') || rest.starts_with('\t') {
                let num: u64 = t[..digits].parse().ok()?;
                (digits + 1, Some(num))
            } else {
                return None;
            }
        }
        _ => return None,
    };
    let chars: Vec<char> = line.chars().collect();
    let mut col = ind + marker_len;
    while col < chars.len() && (chars[col] == ' ' || chars[col] == '\t') {
        col += 1;
    }
    Some((ind, ordered, col))
}

/// The offset (in bytes) of the content column of a list marker line.
fn content_offset(line: &str, col: usize) -> usize {
    let mut n = 0;
    let mut seen = 0;
    for (i, c) in line.char_indices() {
        if seen >= col {
            break;
        }
        n = i + c.len_utf8();
        seen += 1;
    }
    n
}

fn block_quote(line: &str) -> Option<usize> {
    let ind = indent_of(line);
    if ind >= 4 {
        return None;
    }
    let t = &line[ind..];
    if t.starts_with('>') {
        // One optional space after the marker.
        let rest = &t[1..];
        let extra = if rest.starts_with(' ') { 1 } else { 0 };
        Some(ind + 1 + extra)
    } else {
        None
    }
}

fn html_block_start(line: &str) -> bool {
    if indent_of(line) >= 4 {
        return false;
    }
    let t = line.trim_start();
    if !t.starts_with('<') {
        return false;
    }
    let rest = &t[1..];
    if rest.starts_with('/') {
        return true;
    }
    if rest.starts_with("!--") || rest.starts_with('?') || rest.starts_with('!') {
        return true;
    }
    let name: String = rest
        .chars()
        .take_while(|&c| c.is_ascii_alphanumeric() || c == '-')
        .collect();
    if name.is_empty() {
        return false;
    }
    matches!(
        name.to_ascii_lowercase().as_str(),
        "address" | "article" | "aside" | "blockquote" | "details" | "dialog" | "dd" | "div"
            | "dl" | "dt" | "fieldset" | "figcaption" | "figure" | "footer" | "form" | "h1"
            | "h2" | "h3" | "h4" | "h5" | "h6" | "header" | "hgroup" | "hr" | "li" | "main"
            | "menu" | "nav" | "ol" | "p" | "pre" | "section" | "table" | "tbody" | "td"
            | "tfoot" | "th" | "thead" | "tr" | "ul"
    )
}

fn footnote_definition(line: &str) -> Option<usize> {
    if indent_of(line) >= 4 {
        return None;
    }
    let t = line.trim_start();
    if !t.starts_with("[^") {
        return None;
    }
    let end = t.find(']')?;
    let label = &t[2..end];
    if label.is_empty() {
        return None;
    }
    let after = &t[end + 1..];
    if after.starts_with(':') {
        Some(end + 1)
    } else {
        None
    }
}

type RefDefs = HashMap<String, (String, String)>;

struct Parser<'a> {
    opts: &'a Options,
    lines: Vec<&'a str>,
    events: Vec<Event>,
    refs: RefDefs,
}

pub fn parse(text: &str, opts: &Options) -> Vec<Event> {
    let lines = split_lines(text);
    let mut refs = RefDefs::new();
    scan_link_refs(&lines, &mut refs);
    let mut p = Parser {
        opts,
        lines,
        events: Vec::new(),
        refs,
    };
    p.parse_blocks();
    p.events
}

/// Pre-scan the document for link reference definitions.
fn scan_link_refs(lines: &[&str], refs: &mut RefDefs) {
    let mut i = 0;
    while i < lines.len() {
        let line = lines[i];
        if indent_of(line) >= 4 || is_blank(line) {
            i += 1;
            continue;
        }
        let t = line.trim_start();
        if !t.starts_with('[') {
            i += 1;
            continue;
        }
        let Some(close) = find_close(t) else {
            i += 1;
            continue;
        };
        let after = &t[close + 1..];
        let Some(colon) = after.find(':') else {
            i += 1;
            continue;
        };
        if colon != 0 {
            i += 1;
            continue;
        }
        let label = t[1..close].to_string();
        let mut rest = after[1..].trim_start().to_string();
        let mut url = String::new();
        let mut title = String::new();
        let mut j = i;
        loop {
            if j >= lines.len() {
                break;
            }
            let src = if j == i {
                rest.clone()
            } else {
                lines[j].trim_start().to_string()
            };
            if src.is_empty() {
                break;
            }
            let (u, tail) = if let Some(stripped) = src.strip_prefix('<') {
                match stripped.find('>') {
                    Some(end) => (stripped[..end].to_string(), stripped[end + 1..].to_string()),
                    None => break,
                }
            } else {
                let mut k = 0;
                let bytes = src.as_bytes();
                while k < bytes.len() && bytes[k] != b' ' && bytes[k] != b'\t' {
                    k += 1;
                }
                (src[..k].to_string(), src[k..].to_string())
            };
            url = u;
            rest = tail.trim_start().to_string();
            if let Some(q) = rest.find('"') {
                if rest.len() >= 2 && rest.ends_with('"') && q == 0 {
                    title = rest[1..rest.len() - 1].to_string();
                    rest.clear();
                }
            }
            j += 1;
            if rest.is_empty() {
                break;
            }
        }
        if !url.is_empty() {
            refs.entry(label).or_insert((url, title));
        }
        i = j;
    }
}

fn find_close(t: &str) -> Option<usize> {
    let bytes = t.as_bytes();
    let mut i = 1;
    while i < bytes.len() {
        if bytes[i] == b'\\' {
            i += 2;
            continue;
        }
        if bytes[i] == b']' {
            return Some(i);
        }
        i += 1;
    }
    None
}

fn ctx_for<'a>(p: &'a Parser) -> InlineCtx<'a> {
    InlineCtx {
        refs: &p.refs,
        smart_punctuation: p.opts.smart_punctuation,
        footnotes: true,
    }
}

impl<'a> Parser<'a> {
    fn ctx(&self) -> InlineCtx<'a> {
        ctx_for(self)
    }

    fn push_inline(&mut self, text: &str) {
        let ctx = self.ctx();
        let events = inline::inline_events(text, &ctx);
        self.events.extend(events);
    }

    fn parse_blocks(&mut self) {
        let mut i = 0;
        while i < self.lines.len() {
            let line = self.lines[i];
            if is_blank(line) {
                i += 1;
                continue;
            }
            // Fenced code block
            if let Some((fence_char, fence_len, info)) = fence(line) {
                let mut content = String::new();
                let mut j = i + 1;
                while j < self.lines.len() {
                    let l = self.lines[j];
                    let ind = indent_of(l);
                    if ind < 4 {
                        let t = &l[ind..];
                        let run = t.chars().take_while(|&c| c == fence_char).count();
                        if run >= fence_len && run == t.chars().count() {
                            j += 1;
                            break;
                        }
                    }
                    let strip = (ind.min(4)).min(indent_of(line));
                    content.push_str(&l[strip..]);
                    content.push('\n');
                    j += 1;
                }
                self.events.push(Event::Start(Tag::CodeBlock(info.to_string())));
                self.events.push(Event::Text(content));
                self.events.push(Event::End(Tag::CodeBlock(String::new())));
                i = j;
                continue;
            }
            // Indented code block
            if indent_of(line) >= 4 {
                let mut content: Vec<&str> = Vec::new();
                let mut j = i;
                while j < self.lines.len() {
                    let l = self.lines[j];
                    if is_blank(l) {
                        let mut k = j + 1;
                        while k < self.lines.len() && is_blank(self.lines[k]) {
                            k += 1;
                        }
                        if k < self.lines.len() && indent_of(self.lines[k]) >= 4 {
                            content.push("");
                            j = k;
                            continue;
                        }
                        break;
                    }
                    if indent_of(l) < 4 {
                        break;
                    }
                    content.push(&l[4.min(l.len())..]);
                    j += 1;
                }
                self.events.push(Event::Start(Tag::CodeBlock(String::new())));
                self.events.push(Event::Text(content.join("\n")));
                self.events.push(Event::End(Tag::CodeBlock(String::new())));
                i = j;
                continue;
            }
            // HTML block
            if html_block_start(line) {
                let mut content = String::new();
                let mut j = i;
                let mut blank_before = false;
                while j < self.lines.len() {
                    let l = self.lines[j];
                    if is_blank(l) {
                        blank_before = true;
                        j += 1;
                        continue;
                    }
                    if blank_before {
                        break;
                    }
                    content.push_str(l);
                    content.push('\n');
                    j += 1;
                }
                self.events.push(Event::Html(content));
                i = j;
                continue;
            }
            // ATX heading
            if let Some((level, rest)) = atx_heading(line) {
                let mut content = rest.trim().to_string();
                if content.ends_with('#') && (content.len() == 1 || content.ends_with(" #")) {
                    content = content.trim_end_matches('#').trim_end().to_string();
                }
                let (id, classes, attrs) = inline::parse_heading_attrs(&content);
                self.events.push(Event::Start(Tag::Heading(
                    level, id.clone(), classes.clone(), attrs.clone(),
                )));
                self.push_inline(&content_with_attrs(&content, id.as_deref()));
                self.events.push(Event::End(Tag::Heading(
                    level, None, Vec::new(), Vec::new(),
                )));
                i += 1;
                continue;
            }
            // Thematic break
            if is_thematic_break(line) {
                self.events.push(Event::Rule);
                i += 1;
                continue;
            }
            // Footnote definition
            if let Some(colon) = footnote_definition(line) {
                let t = line.trim_start();
                let end = t.find(']').unwrap();
                let label = t[2..end].to_string();
                let mut inner: Vec<&str> = Vec::new();
                let after = &t[colon + 1..];
                inner.push(after.trim_start());
                let mut j = i + 1;
                while j < self.lines.len() {
                    let l = self.lines[j];
                    if is_blank(l) {
                        let mut k = j + 1;
                        while k < self.lines.len() && is_blank(self.lines[k]) {
                            k += 1;
                        }
                        if k < self.lines.len() && indent_of(self.lines[k]) >= 4 {
                            inner.push("");
                            j = k;
                            continue;
                        }
                        break;
                    }
                    if indent_of(l) < 4 {
                        break;
                    }
                    inner.push(&l[4.min(l.len())..]);
                    j += 1;
                }
                self.events
                    .push(Event::Start(Tag::FootnoteDefinition(label)));
                let sub = parse(&inner.join("\n"), self.opts);
                self.events.extend(sub);
                self.events
                    .push(Event::End(Tag::FootnoteDefinition(String::new())));
                i = j;
                continue;
            }
            // Block quote
            if let Some(off) = block_quote(line) {
                let mut inner: Vec<&str> = Vec::new();
                let mut j = i;
                let mut blank = false;
                let mut started = false;
                while j < self.lines.len() {
                    let l = self.lines[j];
                    if is_blank(l) {
                        blank = true;
                        j += 1;
                        continue;
                    }
                    if let Some(off2) = block_quote(l) {
                        if blank && started {
                            break;
                        }
                        inner.push(&l[off2..]);
                        blank = false;
                        started = true;
                        j += 1;
                        continue;
                    }
                    if blank || !started || indent_of(l) >= 4 {
                        break;
                    }
                    // Lazy continuation.
                    inner.push(l);
                    j += 1;
                }
                self.events.push(Event::Start(Tag::BlockQuote));
                let sub = parse(&inner.join("\n"), self.opts);
                self.events.extend(sub);
                self.events.push(Event::End(Tag::BlockQuote));
                i = j;
                continue;
            }
            // Table
            if let Some(alignments) = self.try_table(i) {
                let n = alignments.1;
                i = n;
                continue;
            }
            // List
            if let Some((indent, start, _)) = list_marker(line) {
                i = parse_list_impl(self, i, indent, start);
                continue;
            }
            // Paragraph, possibly a setext heading
            let mut content: Vec<&str> = Vec::new();
            let mut j = i;
            while j < self.lines.len() {
                let l = self.lines[j];
                if is_blank(l) {
                    break;
                }
                if !content.is_empty() {
                    if indent_of(l) >= 4
                        || atx_heading(l).is_some()
                        || is_thematic_break(l)
                        || fence(l).is_some()
                        || footnote_definition(l).is_some()
                        || html_block_start(l)
                        || block_quote(l).is_some()
                        || list_marker(l).is_some()
                    {
                        break;
                    }
                }
                content.push(l);
                j += 1;
            }
            if content.is_empty() {
                i += 1;
                continue;
            }
            if let Some(level) = setext_level(self.lines.get(j).copied().unwrap_or("")) {
                let text: String = content
                    .iter()
                    .map(|l| l.trim_start())
                    .collect::<Vec<_>>()
                    .join("\n");
                let (id, classes, attrs) = inline::parse_heading_attrs(&text);
                self.events.push(Event::Start(Tag::Heading(
                    level, id.clone(), classes.clone(), attrs.clone(),
                )));
                self.push_inline(&content_with_attrs(&text, id.as_deref()));
                self.events.push(Event::End(Tag::Heading(
                    level, None, Vec::new(), Vec::new(),
                )));
                i = j + 1;
                continue;
            }
            self.push_paragraph(&content);
            i = j;
        }
    }

    fn try_table(&mut self, i: usize) -> Option<(Vec<Alignment>, usize)> {
        if i + 1 >= self.lines.len() {
            return None;
        }
        let header = self.lines[i];
        if !header.contains('|') || indent_of(header) >= 4 {
            return None;
        }
        let alignments = table_delimiter(self.lines[i + 1])?;
        let cells = table_row(header)?;
        self.events.push(Event::Start(Tag::Table(alignments.clone())));
        self.events.push(Event::Start(Tag::TableHead));
        self.events.push(Event::Start(Tag::TableRow));
        for cell in &cells {
            self.push_cell(cell);
        }
        self.events.push(Event::End(Tag::TableRow));
        self.events.push(Event::End(Tag::TableHead));
        self.events.push(Event::Start(Tag::TableRow));
        let mut j = i + 2;
        while j < self.lines.len() {
            let l = self.lines[j];
            if is_blank(l) || !l.contains('|') || indent_of(l) >= 4 {
                break;
            }
            match table_row(l) {
                Some(cells) => {
                    self.events.push(Event::Start(Tag::TableRow));
                    for cell in &cells {
                        self.push_cell(cell);
                    }
                    self.events.push(Event::End(Tag::TableRow));
                }
                None => break,
            }
            j += 1;
        }
        self.events.push(Event::End(Tag::TableRow));
        self.events.push(Event::End(Tag::Table(alignments.clone())));
        self.out.push('\n');
        Some((alignments, j))
    }

    fn push_cell(&mut self, cell: &str) {
        self.events.push(Event::Start(Tag::TableCell));
        self.push_inline(cell);
        self.events.push(Event::End(Tag::TableCell));
    }

    fn push_paragraph(&mut self, lines: &[&str]) {
        let mut text = String::new();
        for (n, l) in lines.iter().enumerate() {
            if n > 0 {
                text.push('\n');
            }
            text.push_str(l.trim_start());
        }
        let text = text.trim_end().to_string();
        self.events.push(Event::Start(Tag::Paragraph));
        // Breaks between lines.
        let parts: Vec<&str> = text.split('\n').collect();
        for (n, part) in parts.iter().enumerate() {
            if n > 0 {
                self.events.push(Event::SoftBreak);
            }
            self.push_inline(part);
        }
        self.events.push(Event::End(Tag::Paragraph));
    }
}

/// Strip the heading attributes from the text so they are not rendered.
fn content_with_attrs(text: &str, _id: Option<&str>) -> String {
    let trimmed = text.trim_end();
    if trimmed.ends_with('}') {
        if let Some(open) = trimmed.rfind('{') {
            if open > 0 && trimmed[..open].ends_with(' ') {
                return trimmed[..open].trim_end().to_string();
            }
        }
    }
    text.to_string()
}

fn table_delimiter(line: &str) -> Option<Vec<Alignment>> {
    if !line.contains('|') {
        return None;
    }
    let cells = split_row(line)?;
    let mut alignments = Vec::new();
    for cell in cells {
        let c = cell.trim();
        if c.is_empty() {
            return None;
        }
        let mut left = false;
        let mut right = false;
        let mut dashes = 0;
        let mut chars = c.chars().peekable();
        if chars.peek() == Some(&':') {
            left = true;
            chars.next();
        }
        while let Some(&ch) = chars.peek() {
            if ch == '-' {
                dashes += 1;
                chars.next();
            } else {
                break;
            }
        }
        if chars.peek() == Some(&':') {
            right = true;
            chars.next();
        }
        if chars.next().is_some() || dashes == 0 {
            return None;
        }
        alignments.push(match (left, right) {
            (true, true) => Alignment::Center,
            (true, false) => Alignment::Left,
            (false, true) => Alignment::Right,
            (false, false) => Alignment::None,
        });
    }
    Some(alignments)
}

/// Split a table row into cells.
fn split_row(line: &str) -> Option<Vec<String>> {
    let t = line.trim();
    if t.is_empty() || !t.contains('|') {
        return None;
    }
    let mut s = t;
    if s.starts_with('|') {
        s = &s[1..];
    }
    if s.ends_with('|') {
        s = &s[..s.len() - 1];
    }
    let mut cells = Vec::new();
    let mut cur = String::new();
    let mut escaped = false;
    for c in s.chars() {
        if escaped {
            cur.push('\\');
            cur.push(c);
            escaped = false;
            continue;
        }
        match c {
            '\\' => escaped = true,
            '|' => cells.push(std::mem::take(&mut cur)),
            _ => cur.push(c),
        }
    }
    cells.push(cur);
    Some(cells)
}

fn table_row(line: &str) -> Option<Vec<String>> {
    if !line.contains('|') {
        return None;
    }
    if indent_of(line) >= 4 {
        return None;
    }
    let t = line.trim();
    if t.is_empty() || t.starts_with('>') {
        return None;
    }
    let cells = split_row(line)?;
    if cells.is_empty() {
        return None;
    }
    if table_delimiter(line).is_some() {
        return None;
    }
    Some(cells)
}

#[allow(clippy::too_many_arguments)]
fn parse_list_impl(
    p: &mut Parser,
    start_line: usize,
    indent: usize,
    start: Option<u64>,
) -> usize {
    let mut items: Vec<(usize, Vec<&str>)> = Vec::new();
    let mut loose = false;
    let mut cur: Vec<&str> = Vec::new();
    let mut cur_content_col = 0usize;
    let mut blank = false;
    let mut j = start_line;
    let mut first = true;
    let mut start_num = start;

    while j < p.lines.len() {
        let line = p.lines[j];
        if is_blank(line) {
            blank = true;
            j += 1;
            continue;
        }
        let ind = indent_of(line);
        if let Some((ind2, start2, col2)) = list_marker(line) {
            if ind2 == indent {
                if first {
                    start_num = start2;
                    cur_content_col = col2;
                    cur.push(&line[content_offset(line, col2)..]);
                    first = false;
                    blank = false;
                    j += 1;
                    continue;
                }
                if blank {
                    loose = true;
                }
                items.push((cur_content_col, std::mem::take(&mut cur)));
                cur_content_col = col2;
                cur.push(&line[content_offset(line, col2)..]);
                blank = false;
                j += 1;
                continue;
            }
            if ind2 > indent && !first {
                if blank {
                    loose = true;
                }
                blank = false;
                cur.push(strip_indent(line, cur_content_col));
                j += 1;
                continue;
            }
        }
        if first {
            break;
        }
        if blank {
            if ind >= cur_content_col {
                loose = true;
                cur.push("");
                blank = false;
                cur.push(strip_indent(line, cur_content_col));
                j += 1;
                continue;
            }
            break;
        }
        if ind >= cur_content_col {
            cur.push(strip_indent(line, cur_content_col));
            j += 1;
            continue;
        }
        if ind > indent {
            cur.push(strip_indent(line, indent));
            j += 1;
            continue;
        }
        break;
    }
    if !first {
        items.push((cur_content_col, cur));
    }

    p.events.push(Event::Start(Tag::List(start_num)));
    for (_col, content) in items {
        let text = content.join("\n");
        let mut body = text.as_str();
        if let Some((checked, rest)) = task_marker(body) {
            p.events.push(Event::TaskMarker(checked));
            body = rest;
        }
        let sub = parse(body, p.opts);
        p.events.push(Event::Start(Tag::Item));
        if !loose {
            // A tight item contains a single paragraph; unwrap it.
            if sub.len() == 3
                && matches!(sub[0], Event::Start(Tag::Paragraph))
                && matches!(sub[2], Event::End(Tag::Paragraph))
            {
                let inner = sub[1].clone();
                p.events.push(inner);
                p.events.push(Event::End(Tag::Item));
                continue;
            }
        }
        p.events.extend(sub);
        p.events.push(Event::End(Tag::Item));
    }
    p.events.push(Event::End(Tag::List(start_num)));
    j
}

/// Strip at most `n` columns of leading whitespace.
fn strip_indent(line: &str, n: usize) -> &str {
    let mut count = 0;
    let mut idx = 0;
    for c in line.chars() {
        if count >= n {
            break;
        }
        if c == ' ' {
            count += 1;
            idx += 1;
        } else if c == '\t' {
            count += 4;
            idx += 1;
        } else {
            break;
        }
    }
    &line[idx..]
}

/// Recognise a task list marker, returning whether it is checked and the rest.
fn task_marker(text: &str) -> Option<(bool, &str)> {
    let t = text.strip_prefix('[')?;
    let (checked, rest) = match t.chars().next()? {
        ' ' => (false, &t[1..]),
        'x' | 'X' => (true, &t[1..]),
        _ => return None,
    };
    if rest.starts_with(']') {
        let after = &rest[1..];
        if after.is_empty() || after.starts_with(' ') {
            return Some((checked, after.strip_prefix(' ').unwrap_or(after)));
        }
    }
    None
}
