import os
files=[]
for root,dirs,fs in os.walk('assets'):
    for f in sorted(fs):
        p=os.path.join(root,f)
        files.append(os.path.relpath(p,'assets'))
files.sort()
out=['//! Generated list of the bundled assets.','']
out.append('pub static ASSETS: &[(&str, &[u8])] = &[')
for rel in files:
    esc=rel.replace('\\','\\\\').replace('"','\\"')
    out.append(f'    ("{esc}", include_bytes!("../assets/{esc}")),')
out.append('];')
out.append('')
out.append('''/// Look up a bundled asset by its relative path.
pub fn asset(path: &str) -> Option<&'static [u8]> {
    ASSETS.iter().find(|(p, _)| *p == path).map(|(_, d)| *d)
}

/// The text of an asset.
pub fn asset_str(path: &str) -> &'static str {
    match asset(path) {
        Some(d) => std::str::from_utf8(d).unwrap_or_default(),
        None => "",
    }
}

/// The names of all the bundled assets.
pub fn names() -> Vec<&'static str> {
    ASSETS.iter().map(|(p, _)| *p).collect()
}''')
open('src/assets_data.rs','w').write('\n'.join(out))
