/// A document of the search index.
struct Doc {
    url: String,
    title: String,
    breadcrumbs: String,
    body: String,
}

pub struct Search<'a> {
    html: &'a HtmlConfig,
}

impl<'a> Search<'a> {
    pub fn new(html: &'a HtmlConfig) -> Search<'a> {
        Search { html }
    }

    /// Build the search index JSON.
    pub fn build(&self, items: &mut [BookItem]) -> String {
        let chapters = crate::book::collect_chapters(items);
        let mut docs: Vec<Doc> = Vec::new();
        for ch in &chapters {
            if ch.path.as_os_str().is_empty() {
                continue;
            }
            let ancestors: Vec<&str> = ch
                .parent_names
                .iter()
                .map(|s| s.as_str())
                .chain(std::iter::once(ch.name.as_str()))
                .collect();
            let sections = split_sections(&ch.content, self.html.search.heading_split_level as u32);
            let mut parts: Vec<String> = Vec::new();
            for p in &ancestors {
                parts.push(p.to_string());
            }
            if sections.is_empty() {
                docs.push(Doc {
                    url: ch.output_file(),
                    title: ch.name.clone(),
                    breadcrumbs: parts.join(" \u{00bb} "),
                    body: String::new(),
                });
                continue;
            }
            for section in sections {
                let mut breadcrumbs = parts.clone();
                if let Some(title) = &section.title {
                    breadcrumbs.push(title.clone());
                }
                docs.push(Doc {
                    url: format!("{}#{}", ch.output_file(), section.id),
                    title: section.title.clone().unwrap_or_else(|| ch.name.clone()),
                    breadcrumbs: breadcrumbs.join(" \u{00bb} "),
                    body: section.body,
                });
