            let mut info = serde_json::Map::new();
            for field in fields {
                let tokens = tokenize(&field_text(doc, field));
                let mut terms: HashMap<String, f64> = HashMap::new();
                for t in tokens {
                    *terms.entry(t).or_insert(0.0) += 1.0;
                }
                let count = terms.len();
                info.insert(field.to_string(), json!(count));
                let field_index = index.entry(field).or_default();
                for (term, freq) in terms {
                    field_index
                        .entry(term)
                        .or_default()
                        .insert(id.to_string(), freq.sqrt());
                }
            }
            doc_info.push(info);
        }

        let mut root = serde_json::Map::new();
        root.insert(
            "doc_urls".to_string(),
            Json::Array(docs.iter().map(|d| Json::String(d.url.clone())).collect()),
        );
        let mut inner = serde_json::Map::new();
        // documentStore
        let mut store = serde_json::Map::new();
        let mut doc_info_map = serde_json::Map::new();
        let mut docs_map = serde_json::Map::new();
        for (id, doc) in docs.iter().enumerate() {
            doc_info_map.insert(id.to_string(), Json::Object(doc_info[id].clone()));
            let mut d = serde_json::Map::new();
            d.insert("body".to_string(), Json::String(doc.body.clone()));
            d.insert("breadcrumbs".to_string(), Json::String(doc.breadcrumbs.clone()));
            d.insert("id".to_string(), Json::String(id.to_string()));
            d.insert("title".to_string(), Json::String(doc.title.clone()));
            docs_map.insert(id.to_string(), Json::Object(d));
        }
        store.insert("docInfo".to_string(), Json::Object(doc_info_map));
        store.insert("docs".to_string(), Json::Object(docs_map));
        store.insert("length".to_string(), json!(docs.len()));
        store.insert("save".to_string(), json!(true));
        inner.insert("documentStore".to_string(), Json::Object(store));
        inner.insert(
            "fields".to_string(),
            Json::Array(fields.iter().map(|f| Json::String(f.to_string())).collect()),
        );
        let mut index_map = serde_json::Map::new();
        for field in fields {
            let terms = index.remove(field).unwrap_or_default();
            let trie = build_trie(&terms);
            let mut f = serde_json::Map::new();
            f.insert("root".to_string(), trie);
            index_map.insert(field.to_string(), Json::Object(f));
        }
        inner.insert("index".to_string(), Json::Object(index_map));
        inner.insert("lang".to_string(), Json::String("English".to_string()));
        inner.insert(
            "pipeline".to_string(),
            Json::Array(vec![
                Json::String("trimmer".to_string()),
                Json::String("stopWordFilter".to_string()),
                Json::String("stemmer".to_string()),
            ]),
        );
        inner.insert("ref".to_string(), Json::String("id".to_string()));
        inner.insert("version".to_string(), Json::String("0.9.5".to_string()));
        root.insert("index".to_string(), Json::Object(inner));
        let mut results = serde_json::Map::new();
        results.insert(
            "limit_results".to_string(),
            match self.html.search.limit_results {
                Some(n) => json!(n),
                None => Json::Null,
            },
        );
        results.insert(
            "teaser_word_count".to_string(),
            json!(self.html.search.teaser_word_count),
        );
        root.insert("results_options".to_string(), Json::Object(results));
        let mut options = serde_json::Map::new();
        options.insert(
            "bool".to_string(),
            Json::String(if self.html.search.use_boolean_and {
                "AND".to_string()
            } else {
                "OR".to_string()
            }),
        );
        options.insert("expand".to_string(), json!(self.html.search.expand));
        let mut fields_boost = serde_json::Map::new();
        for (name, boost) in [
            ("body", self.html.search.boost_hierarchy),
            ("breadcrumbs", self.html.search.boost_hierarchy),
            ("title", self.html.search.boost_title),
        ] {
            let mut f = serde_json::Map::new();
            f.insert("boost".to_string(), json!(boost));
            fields_boost.insert(name.to_string(), Json::Object(f));
        }
        options.insert("fields".to_string(), Json::Object(fields_boost));
