struct Section {
    title: Option<String>,
    id: String,
    body: String,
}

/// Split a chapter into sections at headings of the given level or lower.
fn split_sections(content: &str, split_level: u32) -> Vec<Section> {
    let opts = MdOptions::default();
    let events = crate::md::block::parse(content, &opts);
    let mut sections: Vec<Section> = Vec::new();
    let mut current = Section {
        title: None,
        id: String::new(),
        body: String::new(),
    };
    let mut i = 0;
    while i < events.len() {
        match &events[i] {
            Event::Start(Tag::Heading(level, id, _, _)) if *level <= split_level => {
                let mut j = i + 1;
                while j < events.len() {
                    if matches!(events[j], Event::End(Tag::Heading(..))) {
                        break;
                    }
                    j += 1;
                }
                let text = collect_text(&events[i + 1..j]);
                if current.title.is_none() && sections.is_empty() {
                    current.title = Some(text.clone());
                } else {
                    sections.push(std::mem::replace(
                        &mut current,
                        Section {
                            title: Some(text.clone()),
                            id: String::new(),
                            body: String::new(),
                        },
                    ));
                }
                current.id = id.clone().unwrap_or_else(|| crate::md::html::id_from_content(&text));
                i = j + 1;
                continue;
            }
            Event::Text(t) => {
                push_text(&mut current.body, t);
            }
            Event::Code(c) => {
                push_text(&mut current.body, c);
            }
            Event::SoftBreak | Event::HardBreak => {
                push_text(&mut current.body, " ");
            }
            Event::Html(h) | Event::InlineHtml(h) => {
                push_text(&mut current.body, &strip_tags(h));
            }
            Event::FootnoteRef(_) => {}
            Event::TaskMarker(_) => {}
            _ => {}
        }
        i += 1;
    }
    if !current.body.trim().is_empty() || current.title.is_some() {
        sections.push(current);
    }
    sections
}

fn push_text(body: &mut String, text: &str) {
    if !body.is_empty() {
        body.push(' ');
    }
    body.push_str(text);
}

fn strip_tags(html: &str) -> String {
    let mut out = String::new();
    let mut in_tag = false;
    for c in html.chars() {
        match c {
            '<' => in_tag = true,
            '>' => in_tag = false,
            c if !in_tag => out.push(c),
            _ => {}
        }
    }
    out
}

fn collect_text(events: &[Event]) -> String {
    let mut out = String::new();
    for ev in events {
        match ev {
            Event::Text(t) => out.push_str(t),
            Event::SoftBreak | Event::HardBreak => out.push(' '),
            _ => {}
        }
    }
    out
}

fn field_text(doc: &Doc, field: &str) -> String {
    match field {
        "title" => doc.title.clone(),
        "body" => doc.body.clone(),
        _ => doc.breadcrumbs.clone(),
    }
}

/// Normalize the whitespace of a text.
fn normalize(text: &str) -> String {
    let mut out = String::new();
    let mut ws = false;
    for c in text.chars() {
        if c.is_whitespace() {
            ws = true;
        } else {
            if ws && !out.is_empty() {
                out.push(' ');
            }
            ws = false;
            out.push(c);
        }
    }
    out
}

/// Tokenize a text the way the search index does.
pub fn tokenize(text: &str) -> Vec<String> {
    let lower = text.to_lowercase();
    let mut tokens = Vec::new();
    let mut cur = String::new();
    for c in lower.chars() {
        if c.is_whitespace() || c == '-' {
            if !cur.is_empty() {
                tokens.push(std::mem::take(&mut cur));
            }
        } else {
            cur.push(c);
        }
    }
    if !cur.is_empty() {
        tokens.push(cur);
    }
    tokens
        .into_iter()
        .map(|t| {
            let trimmed = trimmer(&t);
            if trimmed.is_empty() {
                None
            } else if stopwords().contains(trimmed.as_str()) {
                None
            } else {
                Some(stem(&trimmed))
            }
        })
        .flatten()
        .collect()
}

/// Remove leading and trailing non-word characters (ASCII word characters).
fn trimmer(token: &str) -> String {
    token
        .trim_start_matches(|c: char| !is_word(c))
        .trim_end_matches(|c: char| !is_word(c))
        .to_string()
}

fn is_word(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_'
}

/// The body text of a document, with whitespace normalized.
pub fn body_text(text: &str) -> String {
    normalize(text)
}

/// Build the trie node for a field.
fn build_trie(terms: &HashMap<String, HashMap<String, f64>>) -> Json {
    let mut node = serde_json::Map::new();
    node.insert("df".to_string(), json!(0));
    node.insert("docs".to_string(), Json::Object(serde_json::Map::new()));
    // Group the terms by their first character.
    let mut by_char: HashMap<char, Vec<(String, HashMap<String, f64>)>> = HashMap::new();
    for (term, docs) in terms {
        let mut chars = term.chars();
        let first = chars.next().unwrap_or('\0');
        by_char.entry(first).or_default().push((term.clone(), docs.clone()));
    }
    let mut keys: Vec<char> = by_char.keys().copied().collect();
    keys.sort();
    for c in keys {
        let entries = &by_char[&c];
        if entries.len() == 1 && entries[0].0.chars().count() == 1 {
            let docs = &entries[0].1;
            let mut n = serde_json::Map::new();
            n.insert("df".to_string(), json!(docs.len()));
            n.insert("docs".to_string(), docs_to_json(docs));
            node.insert(c.to_string(), Json::Object(n));
        } else {
            let mut sub: HashMap<String, HashMap<String, f64>> = HashMap::new();
            for (term, docs) in entries {
                let rest: String = term.chars().skip(1).collect();
                if rest.is_empty() {
                    let mut n = serde_json::Map::new();
                    n.insert("df".to_string(), json!(docs.len()));
                    n.insert("docs".to_string(), docs_to_json(docs));
                    node.insert(c.to_string(), Json::Object(n));
                } else {
                    sub.insert(rest, docs.clone());
                }
            }
            if !sub.is_empty() {
                let child = build_trie(&sub);
                match node.get_mut(&c.to_string()) {
                    Some(Json::Object(existing)) => {
                        if let Json::Object(child_obj) = child {
                            for (k, v) in child_obj {
                                existing.insert(k, v);
                            }
                        }
                    }
                    _ => {
                        node.insert(c.to_string(), child);
                    }
                }
            }
        }
    }
    Json::Object(node)
}

fn docs_to_json(docs: &HashMap<String, f64>) -> Json {
    let mut out = serde_json::Map::new();
    for (id, tf) in docs {
        let mut d = serde_json::Map::new();
        d.insert("tf".to_string(), json!(tf));
        out.insert(id.clone(), Json::Object(d));
    }
    Json::Object(out)
}

/// Render a list of key/value pairs as a JSON object.
pub fn json_object(items: &[(String, String)]) -> String {
    let mut out = String::from("{");
    for (i, (k, v)) in items.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        out.push_str(&json_string(k));
        out.push(':');
        out.push_str(&json_string(v));
    }
    out.push('}');
    out
}

/// Escape a string for embedding in a single quoted JavaScript string.
pub fn json_string(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}
