/// Whether the stem `b[0..=j]` contains a vowel.
fn vowel_in_stem(b: &[u8], j: usize) -> bool {
    for i in 0..=j {
        if !is_cons(b, i) {
            return true;
        }
    }
    false
}

/// Whether the stem ends with a double consonant.
fn doublec(b: &[u8], j: usize) -> bool {
    if j < 1 {
        return false;
    }
    if b[j] != b[j - 1] {
        return false;
    }
    is_cons(b, j)
}

/// cvc(i): the stem ends with consonant-vowel-consonant and the last consonant
/// is not `w`, `x` or `y`.
fn cvc(b: &[u8], i: usize) -> bool {
    if i < 2 || !is_cons(b, i) || is_cons(b, i - 1) || !is_cons(b, i - 2) {
        return false;
    }
    let ch = b[i];
    ch != b'w' && ch != b'x' && ch != b'y'
}

fn ends_with(b: &[u8], k: usize, suffix: &str) -> bool {
    let s = suffix.as_bytes();
    if s.len() > k + 1 {
        return false;
    }
    let start = k + 1 - s.len();
    &b[start..=k] == s
}

const fn _unused() {}

/// Stem a lowercase ASCII-ish word.
pub fn stem(word: &str) -> String {
    let mut b: Vec<u8> = word.bytes().collect();
    // Non ASCII words are left alone.
    if b.iter().any(|c| !c.is_ascii_alphabetic()) {
        return word.to_string();
    }
    let mut k = b.len() as i32 - 1;
    if k <= 1 {
        return word.to_string();
    }
    let b0 = &mut b;
    // Step 1a
    if b0[k as usize] == b's' {
        if ends_with(b0, k as usize, "sses") {
            k -= 2;
        } else if ends_with(b0, k as usize, "ies") {
            truncate(b0, &mut k, 1, "i");
        } else if b0[(k - 1) as usize] != b's' {
            k -= 1;
        }
    }
    // Step 1b
    let mut flag = false;
    if ends_with(b0, k as usize, "eed") {
        if measure(b0, (k - 3) as usize) > 0 {
            k -= 1;
        }
    } else if (ends_with(b0, k as usize, "ed") && vowel_in_stem(b0, (k - 2) as usize))
        || (ends_with(b0, k as usize, "ing") && vowel_in_stem(b0, (k - 3) as usize))
