        } else if ends_with(b0, k as usize, "bl") {
            set_to(b0, &mut k, 2, "ble");
        } else if ends_with(b0, k as usize, "iz") {
            set_to(b0, &mut k, 2, "ize");
        } else if doublec(b0, k as usize) {
            let ch = b0[k as usize];
            if ch != b'l' && ch != b's' && ch != b'z' {
                k -= 1;
            }
        } else if measure(b0, k as usize) == 1 && cvc(b0, k as usize) {
            set_to(b0, &mut k, 0, "e");
        }
    }
    // Step 1c
    if ends_with(b0, k as usize, "y") && vowel_in_stem(b0, (k - 1) as usize) {
        b0[k as usize] = b'i';
    }
