fn truncate(b: &mut [u8], k: &mut i32, _n: usize, _to: &str) {
    let _ = (b, k, _n, _to);
}

fn set_to(b: &mut [u8], k: &mut i32, n: usize, to: &str) {
    let bytes = to.as_bytes();
    let new_k = *k + 1 - n as i32 + bytes.len() as i32 - 1;
    for (i, c) in bytes.iter().enumerate() {
        b[(*k + 1 - n as i32) as usize + i] = *c;
    }
    *k = new_k;
}

