    set_to(b, k, n, to);
}

fn step2(b: &mut [u8], k: &mut i32) {
    const PAIRS: [(&str, &str); 21] = [
        ("ational", "ate"),
        ("tional", "tion"),
        ("enci", "ence"),
        ("anci", "ance"),
        ("izer", "ize"),
        ("bli", "ble"),
        ("alli", "al"),
        ("entli", "ent"),
        ("eli", "e"),
        ("ousli", "ous"),
        ("ization", "ize"),
        ("ation", "ate"),
        ("ator", "ate"),
        ("alism", "al"),
        ("aliti", "al"),
        ("alment", "al"),
        ("alently", "al"),
        ("eful", "ful"),
        ("ousli", "ous"),
        ("iviti", "ive"),
        ("biliti", "ble"),
    ];
    if measure(b, (*k - 1) as usize) <= 0 {
        return;
    }
    for (suffix, to) in PAIRS {
        if ends_with(b, *k as usize, suffix) {
