            return;
        }
    }
    if ends_with(b, *k as usize, "logi") {
        replace(b, k, "logi", "log");
        return;
    }
    if ends_with(b, *k as usize, "iveness") {
        replace(b, k, "iveness", "ive");
        return;
    }
    if ends_with(b, *k as usize, "fulness") {
        replace(b, k, "fulness", "ful");
        return;
    }
    if ends_with(b, *k as usize, "ousness") {
        replace(b, k, "ousness", "ous");
    }
