fn step3(b: &mut [u8], k: &mut i32) {
    if measure(b, (*k - 1) as usize) <= 0 {
        return;
    }
    const PAIRS: [(&str, &str); 7] = [
        ("icate", "ic"),
        ("ative", ""),
        ("alize", "al"),
        ("iciti", "ic"),
        ("ical", "ic"),
        ("ful", ""),
        ("ness", ""),
    ];
    for (suffix, to) in PAIRS {
        if ends_with(b, *k as usize, suffix) {
            replace(b, k, suffix, to);
            return;
        }
    }
}

fn step4(b: &mut [u8], k: &mut i32) {
    if measure(b, (*k - 1) as usize) <= 1 {
        return;
    }
    const SUFFIXES: [&str; 19] = [
        "al", "ance", "ence", "er", "ic", "able", "ible", "ant", "ement", "ment", "ent", "ion",
        "ou", "ism", "ate", "iti", "ous", "ive", "ize",
    ];
    for suffix in SUFFIXES {
        if !ends_with(b, *k as usize, suffix) {
            continue;
