        if suffix == "ion" {
            let k1 = (*k - 3) as usize;
            if b[k1] == b's' || b[k1] == b't' {
                *k -= suffix.len() as i32;
                return;
            }
            continue;
        }
        if suffix == "ou" {
            continue;
        }
        *k -= suffix.len() as i32;
        return;
    }
}
