fn is_single_paragraph(events: &[Event]) -> bool {
    if !matches!(events.first(), Some(Event::Start(Tag::Paragraph))) {
        return false;
    }
    if !matches!(events.last(), Some(Event::End(Tag::Paragraph))) {
        return false;
    }
    let mut depth = 0;
    for ev in &events[1..events.len() - 1] {
        match ev {
            Event::Start(tag) => {
                if is_block_tag(tag) {
                    depth += 1;
                }
            }
            Event::End(tag) => {
                if is_block_tag(tag) {
                    depth -= 1;
                }
            }
            _ => {}
        }
        if depth > 0 {
            return false;
        }
    }
    true
}

