actions.command:
cd /workspace && python3 - <<'PY'
p='src/md/inline.rs'
s=open(p).read()
start=s.index("    /// Close emphasis, converting the unused delimiters into text.")
end=s.index("    fn footnote_ref(&mut self) -> Option<String> {")
new = '''    /// Close emphasis, converting the unused delimiters into text.
    fn process_emphasis(&mut self, stack_bottom: usize) {
        loop {
            let Some(closer_idx) = self.find_closer(stack_bottom) else {
                break;
            };
            let ch = self.delims[closer_idx].ch;
            let Some(opener_idx) = (stack_bottom..closer_idx)
                .rev()
                .find(|&i| self.delims[i].ch == ch && self.delims[i].can_open)
            else {
                // No opener: the closer becomes literal text.
                let d = self.delims.remove(closer_idx);
                self.insert_text(d.index, d.ch, d.count);
                continue;
            };
            let strong = self.delims[opener_idx].count >= 2 && self.delims[closer_idx].count >= 2;
            let use_count = if strong { 2 } else { 1 };
            let tag = if ch == '~' {
                Tag::Strikethrough
            } else if strong {
                Tag::Strong
            } else {
                Tag::Emphasis
            };
            let index = self.delims[opener_idx].index;
            self.out.insert(index, Event::Start(tag.clone()));
            for dd in self.delims.iter_mut() {
                if dd.index > index {
                    dd.index += 1;
                }
            }
            self.out.push(Event::End(tag));
            // Shrink the opener.
            self.delims[opener_idx].count -= use_count;
            if self.delims[opener_idx].count == 0 {
                self.delims.remove(opener_idx);
                for dd in self.delims.iter_mut() {
                    if dd.index > index {
                        dd.index -= 1;
                    }
                }
            } else {
                self.delims[opener_idx].can_open = false;
            }
            // Shrink the closer.
            let closer_idx = closer_idx - 1; // the opener may have been removed
            if closer_idx < self.delims.len() && self.delims[closer_idx].ch == ch {
                self.delims[closer_idx].count -= use_count;
                if self.delims[closer_idx].count == 0 {
                    self.delims.remove(closer_idx);
                } else {
                    self.delims[closer_idx].can_close = false;
                }
            }
        }
        // Any remaining delimiters become literal text.
        while let Some(d) = self.delims.pop() {
            self.insert_text(d.index, d.ch, d.count);
        }
    }

    fn insert_text(&mut self, index: usize, ch: char, count: usize) {
        let mut s = String::new();
        for _ in 0..count {
            s.push(ch);
        }
        let pos = index.min(self.out.len());
        self.out.insert(pos, Event::Text(s));
        for dd in self.delims.iter_mut() {
            if dd.index > pos {
                dd.index += 1;
            }
        }
    }

    /// The index of the topmost delimiter that can close emphasis.
    fn find_closer(&self, stack_bottom: usize) -> Option<usize> {
        for i in (stack_bottom..self.delims.len()).rev() {
            if self.delims[i].can_close {
                return Some(i);
            }
        }
        None
    }

'''
s = s[:start] + new + s[end:]
open(p,'w').write(s)
