/// The plain text of a heading, as used for the heading id and the search index.
pub fn heading_text(events: &[Event], refs: &[String], tags_as_spaces: bool) -> String {
    let mut out = String::new();
    let mut i = 0;
    while i < events.len() {
        match &events[i] {
            Event::Text(t) => out.push_str(t),
            Event::Code(c) => out.push_str(c),
            Event::FootnoteRef(label) => {
                if !tags_as_spaces {
                    let n = refs.iter().position(|l| l == label).map(|p| p + 1).unwrap_or(0);
                    out.push_str(&n.to_string());
                }
            }
            Event::Start(Tag::Image { .. }) => {
                if tags_as_spaces {
                    out.push(' ');
                }
                // The alt text.
                let mut j = i + 1;
                while j < events.len() {
                    match &events[j] {
                        Event::End(Tag::Image { .. }) => break,
                        Event::Text(t) => out.push_str(t),
                        _ => {}
                    }
                    j += 1;
                }
                if tags_as_spaces {
                    out.push(' ');
                }
                i = j;
                continue;
            }
            Event::Start(tag) | Event::End(tag) => {
                if matches!(
                    tag,
                    Tag::Emphasis | Tag::Strong | Tag::Strikethrough | Tag::Link { .. }
                ) && tags_as_spaces
