import re,json,sys
def load(p):
    s=open(p).read()
    i=s.index("JSON.parse('")+len("JSON.parse('")
    j=s.rindex("'));")
    raw=s[i:j]
    # The tool embeds the JSON in single quotes without escaping the double quotes
    # of the JSON, so rebuild by decoding the JS escapes then re-encoding.
    out=[]
    k=0
    while k < len(raw):
        if raw[k]=='\\' and k+1 < len(raw):
            out.append(raw[k:k+2]); k+=2; continue
        if raw[k]=="'":
            out.append("\\'"); k+=1; continue
        out.append(raw[k]); k+=1
    return json.loads(''.join(out))
a=load(sys.argv[1]); b=load(sys.argv[2])
def cmp(x,y,path=''):
    if type(x)!=type(y): print("TYPE", path, type(x).__name__, type(y).__name__); return
    if isinstance(x,dict):
        if set(x)!=set(y): print("KEYS", path, sorted(set(x)^set(y))); return
        for k in x: cmp(x[k],y[k],path+'.'+str(k))
    elif isinstance(x,list):
        if len(x)!=len(y): print("LEN", path, len(x), len(y)); return
        for i,(p,q) in enumerate(zip(x,y)): cmp(p,q,path+f'[{i}]')
    else:
        if x!=y: print("VAL", path, repr(x)[:150], "||", repr(y)[:150])
cmp(a,b)
print("(end)")
